\begin{enumerate}
    \item It should be emphasized that $\lambda_1$ \textit{a priori} must verify the bound $\lambda_1 < 1$ due to causality, as the speed of light is $1$ in our case. Therefore, our result saturates the regime of causality in this sense.

    \item We expect that our main result can be extended to the full regime $\kappa \in (0,1)$, which is of physical significance, after adapting a modified energy framework established in \cite{shkoller2019global}. For the sake of conciseness, we leave the details to interested readers.
\end{enumerate}

\label{lem:lambdaODE}
    The initial value problem \eqref{lambdaODEt}--\eqref{lambdaODEt_data} admits a unique, smooth solution $\lambda(t)$ for all $t \ge 0$. Moreover, there exist constants $\delta_0 > 0, C>0$ such that for any $\delta \in (0,\delta_0)$, the unique solution $\lambda(t)$ to \eqref{lambdaODEt}--\eqref{lambdaODEt_data} can be written in the form
\begin{equation}
    \label{lambdaasymp}
    \lambda(t) = a^\delta(t) + t\bar\lambda^\delta,
\end{equation}
where $\bar\lambda^\delta$ is time independent and
$$
|\bar\lambda^\delta - \lambda_1| \le C\delta,\quad |\partial_t^2 a^\delta| \le C\delta (1+t)^{-3\kappa-1}.
$$
Furthermore, consider the following time rescaling
$$
\frac{d\tau}{dt}= \frac{1}{\lambda(t)}.
$$
Then the following bounds hold:
\begin{equation}\label{est:lambdaasym}
C^{-1}e^{\bar\lambda^\delta \tau} \le \lambda(\tau) \le C e^{\bar\lambda^\delta \tau},\quad\tau\ge 0,
\end{equation}
and for $\bar{\lambda}_{\tau}^\delta := \frac{\partial_{\tau}\lambda}{\lambda}$, we have
\begin{equation}\label{est:ptlamt}
\left|\partial_\tau \bar{\lambda}_{\tau}^\delta\right| \le C\delta e^{-3\kappa \bar\lambda^\delta \tau}.
\end{equation}
Finally, $\lim_{\tau \to \infty}\bar{\lambda}_{\tau}^\delta = \bar\lambda^\delta$ and the following estimate holds:
\begin{equation}
    \label{est:difflamt}
    |\bar{\lambda}_{\tau}^\delta - \bar\lambda^\delta| \le \frac{C}{\kappa\bar\lambda^\delta}\delta e^{-3\kappa\lambda^\delta \tau}.
\end{equation}

\label{lem:u^0 cancellation}
    The following identities hold:
    \begin{align}\label{eq: u^0 cancellation}
        \begin{aligned}
            \left(V + \frac{\lambda'}{\lambda}z\right) \partial_zu^0 &+\lambda^{\frac{3}{2}\kappa + 1}\partial_t u^0 = \partial_s u^0 + V\partial_z u^0\\
            &=\lambda^{-3\kappa}(u^0)^3 \left(V+\frac{\lambda'}{\lambda}z\right)\left[\partial_s V+ V\partial_z V + \delta z + \frac{\lambda'}{\lambda}\left(1-\frac32\kappa\right)V\right].
        \end{aligned}
    \end{align}

We first address the first equality. Since $\frac{ds}{dt} = \lambda^{-\frac32\kappa - 1}$ and $\frac{dz}{dt} = -\frac{\lambda'}{\lambda}\lambda^{-\frac32\kappa - 1}z$, we have
    \begin{align*}
    \lambda^{\frac32\kappa + 1}\partial_t u^0 &= \lambda^{\frac32\kappa + 1}\left(\lambda^{-\frac32\kappa - 1}\partial_s u^0 - \frac{\lambda'}{\lambda}\lambda^{-\frac32\kappa - 1}z\partial_z u^0\right)\\
    &= \partial_s u^0 -\frac{\lambda'}{\lambda}z\partial_z u^0,
    \end{align*}
    and the first equality follows from the identity above.

    To address the second equality, by \eqref{u0}, a straightforward computation gives: 
    \begin{align}\label{p_z u^0}
    \partial_z u^0 &= (u^0)^3 \lambda^{-3\kappa}\left(V + \frac{\lambda'}{\lambda}z\right)\left(\partial_zV + \frac{\lambda'}{\lambda}\right),
\end{align}
and 
\begin{align}\label{p_s u^0 pre}
\begin{aligned}
    \partial_s u^0 &= -\frac12 (u^0)^3 \partial_s (u^0)^{-2} = \frac12 (u^0)^3 \partial_s\left(\lambda^{-3\kappa}\left(V + \frac{\lambda'}{\lambda}z\right)^2\right)\\
    &= (u^0)^3\lambda^{-3\kappa}\left(V + \frac{\lambda'}{\lambda}z\right)\left[\partial_s V - \frac32\kappa \frac{\lambda'}{\lambda} V + \left(\left(\frac{\lambda'}{\lambda}\right)' - \frac32\kappa \left(\frac{\lambda'}{\lambda}\right)^2\right)z\right]\\
    &= (u^0)^3\lambda^{-3\kappa}\left(V + \frac{\lambda'}{\lambda}z\right)\left[\partial_s V - \frac32\kappa \frac{\lambda'}{\lambda} V + \delta z\right],
    \end{aligned}
\end{align}
where the final equality follows from \eqref{ODE}. Then the second equality in \eqref{eq: u^0 cancellation} is proved after we combine \eqref{p_z u^0} and \eqref{p_s u^0 pre}.

\label{def: w}
    A smooth function $w: [0,1] \to \mathbb{R}^+$ is said to be an admissible weight function if $w$ possesses the following properties:
    \begin{enumerate}
        \item (Absence of interior vacuum) $w > 0$ on $[0,1)$  and $w(1) = 0$;
        \item (Physical vacuum boundary) $-\infty <w'(1) < 0$. Or equivalently, there exists a universal constant $C > 0$ such that
        $$
        \frac1C |r-1| \le w(r) \le C|r-1|,
        $$
        when $r$ is sufficiently close to $1$;
        \item (Regularity at the origin) $w^{(2k+1)}(0) = 0$ for all nonnegative integers $k$.
    \end{enumerate}
    Given $\delta > 0$ and an admissible weight $w$, we also define the 1-parameter family $w_\delta = \delta w$.

Let $\tau \ge \tau_0 \ge 0$ and $N \in \mathbb{N}$. We define
    \begin{equation}
        \label{defn:EN}
        E^N(\tau;\tau_0):= \sum_{i = 0}^N \sup_{\tau_0 \le \tau' \le \tau} \left[\delta^{-1}\lambda(\tau')^{3\kappa}\|\mathcal{D}_i \partial_{\tau} \Theta(\tau',\cdot)\|_i^2 + \|\mathcal{D}_i \Theta(\tau',\cdot)\|_i^2 + \|\mathcal{D}_{i+1}\Theta(\tau',\cdot)\|_{i+1}^2 \right].
    \end{equation}
    We also define
    \begin{equation}
        \label{defn:SN}
        S^N(\tau;\tau_0) := \sum_{i = 0}^{N-1}\int_{\tau_0}^{\tau} \|\mathcal{D}_i\partial_{\tau}^2\Theta(\tau',\cdot)\|_i^2 d\tau'.
    \end{equation}
    We will also use the following shorthand notations:
    $$
    E^N(\tau) := E^N(\tau;0),\quad S^N(\tau) := S^N(\tau;0).
    $$

\label{lem:elliptic term in theta}
    The following identity holds:
    \begin{align}\label{eq: elliptic term in theta}
        \begin{aligned}
            w^{-\frac{1}{\kappa}}\partial_{\zeta} \left(w^{1+\frac1\kappa}(\mathcal{F}^{-\kappa-1}-1)\right)=&
            -(1+\kappa)\mathcal{F}^{-\kappa-2}\xi^2w^{-\frac1\kappa}\partial_{\zeta}\left(w^{1+\frac1\kappa}\frac{1}{\zeta^2}\partial_{\zeta}(\zeta^3\theta)\right)\\
            &\underbrace{-2(1+\kappa)\mathcal{F}^{-\kappa-2}w\xi\zeta (\partial_{\zeta}\theta)^2}_{=R_1(\theta)}\\
            &+\frac{1+\kappa}{\kappa}w'\left(\mathcal{F}^{-\kappa-1}-1+(1+\kappa)\mathcal{F}^{-\kappa-2}\xi^2(\zeta\partial_{\zeta}\theta+3\theta)\right). 
        \end{aligned}
    \end{align}
    Moreover, the term $\frac{1+\kappa}{\kappa}w'\left(\mathcal{F}^{-\kappa-1}-1+(1+\kappa)\mathcal{F}^{-\kappa-2}\xi^2(\zeta\partial_{\zeta}\theta+3\theta)\right)$
    in \eqref{eq: elliptic term in theta} can be modified into
    \begin{align}\label{eq:cancellation pre}
        \begin{aligned}
            &\frac{1+\kappa}{\kappa}w'\left(\mathcal{F}^{-\kappa-1}-1+(1+\kappa)\mathcal{F}^{-\kappa-2}\xi^2(\zeta\partial_{\zeta}\theta+3\theta)\right)\\
            =  &\underbrace{\frac{(1+\kappa)^2}{\kappa}w'(3\theta^2 + 2\theta^3)}_{=R_2(\theta)}\\
            &+\underbrace{\frac{1+\kappa}{\kappa}w'\left(\mathcal{F}^{-\kappa-1}-1+ (1+\kappa)(\mathcal{F}-1)+(1+\kappa)(\mathcal{F}^{-\kappa-2}-1)\xi^2(\zeta\partial_{\zeta}\theta+3\theta)\right)}_{=R_3(\theta)}. 
        \end{aligned}
    \end{align}

We expand \eqref{ellipticpre} to obtain
    \begin{align*}
        \frac{1}{w^{\frac1\kappa}}\partial_\zeta \left(w^{1+\frac1\kappa} (\mathcal{F}^{-1-\kappa}-1)\right) = - (1+\kappa)w\mathcal{F}^{-\kappa-2}\partial_{\zeta} \mathcal{F}
        + \frac{1+\kappa}{\kappa}w'(\mathcal{F}^{-\kappa-1}-1). 
    \end{align*}
    From \eqref{eq: pz calF in xi}, we have
    \begin{align*}
        - (1+\kappa)w\mathcal{F}^{-\kappa-2}\partial_{\zeta} \mathcal{F} =& -(1+\kappa)\mathcal{F}^{-\kappa-2}\xi^2w^{-\frac1\kappa}\partial_{\zeta} \left(w^{1+\frac1\kappa}\frac{1}{\zeta^2}\partial_{\zeta} (\zeta^3 \theta)\right)\\
        -&2(1+\kappa)\mathcal{F}^{-\kappa-2}w\xi\zeta(\partial_{\zeta}\theta)^2\\
        +&\frac{(1+\kappa)^2}{\kappa}w'\mathcal{F}^{-\kappa-2}\xi^2(\zeta\partial_{\zeta}\theta+3\theta),
    \end{align*}
    which leads to \eqref{eq: elliptic term in theta}, where we also used $\partial_\zeta(\frac{1}{\zeta^2} \partial_\zeta(\zeta^3 \theta))=\zeta \partial_\zeta^2\theta +4 \partial_\zeta \theta$. Moreover, \eqref{eq:cancellation pre} follows from the identity
    \begin{align*}
        (\mathcal{F}-1) - \xi^2(\zeta\partial_{\zeta}\theta+3\theta)=-(3\theta^2+2\theta^3),
    \end{align*}
    which follows from a direct computation by setting $\xi=1+\theta$ in \eqref{eq: calF in xi}.

\label{lem:cancellation lemma theta}
Let $R_3(\theta)$ be defined in \eqref{eq:cancellation pre}. Then
    \begin{align}\label{eq:cancellation theta}
        \begin{aligned}
            D_{\zeta} R_3(\theta) &=\frac{1+\kappa}{\kappa}(D_{\zeta} w')\left(\mathcal{F}^{-\kappa-1}-1+ (1+\kappa)(\mathcal{F}-1)+(1+\kappa)(\mathcal{F}^{-\kappa-2}-1)\xi^2(\zeta\partial_{\zeta}\theta+3\theta)\right)\\
            &+ \frac{1+\kappa}{\kappa} w' \partial_{\zeta} \left(\mathcal{F}^{-\kappa-1}-1+ (1+\kappa)(\mathcal{F}-1)+(1+\kappa)(\mathcal{F}^{-\kappa-2}-1)\xi^2(\zeta\partial_{\zeta}\theta+3\theta)\right)
            \\&=\frac{1+\kappa}{\kappa}(D_{\zeta} w')\left(\mathcal{F}^{-\kappa-1}-1+ (1+\kappa)(\mathcal{F}-1)+(1+\kappa)(\mathcal{F}^{-\kappa-2}-1)\xi^2(\zeta\partial_{\zeta}\theta+3\theta)\right)\\
            &+\frac{1+\kappa}{\kappa}w'\bigg(6(1+\kappa)(\mathcal{F}^{-\kappa-2}-1)\xi\theta\partial_{\zeta}\theta
            -(\kappa+1)(\kappa+2)\mathcal{F}^{-\kappa-3}\xi^2\partial_{\zeta}\mathcal{F}(\zeta\partial_{\zeta}\theta+3\theta)\bigg). 
        \end{aligned}
    \end{align}

\label{lem: cancellation lemma M}
    Let $\mathfrak{M}(\Theta)$ be given by \eqref{def: M}. Then
    \begin{align}\label{def: M decomp}
        \mathfrak{M}(\Theta) = \mathfrak{M}_1+ \mathfrak{M}_2 + \mathfrak{M}_3, 
    \end{align}
    where 
    \begin{align}
        \begin{aligned}
            \mathfrak{M}_1 =& \frac{1+\kappa}{\kappa}D_{\zeta}\left((U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^2 w'\right)\Big(\mathcal{F}^{-\kappa-1}-1+ (1+\kappa)(\mathcal{F}-1)\\
            &+(1+\kappa)(\mathcal{F}^{-\kappa-2}-1)\left(1+\frac{\Theta}{\zeta}\right)^2D_{\zeta}\Theta\Big),\\
            \mathfrak{M}_2 =&\frac{6(1+\kappa)^2}{\kappa}\left((U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^2 w'\right)\Bigg(
            (\mathcal{F}^{-\kappa-2}-1)\left(1+\frac{\Theta}{\zeta}\right)\left(\frac{\Theta}{\zeta}\right)\partial_{\zeta}\left(\frac{\Theta}{\zeta}\right)\Bigg),\\
            \mathfrak{M}_3 =& (1+\kappa)w\left((\kappa+2)\mathcal{F}^{-\kappa-3}(\partial_{\zeta}\mathcal{F})(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\right)\partial_{\zeta}D_{\zeta}\Theta\\
           &-(1+\kappa)\left(\mathcal{F}^{-\kappa-2}\partial_{\zeta}\left((U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\right)\right)\left(\frac{1+\kappa}{\kappa}w'D_{\zeta}\Theta+w\partial_{\zeta}D_{\zeta}\Theta\right). 
        \end{aligned}
    \end{align}
 In other words, terms in $\mathfrak{M}(\Theta)$ that involve two spatial derivatives of $\Theta$ must be multiplied by $w$.

Invoking Lemma \ref{lem:cancellation lemma theta}, we have
        \begin{align}\label{eq: Dz frakR3Theta}
        \begin{aligned}
            D_{\zeta} \mathfrak{R}_3(\Theta) &=\frac{1+\kappa}{\kappa}D_{\zeta}\left((U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^2 w'\right)\Big(\mathcal{F}^{-\kappa-1}-1+ (1+\kappa)(\mathcal{F}-1)\\
            &+(1+\kappa)(\mathcal{F}^{-\kappa-2}-1)\left(1+\frac{\Theta}{\zeta}\right)^2D_{\zeta}\Theta\Big)\\
            &+\frac{1+\kappa}{\kappa}\left((U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^2 w'\right)\Bigg[
            6(1+\kappa)(\mathcal{F}^{-\kappa-2}-1)\left(1+\frac{\Theta}{\zeta}\right)\left(\frac{\Theta}{\zeta}\right)\partial_{\zeta}\left(\frac{\Theta}{\zeta}\right)\\
            &-(\kappa+1)(\kappa+2)\mathcal{F}^{-\kappa-3}\left(1+\frac{\Theta}{\zeta}\right)^2\partial_{\zeta}\mathcal{F}D_{\zeta}\Theta\Bigg]. 
            \end{aligned}
    \end{align}
   We will show that the term in the last line of \eqref{eq: Dz frakR3Theta} can be cancelled after expanding $(1+\kappa)\mathfrak{R}_4(\Theta)$. From definition of $\mathfrak{R}_4(\Theta)$ \eqref{def:R4}, we see that 
   \begin{align}\label{eq:pz frakR4}
       \begin{aligned}
           (1+\kappa)\mathfrak{R}_4(\Theta)=& (1+\kappa)\partial_{\zeta}\left(\mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\right)\left(-\frac{1+\kappa}{\kappa}w'D_{\zeta}\Theta-w\partial_{\zeta}D_{\zeta}\Theta\right)\\
           =&(1+\kappa)\left(-(\kappa+2)\mathcal{F}^{-\kappa-3}\partial_{\zeta}\mathcal{F}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\right)\left(-\frac{1+\kappa}{\kappa}w'D_{\zeta}\Theta-w\partial_{\zeta}D_{\zeta}\Theta\right)\\
           +&(1+\kappa)\left(\mathcal{F}^{-\kappa-2}\partial_{\zeta}\left((U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\right)\right)\left(-\frac{1+\kappa}{\kappa}w'D_{\zeta}\Theta-w\partial_{\zeta}D_{\zeta}\Theta\right).
       \end{aligned}
   \end{align}
   It can be seen that the first term of the second line of \eqref{eq:pz frakR4} cancels with the final term of \eqref{eq: Dz frakR3Theta}.

\label{lem:calF-1} We have
        \begin{align}\label{eq:calF-1}
        \mathcal{F}-1 = D_{\zeta}\left(\Theta + \frac{\Theta^2}{\zeta}\right) + \frac13D_{\zeta}\left(\frac{\Theta^3}{\zeta^2}\right).
        \end{align}

\label{prop:buildingblock}
    Let $i \ge 1$ be an integer, and consider $\bar P_i \in \bar{\mathcal{P}}_{i}$. Then the following identities hold:
    \begin{enumerate}
        \item ($\bar{\mathcal{P}}$ Derivative of Jacobian $\mathcal{F}$)
        \begin{equation}
            \label{PbarF}
            \bar P_i\mathcal{F} = P_{i+1}\Theta + \sum_{\substack{A_{1,2} \in \mathcal{P}_{l_1,l_2}\\ l_1 + l_2 = i+2,\\l_1,l_2 \le i+1}} c^{l_1,l_2}_i (A_1\Theta)(A_2\Theta) + \sum_{\substack{A_{1,2,3} \in \mathcal{P}_{l_1,l_2, l_3}\\ l_1 + l_2 + l_3 = i+2,\\l_1,l_2,l_3 \le i+1}} c^{l_1,l_2,l_3}_i(A_1\Theta)(A_2\Theta)(A_3\Theta),
        \end{equation}
        where $P_{i+1} = \bar P_i D_{\zeta} \in \mathcal{P}_{i+1}$ and $c^{l_1,l_2}_i,c^{l_1,l_2,l_3}_i$ are constants.

        \item ($\bar{\mathcal{P}}$ Derivative of the velocity component $U^0$)
        \begin{equation}
            \label{PbarU0}
            \begin{split}
            &\bar P_i (U^0)^{-2} = \sum_{\substack{A_{1,2}\in \mathcal{P}_{l_1,l_2},\\l_1+l_2 =i,\\l_1 \le i-1 }} c^{l_1,l_2}_{i,1} (A_1\partial_{\tau}\Theta)(A_2\partial_{\tau}\Theta) + \bar{\lambda}_{\tau}\sum_{\substack{A_{1,2}\in \mathcal{P}_{l_1,l_2},\\l_1+l_2 =i,\\l_1 \le i-1}} c^{l_1,l_2}_{i,2} (A_1\partial_{\tau}\Theta)(A_2\Theta)\\
            &+ \bar{\lambda}_{\tau}^2\sum_{\substack{A_{1,2}\in \mathcal{P}_{l_1,l_2},\\l_1+l_2 =i,\\l_1 \le i-1}} c^{l_1,l_2}_{i,3} (A_1\Theta)(A_2\Theta)+ \bar{\lambda}_{\tau}\sum_{\substack{A_{1,2}\in \mathcal{P}_{l_1,l_2},\\l_1+l_2 =i,\\l_1 \le i-1}} c^{l_1,l_2}_{i,4} (A_1\zeta)(A_2\partial_{\tau}\Theta + \bar{\lambda}_{\tau} A_2\Theta) - \bar{\lambda}_{\tau}^2 \bar P_{i}\zeta^2,
            \end{split}
        \end{equation}
        where $c^{l_1,l_2}_{i,j}$ are constants.

        In particular, we also have:
        \begin{equation}
            \label{PbarU0highest}
            \begin{split}
            &\bar{\mathcal{D}}_{i+1}(U^0)^{-2} = -2(\partial_{\tau} \Theta + \bar{\lambda}_{\tau}(\Theta + \zeta)) \mathcal{D}_{i+1}\partial_{\tau} \Theta +\sum_{\substack{A_{1,2}\in \mathcal{P}_{l_1,l_2},\\l_1+l_2 =i+1,\\l_1,l_2 \le i }} c^{l_1,l_2}_{i,1} (A_1\partial_{\tau}\Theta)(A_2\partial_{\tau}\Theta)\\
            &\quad+ \bar{\lambda}_{\tau}\sum_{\substack{A_{1,2}\in \mathcal{P}_{l_1,l_2},\\l_1+l_2 =i+1,\\l_1 \le i}} c^{l_1,l_2}_{i,2} (A_1\partial_{\tau}\Theta)(A_2\Theta) + \bar{\lambda}_{\tau}^2\sum_{\substack{A_{1,2}\in \mathcal{P}_{l_1,l_2},\\l_1+l_2 =i+1,\\l_1 \le i}} c^{l_1,l_2}_{i,3} (A_1\Theta)(A_2\Theta)\\
            &\quad + \bar{\lambda}_{\tau}\sum_{\substack{A_{1,2}\in \mathcal{P}_{l_1,l_2},\\l_1+l_2 =i+1,\\l_1,l_2 \le i}} c^{l_1,l_2}_{i,4} (A_1\zeta)(A_2\partial_{\tau}\Theta) + \bar{\lambda}_{\tau}\sum_{\substack{A_{1,2}\in \mathcal{P}_{l_1,l_2},\\l_1+l_2 =i+1,\\l_1 \le i}} c^{l_1,l_2}_{i,5} (A_1\zeta)(A_2\Theta)- \bar{\lambda}_{\tau}^2 \bar{\mathcal{D}}_{i+1} \zeta^2,
            \end{split}
        \end{equation}
        where $c^{l_1,l_2}_{i,j}$ are constants. 
    \end{enumerate}

\label{prop:buildingblockpowers}
    Let $i \ge 1$ be an integer, and consider $\bar P_i \in \bar{\mathcal{P}}_{i}$. Then the following statements hold:
    \begin{enumerate}
        \item For a given $\alpha > 0$, we can write $\bar P_i (\mathcal{F}^{-\alpha})$ as a linear combination of the following three types of terms:
        \begin{equation}
            \label{PbarF-atype1}
            \mathcal{F}^{-\alpha-k}\prod_{\substack{W_j \in \bar P_{i_j},\\\sum_{j=1}^k i_j = i}} (W_jD_{\zeta}\Theta),
        \end{equation}
        \begin{equation}
            \label{PbarF-atype2}
            \mathcal{F}^{-\alpha-k}\prod_{\substack{W_j^a \in \bar P_{i_j^a},\\ \sum_{a = 1}^2 \sum_{j=1}^k i_j^a = i}} (W_j^aD_{\zeta}\Theta),
        \end{equation}
        and
        \begin{equation}
            \label{PbarF-atype3}
            \mathcal{F}^{-\alpha-k}\prod_{\substack{W_j^b \in \bar P_{i_j^b},\\ \sum_{b = 1}^3 \sum_{j=1}^k i_j^b = i}} (W_j^bD_{\zeta}\Theta),
        \end{equation}
        for $k = 1,\hdots, i$.

        \item For a given $\alpha \neq 0$, $\bar P_i \left((U^0)^{\alpha}\right)$ can be written as a linear combination of terms in the following types:
        \begin{equation}
            \label{PbarU0type1}
            (U^0)^{\alpha + 2k} \prod_{\substack{W_j^a \in \bar{\mathcal{P}}_{i_j^a},\\\sum_{a=1}^2 \sum_{j=1}^k i_j^a = i}}(W_j^aH_j^a(\Theta)),
        \end{equation}
        \begin{equation}
            \label{PbarU0type2}
            (U^0)^{\alpha + 2k} \prod_{\substack{W_j^b \in \bar{\mathcal{P}}_{i_j^b},\\\sum_{b=1}^2 \sum_{j=1}^k i_j^b = i}} (W_j^1\zeta)(W_j^2H_j(\Theta)),
        \end{equation}
        and
        \begin{equation}
            \label{PbarU0type3}
            (U^0)^{\alpha + 2k} \prod_{\substack{W_j \in \bar{\mathcal{P}}_{i_j},\\\sum_{j=1}^k i_j = i}} \bar{\lambda}_{\tau}^2(W_j\zeta^2),
        \end{equation}
        where $k = 1,\hdots, i$, and $H_j^a(\Theta), H_j(\Theta)$ can either be $\partial_{\tau}\Theta$ or $\Theta$.
    \end{enumerate}

The representation of typical terms \eqref{PbarF-atype1}, \eqref{PbarF-atype2}, and \eqref{PbarF-atype3} follow from the chain rule \eqref{eq:chainrule} and then \eqref{PbarF}. As for expressions concerning $(U^0)^\alpha$, we note that the chain rule tells us that
        \begin{align*}
        \bar P_i((U^0)^\alpha) &= \bar P_i((U^0)^{-2})^{-\frac{\alpha}{2}} = \sum_{k=1}^i (U^0)^{-2\cdot (-\frac\alpha2 - k)}\prod_{\substack{W_j \in \bar{\mathcal{P}}_{i_j},\\\sum_{j=1}^k i_j = i}} c^{i_1,\hdots,i_k}_i (W_j(U^0)^{-2})\\
        &= \sum_{k=1}^i (U^0)^{\alpha + 2k}\prod_{\substack{W_j \in \bar{\mathcal{P}}_{i_j},\\\sum_{j=1}^k i_j = i}} c^{i_1,\hdots,i_k}_i (W_j(U^0)^{-2}).
        \end{align*}
        Then \eqref{PbarU0type1}, \eqref{PbarU0type2}, and \eqref{PbarU0type3} follow from \eqref{PbarU0}.

\label{prop:buildingblockpowersG}
    Let $i \ge 1$ be an integer, and consider $\bar P_i \in \bar{\mathcal{P}}_i$. The quantity $\bar P_i (\kappa \bar{\mathcal{G}})$ can be represented as a linear combination of the following types of terms: 
    \begin{subequations}\label{PbarGtype1}
    \begin{equation}
            \label{PbarGtype1a}
            (U^0)^{\kappa + 2k}\cdot\bar P\left((U^0)^{-\kappa}(0)(1+\delta \lambda^{-3\kappa}(0)w\mathcal{F}^{-\kappa}(0)\right) \prod_{\substack{V_j^a \in \mathcal{P}_{i_j^a},\\\sum_{a=1}^2 \sum_{j=1}^k i_j^a = n_2}}(V_j^aH_j^a(\Theta)),
    \end{equation}
    \begin{equation}
            \label{PbarGtype1b}
            (U^0)^{\kappa + 2k}\cdot\bar P\left((U^0)^{-\kappa}(0)(1+\delta \lambda^{-3\kappa}(0)w\mathcal{F}^{-\kappa}(0)\right) \prod_{\substack{V_j^b \in \mathcal{P}_{i_j^b},\\\sum_{b=1}^2 \sum_{j=1}^k i_j^b = n_2}} (V_j^b\zeta)(V_j^bH_j(\Theta)),
    \end{equation}
    and
    \begin{equation}
            \label{PbarGtype1c}
            (U^0)^{\kappa + 2k}\cdot\bar P\left((U^0)^{-\kappa}(0)(1+\delta \lambda^{-3\kappa}(0)w\mathcal{F}^{-\kappa}(0)\right) \prod_{\substack{W_j \in \bar{\mathcal{P}}_{i_j},\\\sum_{j=1}^k i_j = n_2}} \bar{\lambda}_{\tau}^2(W_j\zeta^2),
    \end{equation}
    \end{subequations}
    as well as
    \begin{subequations}\label{PbarGtype2}
    \begin{equation}
            \label{PbarGtype2a}
            \delta \lambda^{-3\kappa}\mathcal{F}^{-\kappa - 2k}\cdot\bar Pw \prod_{\substack{W_j \in \bar P_{i_j},\\\sum_{j=1}^k i_j = n_2}} (W_jD_{\zeta}\Theta),
    \end{equation}
    \begin{equation}
            \label{PbarGtype2b}
            \delta \lambda^{-3\kappa}\mathcal{F}^{-\kappa - 2k}\cdot\bar Pw \prod_{\substack{W_j^a \in \bar P_{i_j^a},\\ \sum_{a = 1}^2 \sum_{j=1}^k i_j^a = n_2}} (W_j^aD_{\zeta}\Theta),
    \end{equation}
    and
    \begin{equation}
            \label{PbarGtype2c}
            \delta \lambda^{-3\kappa}\mathcal{F}^{-\kappa - 2k}\cdot\bar Pw \prod_{\substack{W_j^b \in \bar P_{i_j^b},\\ \sum_{b = 1}^3 \sum_{j=1}^k i_j^b = n_2}} (W_j^bD_{\zeta}\Theta),
    \end{equation}
    \end{subequations}
    where $\bar P \in \bar{\mathcal{P}}_{n_1}$ and $k = 1,\hdots, n_2$. Here, $n_1, n_2$ are nonnegative integers such that $n_1 + n_2 = i$.

\label{prop:highestdtF}
    Let $i \ge 1$ be an integer. Then the following set of identities hold:\begin{equation}
        \label{eq:dtFsqpttheta}
        \mathcal{D}_i \left(\partial_{\tau}\Theta D_{\zeta}\partial_\tau\left(\frac{\Theta^2}{\zeta}\right) \right)= 2\partial_{\tau}\Theta \frac{\Theta}{\zeta}\mathcal{D}_{i+1} \partial_\tau \Theta + \sum_{\substack{A_{1,2,3} \in \mathcal{P}_{l_1,l_2,l_3}\\l_1 + l_2 + l_3 = i+1\\l_1, l_2 \le i}} c_i^{l_1,l_2,l_3}(A_1\partial_{\tau}\Theta)(A_2\partial_\tau\Theta)(A_3 \Theta),
    \end{equation}
    \begin{equation}
        \label{eq:dtFsqtheta}
        \mathcal{D}_i \left(\Theta D_{\zeta}\partial_\tau\left(\frac{\Theta^2}{\zeta}\right) \right)= 2\frac{\Theta^2}{\zeta}\mathcal{D}_{i+1} \partial_\tau \Theta + \sum_{\substack{A_{1,2,3} \in \mathcal{P}_{l_1,l_2,l_3}\\l_1 + l_2 + l_3 = i+1\\l_1 \le i}} c_i^{l_1,l_2,l_3}(A_1\partial_{\tau}\Theta)(A_2\Theta)(A_3 \Theta),
    \end{equation}
    \begin{equation}
        \label{eq:dtFsqzeta}
        \mathcal{D}_i \left(\zeta D_{\zeta}\partial_\tau\left(\frac{\Theta^2}{\zeta}\right) \right)= 2\Theta\mathcal{D}_{i+1} \partial_\tau \Theta + \sum_{\substack{A_{1,2} \in \mathcal{P}_{l_1,l_2}\\l_1 + l_2 = i+1\\l_1 \le i}} c_i^{l_1,l_2}(A_1\partial_{\tau}\Theta)(A_2\Theta).
    \end{equation}
    Similarly, the following identities hold:
    \begin{equation}
        \label{eq:dtFcupttheta}
        \begin{split}
        \mathcal{D}_i \left(\partial_{\tau}\Theta D_{\zeta}\partial_\tau\left(\frac{\Theta^3}{\zeta^2}\right)\right) &= 3\partial_{\tau}\Theta\left(\frac{\Theta}{\zeta}\right)^2\mathcal{D}_{i+1} \partial_\tau \Theta\\
        &\quad+ \sum_{\substack{A_{1,\hdots,4} \in \mathcal{P}_{l_1,\hdots,l_4}\\l_1 +\hdots+ l_4 = i+1\\l_1,l_2\le i}} c_i^{l_1,l_2,l_3,l_4}(A_1\partial_{\tau}\Theta)(A_2\partial_{\tau}\Theta)(A_3\Theta)(A_4\Theta),
        \end{split}
    \end{equation}
    \begin{equation}
        \label{eq:dtFcutheta}
        \begin{split}
        \mathcal{D}_i \left(\Theta D_{\zeta}\partial_\tau\left(\frac{\Theta^3}{\zeta^2}\right)\right) &= 3\Theta\left(\frac{\Theta}{\zeta}\right)^2\mathcal{D}_{i+1} \partial_\tau \Theta\\
        &\quad+ \sum_{\substack{A_{1,\hdots,4} \in \mathcal{P}_{l_1,\hdots,l_4}\\l_1 +\hdots+ l_4 = i+1\\l_1\le i}} c_i^{l_1,l_2,l_3,l_4}(A_1\partial_{\tau}\Theta)(A_2\Theta)(A_3\Theta)(A_4\Theta),
        \end{split}
    \end{equation}
    \begin{equation}
        \label{eq:dtFcuzeta}
        \mathcal{D}_i \left(\zeta D_{\zeta}\partial_\tau\left(\frac{\Theta^3}{\zeta^2}\right) \right)= 3\frac{\Theta^2}{\zeta}\mathcal{D}_{i+1} \partial_\tau \Theta + \sum_{\substack{A_{1,2,3} \in \mathcal{P}_{l_1,l_2,l_3}\\l_1 + l_2 + l_3 = i+1\\l_1 \le i}} c_i^{l_1,l_2,l_3}(A_1\partial_{\tau}\Theta)(A_2\Theta)(A_3 \Theta),
    \end{equation}
    where $c_i^{l_1,l_2,l_3}, c_i^{l_1,l_2,l_3,l_4}$ are constants.

We start with the proof of identity \eqref{eq:dtFsqpttheta}. First, we note that
    $$
    D_{\zeta}\partial_{\tau}\left(\frac{\Theta^2}{\zeta}\right) = 2D_{\zeta}\left(\partial_{\tau}\Theta\frac  \Theta\zeta\right) = 2\left(D_{\zeta}\partial_{\tau}\Theta \frac{\Theta}{\zeta} + \partial_{\tau}\Theta \partial_{\zeta}\left(\frac{\Theta}{\zeta}\right)\right).
    $$
    Using this piece of computation, we may write
    \begin{equation}\label{dtFaux1}
        \mathcal{D}_i \left(\partial_{\tau}\Theta D_{\zeta}\partial_\tau\left(\frac{\Theta^2}{\zeta}\right) \right) = 2\mathcal{D}_i\left(\partial_{\tau}\Theta \frac{\Theta}{\zeta} D_{\zeta}\partial_{\tau}\Theta\right) + 2\mathcal{D}_i\left((\partial_{\tau}\Theta)^2 \partial_{\zeta}\left(\frac{\Theta}{\zeta}\right)\right).
    \end{equation}
    For the first term in \eqref{dtFaux1}, we use Lemma \ref{lem:highestspatial} and the product rule \eqref{Pproduct} to write
    \begin{equation}
        \label{dtFaux2}
        \begin{split}
            2\mathcal{D}_i\left(\partial_{\tau}\Theta \frac{\Theta}{\zeta} D_{\zeta}\partial_{\tau}\Theta\right) &= 2\partial_{\tau}\Theta \frac{\Theta}{\zeta} \mathcal{D}_{i+1}\partial_{\tau}\Theta + \sum_{\substack{V_{1,2} \in \mathcal{P}_{l_1,l_2},\\l_1 + l_2 = i+1,\\l_1\le i}}V_1\left(\partial_{\tau}\Theta\frac{\Theta}{\zeta}\right) V_2\partial_{\tau}\Theta\\
            &= 2\partial_{\tau}\Theta \frac{\Theta}{\zeta} \mathcal{D}_{i+1}\partial_{\tau}\Theta + \sum_{\substack{A_{1,2,3} \in \mathcal{P}_{l_1,l_2,l_3}\\l_1 + l_2 + l_3 = i+1\\l_1, l_2 \le i}} c_i^{l_1,l_2,l_3}(A_1\partial_{\tau}\Theta)(A_2\partial_\tau\Theta)(A_3 \Theta)
        \end{split}
    \end{equation}
    For the second term in \eqref{dtFaux1}, we make the following crucial observation:
    $$
    (\partial_{\tau}\Theta)^2 \partial_{\zeta}\left(\frac{\Theta}{\zeta}\right) = \frac{(\partial_{\tau}\Theta)^2}{\zeta}\cdot \zeta\partial_{\zeta}\left(\frac{\Theta}{\zeta}\right) = \frac{(\partial_{\tau}\Theta)^2}{\zeta}\cdot\left(D_{\zeta}\Theta -3\frac{\Theta}{\zeta}\right).
    $$
    Hence, we may use the product rule \eqref{Pproduct} and subsequently \eqref{eq:thetasquare} to obtain
    \begin{equation}
        \label{dtFaux3}
        \begin{split}
            2\mathcal{D}_i\left((\partial_{\tau}\Theta)^2 \partial_{\zeta}\left(\frac{\Theta}{\zeta}\right)\right) &= \sum_{\substack{V_1\in\mathcal{P}_{l_1}, V_2 \in \bar{\mathcal{P}}_{l_2},\\l_1 + l_2 = i}} c^{l_1,l_2} V_1\left(\frac{(\partial_{\tau}\Theta)^2}{\zeta}\right)V_2\left(D_{\zeta}\Theta -3\frac{\Theta}{\zeta}\right)\\
            &= \sum_{\substack{A_{1,2,3} \in \mathcal{P}_{l_1,l_2,l_3}\\l_1 + l_2 + l_3 = i+1\\l_1, l_2 \le i}} c_i^{l_1,l_2,l_3}(A_1\partial_{\tau}\Theta)(A_2\partial_\tau\Theta)(A_3 \Theta).
        \end{split}
    \end{equation}
    Then \eqref{eq:dtFsqpttheta} follows from \eqref{dtFaux1}, \eqref{dtFaux2}, and \eqref{dtFaux3}. The identities \eqref{eq:dtFsqtheta} and \eqref{eq:dtFsqzeta} follow from very similar arguments. To prove \eqref{eq:dtFcupttheta}, \eqref{eq:dtFcutheta}, and \eqref{eq:dtFcuzeta}, we use the following identity:
    \begin{align*}
        D_{\zeta} \partial_{\tau} \left(\frac{\Theta^3}{\zeta^2}\right) &= 3\left[\left(\frac{\Theta}{\zeta}\right)^2 D_{\zeta}\partial_{\tau}\Theta + 2\frac{\Theta}{\zeta} \partial_{\tau}\Theta \partial_{\zeta}\left(\frac{\Theta}{\zeta}\right)\right].
    \end{align*}
    Then a similar argument to that proving \eqref{eq:dtFsqpttheta}, \eqref{eq:dtFsqtheta}, and \eqref{eq:dtFsqzeta} would yield the desired identities. We omit the tedious details here.

\label{prop:dtU0}
