Let $N \in \mathbb{N}$ and $\tau \ge 0$. We define
    \begin{equation}
        \label{defn:mfEN}
        \mathfrak{E}^N(\tau) := \sum_{j = 0}^N \mathfrak{E}_j(\tau),
    \end{equation}
    where
    \begin{equation}
        \label{defn:mfEj}
\begin{aligned}
    \mathfrak{E}_j(\tau):=&\frac{1}{2}\delta^{-1}\lambda^{3\kappa}\int_0^1 w^{\frac1\kappa+j}\zeta^2(1+\delta\lambda^{-3\kappa}w\mathcal{F}^{-\kappa}\mathcal{G}^{\kappa})|\mathcal{D}_j\partial_{\tau}\Theta|^2d\zeta \\
    &+ \frac{1}{2}\int_0^1 w^{\frac1\kappa+j}\zeta^2(1+\delta\lambda^{-3\kappa}w\mathcal{F}^{-\kappa}\mathcal{G}^{\kappa})|\mathcal{D}_j\Theta|^2d\zeta\\
    &+\frac{1+\kappa}{2}\int_0^1w^{1+\frac1\kappa+j}\zeta^2\left(\mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\right)|\mathcal{D}_{j+1}\Theta|^2d\zeta.
\end{aligned}
    \end{equation}

\label{def: damping}
    Let $N \in \mathbb{N}$ and $\tau \ge 0$. We define
    \begin{equation}\label{defn:damping}
        \mathfrak{D}^N(\tau) := \sum_{j=0}^N\mathfrak{D}_j(\tau), 
    \end{equation}
    where
    \begin{equation}
    \mathfrak{D}_j(\tau) := \left(1-\frac32\kappa\right)\bar{\lambda}_{\tau}\delta^{-1}\lambda^{3\kappa}\int_0^1 w^{\frac1\kappa+j}\zeta^2|\partial_{\tau}\mathcal{D}_j\Theta|^2d\zeta.
\end{equation}

Fixing $\tau \ge 0$, we define: 
\begin{equation}
    \label{defn:calEi}
    \mathcal{E}_i(\tau) :=\delta^{-1}\lambda(\tau)^{3\kappa}\|\mathcal{D}_i \partial_{\tau} \Theta(\tau,\cdot)\|_i^2 + \|\mathcal{D}_i \Theta(\tau,\cdot)\|_i^2 + \|\mathcal{D}_{i+1}\Theta(\tau,\cdot)\|_{i+1}^2,
\end{equation}
and
\begin{equation}
    \label{defn:calEN}
    \mathcal{E}^N(\tau) :=\sum_{i = 0}^N \mathcal{E}_i(\tau).
\end{equation}
We also define
\begin{equation}
    \label{defn:calSN}
    \mathcal{S}^N(\tau) := \sum_{j = 0}^{N-1} \|\mathcal{D}_j\partial_{\tau}^2\Theta(\tau,\cdot)\|_j^2.
\end{equation}

\label{assump: bootstrap}
Set $M_* > 0$ and $\epsilon \in (0,1)$ such that $M_* \epsilon < 1$. Let $\tau_* > 0$ be the maximal time such that the solution to \eqref{eq:momlagmainfull} exists on $[0,\tau_*]$ and verifies the following bounds:
\begin{subequations}
\begin{align}\label{bootstrap EN}
    E^N(\tau_*) \leq M_*\epsilon,
\end{align}
\begin{align}\label{bootstrap U0}
    \frac12 (1-\bar\lambda^2\zeta^2)\leq |U^0(\tau,\zeta)|^{-2} \leq \frac32 (1- \bar\lambda^2 \zeta^2), \quad (\tau,\zeta) \in [0,\tau_*]\times [0,1], 
\end{align}
and
    \begin{align} 
        \|\mathcal{F}(\tau)-1\|_{L^{\infty}}+\|\kappa\bar{\mathcal{G}}(\tau)-1\|_{L^{\infty}} \leq \frac{1}{100}, \quad \tau \in [0,\tau_*]. \label{bootstrap FG}
    \end{align}
\end{subequations}

\label{lem: induced bootstrap}
    Let $(\Theta,\partial_{\tau}\Theta)$ be a solution to \eqref{eq:momlagmainfull} on $[0,\tau_*]$ verifying the bootstrap assumptions. There exists a constant $\epsilon' > 0$, a constant $C > 0$ independent of $\epsilon'$ and $\delta$, such that for any $\epsilon \le \epsilon'$, $\delta \le \epsilon^\frac12$, and $\tau \in [0,\tau_*]$, the following estimates hold:

    \begin{enumerate}
    \item (Uniform bound for $U^0$) For any $k\neq 0$, there exists a constant $C(k,\bar\lambda) > 0$ such that
    \begin{equation}
        \label{U0k bd}
        \frac{1}{C(k,\bar\lambda)} \le (U^0)^k(\tau,\zeta) \le C(k,\bar\lambda),
    \end{equation}
    for all $\zeta \in [0,1]$.
    \item ($P_j$-differentiated $\Theta$) 
        \begin{align}\label{bootstrap Theta}
   \sum_{j=0}^{2}\|P_j \Theta(\tau)\|_{L^{\infty}}\leq \frac{1}{100}, 
    \end{align}
    where $P_j\in \mathcal{P}_j$ for $j=0,1,2$, 

    \item ($\tau$--derivatives of $\Theta$)     
        \begin{align} \sum_{j=0}^1\|\partial_{\tau}P_j\Theta(\tau)\|_{L^{\infty}}\leq \frac{1}{100}\lambda^{-\frac32 \kappa}, \quad \|\partial_{\tau}^2\Theta(\tau)\|_{L^{\infty}}\leq \frac{1}{50}\lambda^{-\frac32 \kappa}, \label{bootstrap ptau Theta}
                \end{align}

   \item ($\tau$-- and $\zeta$--derivatives of $U^0$)
      \begin{align}\label{est: induced bootstrap U^0}
     \|\partial_{\tau}(U^0(\tau))^{-2}\|_{L^{\infty}}\leq \frac{1}{10}\lambda^{-\frac{3}{2}\kappa},\quad \|\partial_{\zeta} (U^0(\tau))^{-2}\|_{L^{\infty}} \leq 100, 
    \end{align}

    \item ($\tau$-- and $\zeta$--derivatives of $\mathcal{F}$)
        \begin{align}\label{est: induced bootstrap F}
        \|\partial_{\tau} \mathcal{F}(\tau)\|_{L^{\infty}} \leq \frac{1}{10}\lambda^{-\frac32 \kappa},\quad \|\partial_{\zeta} \mathcal{F}(\tau)\|_{L^{\infty}}\leq \frac{1}{10},
    \end{align}

    \item ($\tau$-- and $\zeta$--derivative of $\mathcal{G}$)
        \begin{align}\label{est: induced bootstrap G}
    \|\partial_{\tau} \mathcal{G}(\tau)\|_{L^{\infty}}\leq \frac{1}{10}\kappa^{-1}\lambda^{-\frac{3}{2}\kappa},\quad
    \|\partial_{\zeta} \mathcal{G}(\tau)\|_{L^{\infty}}\leq 100\kappa^{-1}, 
    \end{align}

    \item (Smallness of $\mathcal{F}^{\kappa}-1$ and $\mathcal{G}^{\kappa}-1$)
    \begin{align}\label{smallness of calFGkk-1}
        \|\mathcal{F}^{\kappa}(\tau)-1\|_{L^{\infty}} \leq \frac14, \quad \|\mathcal{G}^{\kappa}(\tau)-1\|_{L^{\infty}} \leq \frac14.
    \end{align}
    \end{enumerate}

\label{lem:nonlinear}
    Let $(\Theta,\partial_{\tau}\Theta)$ be a solution to \eqref{eq:momlagmainfull} in $[0,\tau_*]$ verifying the bootstrap assumptions. Let $i \le N+1$, $i_1, i_2$ be integers such that $i_1 + i_2 \le i$, and $J_1, J_2 \ge 0$ be integers such that $J_1 + J_2 \ge 1$. Assume further that $H_k(\Theta) = \Theta$ or $\partial_{\tau}\Theta$. Then the following inequality holds for all $\tau \in [0,\tau_*]$:
    \begin{equation}\label{est:nonlinear}
        \int_0^1 w^{\frac1\kappa + i}\zeta^2 \prod_{\substack{A_k \in \mathcal{P}_{a_k},\\\sum_{k=1}^{J_1}a_k \le i_1}}(A_kH_k(\Theta))^2\cdot \prod_{\substack{B_k \in \bar{\mathcal{P}}_{b_k},\\\sum_{k=1}^{J_2}b_k \le i_2 -1}}(B_k P_1\Theta)^2 d\zeta \lesssim (\delta\lambda^{-3\kappa})^K (\mathcal{E}^N)^{J_1+J_2},
    \end{equation}
    where $a_k \le N$ whenever $H_{k}(\Theta) = \partial_{\tau}\Theta$, $P_1 \in \mathcal{P}_1$, and $K = |\{b\;|\; 1 \le b \le J_1, H_b(\Theta) = \partial_{\tau}\Theta\}|$.

\label{lem:nonlinear2}
    Let $(\Theta,\partial_{\tau}\Theta)$ be a solution to \eqref{eq:momlagmainfull} in $[0,\tau_*]$ verifying the bootstrap assumptions. Let $i \le N+1$, $i_1, i_2$ be integers such that $i_1 + i_2 \le i$, and $J_1, J_2, J_3 \ge 0$ be integers such that $J_1 + J_2 + J_3 \ge 1$. Assume further that $\bar H_k(\Theta) = \Theta$, $\partial_{\tau}\Theta$, or $\partial_{\tau}^2\Theta$. Then the following inequality holds for all $\tau \in [0,\tau_*]$:
    \begin{equation}\label{est:nonlinear2}
        \int_0^1 w^{\frac1\kappa + i}\zeta^2 \prod_{\substack{A_k \in \mathcal{P}_{a_k},\\\sum_{k=1}^{J_1+J_2}a_k \le i_1}}(A_k \bar H_k(\Theta))^2\cdot \prod_{\substack{B_k \in \bar{\mathcal{P}}_{b_k},\\\sum_{k=1}^{J_3}b_k \le i_2 -1}}(B_k P_1\Theta)^2 d\zeta \lesssim (\delta\lambda^{-3\kappa})^K (\mathcal{E}^N)^{J_1+J_3}(\mathcal{S}^N)^{J_2},
    \end{equation}
    where $a_k \le N$ whenever $\bar H_{k}(\Theta) = \partial_{\tau}\Theta$ and $a_k \le N-1$ whenever $\bar H_k(\Theta) = \partial_{\tau}^2\Theta$. Moreover, $P_1 \in \mathcal{P}_1$, $J_2 = |\{b\;|\; \bar H_b(\Theta) = \partial_{\tau}^2\Theta\}|$, and $K = |\{b\;|\; \bar H_b(\Theta) = \partial_{\tau}\Theta\}|$.

\label{prop:est M}
    Let $\mathfrak{M}$ be given by \eqref{def: M decomp}. Then
    \begin{equation}
        \|\bar{\mathcal{D}}_{i-1}\mathfrak{M}\|_i^2 \lesssim \mathcal{E}^N. 
    \end{equation}

\label{prop:est R}
    Let $\mathfrak{R}_1(\Theta)$ and $\mathfrak{R}_2(\Theta)$ be given by \eqref{def:R1} and \eqref{def:R2}, respectively. Then
    \begin{equation}
        \sum_{k=1}^2\|\mathcal{D}_{i}\mathfrak{R}_k\|_i^2 \lesssim (\mathcal{E}^N)^2. 
    \end{equation}

\label{prop:est C12}
    Let $\mathfrak{C}_k$, $k=1,2$ be given as \eqref{def:C1} and \eqref{def:C2}, respectively. Then
    \begin{align}\label{est: est C12}
        \sum_{k=1}^2\|\mathfrak{C}_k\|_i^2 \lesssim \mathcal{E}^N.
    \end{align}

\label{thm: pressure estimate}
Let 
\begin{align}\label{def:E7}
    E_{\text{pressure}} = \sum_{j=1}^2(\mathfrak{C}_j+\mathcal{D}_i\mathfrak{R}_j(\Theta)) + \bar{\mathcal{D}}_{i-1}\mathfrak{M}. 
\end{align}
Then, 
\begin{equation}\label{elliptic derivation}
\begin{aligned}
\mathcal{D}_i\left((U^0)^{-4}\left(1+\frac\Theta\zeta\right)^2\frac{1}{w^{\frac1\kappa}}\partial_\zeta \left(w^{1+\frac1\kappa} (\mathcal{F}^{-1-\kappa}-1)\right)\right)\\
= (1+\kappa)\mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\mathcal{L}_i\mathcal{D}_i\Theta + E_{\text{pressure}},
\end{aligned}
    \end{equation}
    where
    \begin{equation}
        E_{\text{pressure}} \lesssim \mathcal{E}^N.
    \end{equation}

\label{prop:est C}
    The high-order commutator $\mathfrak{C}_3$ verifies the following estimate: 
    \begin{align}\label{est: est C3}
        \|\mathfrak{C}_3\|_{i}^2 \lesssim \mathcal{S}^N+ \mathcal{E}^N\mathcal{S}^N+\delta\lambda^{-3\kappa}\mathcal{E}^N. 
    \end{align}
    Also, we have
    \begin{align}\label{est: mfI}
        \sum_{j=1}^5 \mathfrak{I}_j \lesssim \lambda^{-\frac32\kappa}\mathcal{E}^N. 
    \end{align}

\label{prop:DiE4}
    The following decomposition holds for any $\tau \in [0,\tau_*]$:
    \begin{equation}
        \label{est:DiE4}
        \begin{split}
        \mathcal{D}_i E_4 &= (\mathcal{C}^{E_4}_1+\mathcal{C}^{E_4}_2)w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta +\mathcal{C}^{E_4}_3w\mathcal{D}_i\partial_{\tau}^2\Theta + R_{4}^i,
        \end{split}
    \end{equation}
    where
    \begin{equation}\label{E4coeff}
    \begin{split}
    \mathcal{C}^{E_4}_1(\tau,\zeta) &:=-\frac{1+\kappa}{\kappa}(U^0)^{-2}\mathcal{F}^{-\kappa-1}\bar{\mathcal{G}}^{-1}\frac{\partial_{\tau}\Theta + \bar{\lambda}_{\tau}(\Theta +\zeta)}{\zeta}\left(1+\frac{\Theta}{\zeta}\right)^2,\\
    \mathcal{C}^{E_4}_2(\tau,\zeta) &:= -\frac{1+\kappa}{\kappa}\delta \lambda^{-3\kappa} w(U^0)^{-2}\mathcal{F}^{-2\kappa-1}\bar{\mathcal{G}}^{-2}\frac{\partial_{\tau}\Theta + \bar{\lambda}_{\tau}(\Theta +\zeta)}{\zeta}\left(1+\frac{\Theta}{\zeta}\right)^2,\\
    \mathcal{C}^{E_4}_3(\tau,\zeta) &:= -\frac{1+\kappa}{\kappa}\bar{\lambda}_{\tau} (U^0)^\kappa \mathcal{F}^{-\kappa}\bar{\mathcal{G}}^{-2}\left((U^0)^{-\kappa}(0)(1+ \delta\lambda^{-3\kappa}(0)w\mathcal{F}^{-\kappa}(0)) \right)(\partial_{\tau}\Theta + \bar{\lambda}_{\tau}(\Theta +\zeta))^2.
    \end{split}
    \end{equation}
    Moreover,
    \begin{equation}
        \label{est:R4i}
        \|R_{4}^i\|_i^2 \lesssim (\delta \lambda^{-3\kappa})^2+\delta \lambda^{-3\kappa}\mathcal{E}^N(\tau) + \mathcal{S}^N(\tau).
    \end{equation}

\label{lem:DiE41}
    The following decomposition holds for any $\tau \in [0,\tau_*]$:
    \begin{equation}
        \label{est:DiE41}
        \mathcal{D}_i E_{41} = \frac{1+\kappa}{\kappa}w(U^0)^{-2}\mathcal{F}^{-\kappa-1}\bar{\mathcal{G}}^{-1}(\partial_{\tau}\Theta + \bar{\lambda}_{\tau}(\Theta +\zeta))\left(1+\frac{\Theta}{\zeta}\right)^2\mathcal{D}_{i+1}\partial_{\tau}\Theta + R_{41}^i,
    \end{equation}
    where $R_{41}^i$ obeys the following bound:
    \begin{equation}
        \label{est:R41i}
        \|R_{41}^i\|_i^2 \lesssim \delta \lambda^{-3\kappa}\mathcal{E}^N(\tau).
    \end{equation}

\label{lem:DiE42}
    Assuming bootstrap assumptions, we may write
    \begin{equation}
        \label{est:DiE42}
        \begin{split}
        \mathcal{D}_i E_{42} &= \mathcal{C}^{E_{42}}_1\mathcal{D}_{i+1}\partial_{\tau}\Theta +\mathcal{C}^{E_{42}}_2\mathcal{D}_i\partial_{\tau}^2\Theta + R_{42}^i,
        \end{split}
    \end{equation}
    where
    \begin{align*}
    \mathcal{C}^{E_{42}}_1(\tau,\zeta) &:= \frac{1+\kappa}{\kappa}\delta \lambda^{-3\kappa} w^2(U^0)^{-2}\mathcal{F}^{-2\kappa-1}\bar{\mathcal{G}}^{-2}(\partial_{\tau}\Theta + \bar{\lambda}_{\tau}(\Theta +\zeta))\left(1+\frac{\Theta}{\zeta}\right)^2,\\
    \mathcal{C}^{E_{42}}_2(\tau,\zeta) &:= \frac{1+\kappa}{\kappa}\bar{\lambda}_{\tau} w(U^0)^\kappa \mathcal{F}^{-\kappa}\bar{\mathcal{G}}^{-2}\left((U^0)^{-\kappa}(0)(1+ \delta\lambda^{-3\kappa}(0)w\mathcal{F}^{-\kappa}(0)) \right)(\partial_{\tau}\Theta + \bar{\lambda}_{\tau}(\Theta +\zeta))^2.
    \end{align*}
    Moreover,
    \begin{equation}
        \label{est:R42i}
        \|R_{42}^i\|_i^2 \lesssim (\delta \lambda^{-3\kappa})^2+\delta \lambda^{-3\kappa}\mathcal{E}^N(\tau) + S^N(\tau).
    \end{equation}

\label{prop:DiE1}
    Let $E_1$ be given as in \eqref{mainerror}. Then for any $\tau \in [0,\tau_*]$,
    \begin{align}
        \mathcal{D}_i E_1 = \left((1+\kappa)\mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\mathcal{L}_i\mathcal{D}_i\Theta\right)(\mathcal{G}^{\kappa}-1) + R_1^i,
    \end{align}
    where 
    \begin{align*}
    R_1^i := \sum_{\substack{A\in \mathcal{P}_{l_A},\,B\in\bar{\mathcal{P}}_{l_B}\\l_A+l_B=i,\,l_B\geq 1}}A\left((U^0)^{-4}\left(1+\frac\Theta\zeta\right)^2\frac{1}{w^{\frac1\kappa}}\partial_\zeta \left(w^{1+\frac1\kappa} (\mathcal{F}^{-1-\kappa}-1)\right) \right) B(\mathcal{G}^\kappa - 1) + E_{\text{pressure}}(\mathcal{G}^{\kappa}-1), 
    \end{align*}
    where $E_{\text{pressure}}$ is defined in Theorem \ref{thm: pressure estimate}. Also,  $R_1^i$ verifies the following estimate:
    \begin{align}\label{est:R1i}
        \|R_1^i\|_i^2\lesssim (1+\mathcal{E}^N(0))\mathcal{E}^N(\tau). 
    \end{align}

\label{prop:DiE3}
    $\mathcal{D}_i E_3$ possesses the following representation: for any $\tau \in [0,\tau_*]$,
    \begin{equation}
        \label{est:DiE3}
        \begin{split}
        \mathcal{D}_iE_3 &=\mathcal{C}^{E_3}_1w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta + \mathcal{C}_2^{E_3}\mathcal{L}_i\mathcal{D}_i\Theta + \mathcal{C}^{E_3}_3w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta(0) + \mathcal{C}_4^{E_3}\mathcal{L}_i\mathcal{D}_i\Theta(0) + R_{3}^i,
        \end{split}
    \end{equation}
    where
    \begin{equation}\label{E3coeff}
    \begin{split}
    \mathcal{C}^{E_3}_1(\tau,\zeta) &:=-\frac{1+\kappa}{\kappa^2}(U^0)^{\kappa-2}\left(1+\frac\Theta\zeta\right)^2 \mathcal{F}^{-\kappa-1} \bar{\mathcal{G}}^{-2}\left[(U^0)^{-\kappa}(0) \left(1+\delta \lambda^{-3\kappa}(0) w\mathcal{F}^{-\kappa}(0)\right)\right]\\
        &\quad \times \frac{\partial_{\tau}\Theta + \bar{\lambda}_{\tau}(\Theta + \zeta)}{\zeta},\\
    \mathcal{C}^{E_3}_2(\tau,\zeta) &:= \frac{1+\kappa}{\kappa^2}\delta \lambda^{-3\kappa} w\mathcal{F}^{-2\kappa-2}\bar{\mathcal{G}}^{-2}\left[(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\right],\\
    \mathcal{C}^{E_3}_3(\tau,\zeta) &:= \frac{1+\kappa}{\kappa^2} (U^0)^{\kappa-4}(U^0(0))^{-\kappa+2}\left(1+\frac{\Theta}{\zeta}\right)^2 \mathcal{F}^{-\kappa-1}\bar{\mathcal{G}}^{-2}\left(1+\delta\lambda^{-3\kappa}(0)w\mathcal{F}^{-\kappa}(0)\right)\\
            &\quad \times \frac{\partial_{\tau}\Theta + \bar{\lambda}_{\tau}(\Theta + \zeta)}{\zeta},\\
    \mathcal{C}^{E_3}_4(\tau,\zeta) &:= -  \frac{1+\kappa}{\kappa^2} \delta \lambda(0)^{-3\kappa} w \mathcal{F}^{-\kappa-1}\mathcal{F}(0)^{-\kappa-1} (U^0)^{\kappa-4}(U^0)^{-\kappa}(0) \left(1+ \frac{\Theta}{\zeta}\right)^2\left(1+ \frac{\Theta(0)}{\zeta}\right)^2\bar{\mathcal{G}}^{-2}.
    \end{split}
    \end{equation}
    Moreover,
    \begin{equation}
        \label{est:R3i}
        \|R_3^i\|_i^2 \lesssim 1 + \mathcal{E}^N(\tau) + \mathcal{E}^N(0)
    \end{equation}

\label{lem:DiE31}
    For any $\tau \in [0,\tau_*]$, it holds that
    \begin{equation}
        \label{eq:DiE31}
        \begin{split}
        \mathcal{D}_i E_{31} &= -\frac{1+\kappa}{\kappa^2}w(U^0)^{\kappa-2}\left(1+\frac\Theta\zeta\right)^2 \mathcal{F}^{-\kappa-1} \bar{\mathcal{G}}^{-2}\left[(U^0)^{-\kappa}(0) \left(1+\delta \lambda^{-3\kappa}(0) w\mathcal{F}^{-\kappa}(0)\right)\right]\\
        &\quad \times (\partial_{\tau}\Theta + \bar{\lambda}_{\tau}(\Theta + \zeta))\mathcal{D}_{i+1}\partial_{\tau}\Theta + R_{31}^i,
        \end{split}
    \end{equation}
    where $R_{31}^i$ obeys the following bound:
    \begin{equation}
        \label{est:R31}
        \|R_{31}^i\|_i^2 \lesssim 1 + \mathcal{E}^N(\tau)
    \end{equation}

\label{lem:DiE33}
    For any $\tau \in [0,\tau_*]$, it holds that
    \begin{equation}
        \label{est:DiE33}
        \begin{split}
        \mathcal{D}_i E_{33} &= \frac{1+\kappa}{\kappa^2}\delta \lambda^{-3\kappa} w\mathcal{F}^{-2\kappa-2}\bar{\mathcal{G}}^{-2}\left[(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\mathcal{L}_i\mathcal{D}_i\Theta\right] + R_{33}^i,
        \end{split}
    \end{equation}
    where $R_{33}^i$ conforms to the following bound:
    \begin{equation}
        \label{est:R33}
        \|R_{33}^i\|_i^2 \lesssim (\delta \lambda^{-3\kappa})^2\mathcal{E}^N(\tau).
    \end{equation}

\label{lem:DiE34}
    For any $\tau \in [0,\tau_*]$, the following estimate holds:
    \begin{equation}
    \label{est:DiE34}
    \|\mathcal{D}_i E_{34}\|_i^2 \lesssim (\delta \lambda^{-3\kappa})^2 (1+ \mathcal{E}^N(\tau)).
    \end{equation}

\label{lem:DiE32}
    For any $\tau \in [0,\tau_*]$, it holds that
    \begin{equation}
        \label{est:DiE32}
        \begin{split}
            \mathcal{D}_i E_{32} &= \frac{1+\kappa}{\kappa^2} w(U^0)^{\kappa-4}(U^0(0))^{-\kappa+2}\left(1+\frac{\Theta}{\zeta}\right)^2 \mathcal{F}^{-\kappa-1}\bar{\mathcal{G}}^{-2}\left(1+\delta\lambda^{-3\kappa}(0)w\mathcal{F}^{-\kappa}(0)\right)\\
            &\quad \times (\partial_{\tau}\Theta + \bar{\lambda}_{\tau}(\Theta + \zeta))\mathcal{D}_{i+1}\partial_{\tau}\Theta(0)\\
            & -  \frac{1+\kappa}{\kappa^2} \delta \lambda(0)^{-3\kappa} w \mathcal{F}^{-\kappa-1}\mathcal{F}(0)^{-\kappa-1} (U^0)^{\kappa-4}(U^0)^{-\kappa}(0) \left(1+ \frac{\Theta}{\zeta}\right)^2\left(1+ \frac{\Theta(0)}{\zeta}\right)^2\bar{\mathcal{G}}^{-2}\mathcal{L}_i\mathcal{D}_i \Theta(0)\\
            &+ R_{32}^i,            
        \end{split}
    \end{equation}
    where $R_{32}^i$ obeys the following estimate:
    \begin{equation}
        \label{est:R32}
        \|R_{32}^i\|_i^2 \lesssim 1 + \mathcal{E}^N(\tau) + \mathcal{E}^N(0).
    \end{equation}

\label{prop:DiE2}
    The following estimate holds for any $\tau \in [0,\tau_*]$:
    \begin{equation}
        \label{est:DiE2}
        \|\mathcal{D}_iE_2\|_i^2 \lesssim 1 + \mathcal{E}^N(\tau).
    \end{equation}

\label{prop:DiE5+6}
    The following estimate holds for any $\tau \in [0,\tau_*]$:
    \begin{equation}
        \label{est:DiE5+6}
        \|\mathcal{D}_iE_5\|_i^2 + \|\mathcal{D}_iE_6\|_i^2 \lesssim 1 + \mathcal{E}^N(\tau).
    \end{equation}

\label{prop:SN}
    Let $(\Theta,\partial_{\tau}\Theta)$ be the solution to \eqref{eq:momlagmainfull} on $[0,\tau_*]$ verifying the bootstrap assumptions. Suppose that $\epsilon \le \epsilon'$ (where $\epsilon'$ is chosen in Lemma \ref{lem: induced bootstrap}), $\delta \le \epsilon^\frac12$, and time instances $\tau_1,\tau_2$ verifying $0\le \tau_1 \le \tau_2 \le \tau_*$. Then the following estimate holds:
    \begin{equation}
        \label{est:SN}
        S^N(\tau_2;\tau_1) \lesssim \delta^{\frac32}(\mathcal{E}^N(\tau_1) + \mathcal{E}^N(\tau_2) + \mathcal{E}^N(0)) + \delta^2 + \delta\int_{\tau_1}^{\tau_2} \lambda^{-3\kappa} \mathcal{E}^N(\tau) d\tau.
    \end{equation}

For fixed $i\in \{0,\cdots, N-1\}$, we obtain the following identity by testing \eqref{eq:highorder momlagmain} with $\delta \lambda^{-3\kappa}\partial_{\tau}^2\mathcal{D}_i\Theta$ with respect to the inner product $(\cdot,\cdot)_i$:
    \begin{equation}
        \label{eq:Sienergy}
        \begin{split}
        &\int_0^1 w^{\frac1\kappa + i}\zeta^2 \left(1+\delta \lambda^{-3\kappa}w\mathcal{F}^{-\kappa}\mathcal{G}^\kappa\right)|\partial_\tau^2 \mathcal{D}_i\Theta|^2 d\zeta\\
        &\quad + \bar{\lambda}_{\tau}\int_0^1 w^{\frac1\kappa + i}\zeta^2 \left(1+\delta \lambda^{-3\kappa}w\mathcal{F}^{-\kappa}\mathcal{G}^\kappa\right) (\partial_\tau \mathcal{D}_i\Theta)(\partial_{\tau}^2 \mathcal{D}_i \Theta) d\zeta\\
        &\quad + \delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i}\zeta^2\left(1+\delta \lambda^{-3\kappa}w\mathcal{F}^{-\kappa}\mathcal{G}^\kappa\right) (\mathcal{D}_i\Theta)(\partial_{\tau}^2 \mathcal{D}_i\Theta)d\zeta\\
        &\quad+(1+\kappa)\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i}\zeta^2\mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4 (\mathcal{L}_{i}\mathcal{D}_i\Theta)(\partial_{\tau}^2 \mathcal{D}_i \Theta)d\zeta\\
        &\quad + \delta \lambda^{-3\kappa}\bigg[\sum_{j=1}^3 (\mathfrak{C}_i,\partial_{\tau}^2\mathcal{D}_i \Theta)_i+\sum_{j=1}^2(\mathcal{D}_i \mathfrak{R}_j(\Theta),\partial_{\tau}^2\mathcal{D}_i \Theta)_i+ (\bar{\mathcal{D}}_{i-1}\mathfrak{M}(\Theta),\partial_{\tau}^2\mathcal{D}_i \Theta)_i\\
        &\quad
        + \sum_{j=1}^6(\mathcal{D}_iE_j,\partial_{\tau}^2\mathcal{D}_i \Theta)_i\bigg] = 0,
        \end{split}
    \end{equation}
    We then estimate \eqref{eq:Sienergy} on a term-by-term basis:
    \begin{enumerate}
            \item \textbf{First term on the LHS of \eqref{eq:Sienergy}.} By bootstrap assumptions on $\mathcal{F}, \bar{\mathcal{G}}$, and the fact that $|\bar{\lambda}_{\tau}-\bar\lambda| \lesssim \delta$ in view of the estimate \eqref{est:difflamt}, we immediately have $|\delta \lambda^{-3\kappa}w\mathcal{F}^{-\kappa}\mathcal{G}^\kappa|_{L^\infty} \le \frac12$ after choosing $\delta \le \epsilon^{\frac12} \ll 1$. We then obtain the following coercivity estimate:
        \begin{equation}
            \label{est:line1}
            \int_0^1 w^{\frac1\kappa + i}\zeta^2 \left(1+\delta \lambda^{-3\kappa}w\mathcal{F}^{-\kappa}\mathcal{G}^\kappa\right)|\partial_\tau^2 \mathcal{D}_i\Theta|^2 d\zeta \ge \frac12 \|\partial_{\tau}^2 \mathcal{D}_i \Theta\|_i^2.
        \end{equation}

        \item \textbf{Second and third terms on the LHS of \eqref{eq:Sienergy}.} Once again, by using the bounds $|\delta \lambda^{-3\kappa}w\mathcal{F}^{-\kappa}\mathcal{G}^\kappa|_{L^\infty} \le \frac12$ and $|\bar{\lambda}_{\tau}| \lesssim 1$, a straightforward application of Cauchy-Schwarz inequality yields that
        \begin{equation}
            \label{est:line2+3}
            \begin{split}
                &\left|\bar{\lambda}_{\tau}\int_0^1 w^{\frac1\kappa + i}\zeta^2 \left(1+\delta \lambda^{-3\kappa}w\mathcal{F}^{-\kappa}\mathcal{G}^\kappa\right) (\partial_\tau \mathcal{D}_i\Theta)(\partial_{\tau}^2 \mathcal{D}_i \Theta) d\zeta\right|\\
        &\quad + \left|\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i}\zeta^2\left(1+\delta \lambda^{-3\kappa}w\mathcal{F}^{-\kappa}\mathcal{G}^\kappa\right) (\mathcal{D}_i\Theta)(\partial_{\tau}^2 \mathcal{D}_i\Theta)d\zeta\right|\\
        &\lesssim \|\partial_{\tau}\mathcal{D}_i \Theta\|_i \|\partial_{\tau}^2 \mathcal{D}_i \Theta\|_i + \delta \lambda^{-3\kappa} \|\mathcal{D}_i\Theta\|_i \|\partial_{\tau}^2\mathcal{D}_i\Theta\|_i\\
        &\lesssim \mathring{\epsilon}\|\partial_{\tau}^2\mathcal{D}_i\Theta\|_i^2 + C(\mathring{\epsilon})\delta\lambda^{-3\kappa}\mathcal{E}^N(\tau),
            \end{split}
        \end{equation}
        where $\mathring{\epsilon} > 0$ is a small constant to be determined. We also used $\delta \lambda^{-3\kappa} \ll 1$ in the final inequality above.

        \item \textbf{Fourth term on the LHS of \eqref{eq:Sienergy}.} Let us denote
        $$
        g(\tau,\zeta) := \mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4 .
        $$
        By definition of $\mathcal{L}_i\mathcal{D}_i$, we integrate by parts and obtain the following:
        \begin{equation}\label{eq:line4}
        \begin{split}
            &(1+\kappa)\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i}\zeta^2\mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4 (\mathcal{L}_{i}\mathcal{D}_i\Theta)(\partial_{\tau}^2 \mathcal{D}_i \Theta)d\zeta\\
            &\quad = (1+\kappa)\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 g \mathcal{D}_{i+1}\Theta \partial_{\tau}^2 \mathcal{D}_{i+1}\Theta d\zeta\\
            &\quad\quad +(1+\kappa)\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \partial_{\zeta} g \mathcal{D}_{i+1}\Theta \partial_{\tau}^2 \mathcal{D}_i\Theta d\zeta\\
            &\quad = (1+\kappa)\frac{d}{d\tau}\left[\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 g \mathcal{D}_{i+1}\Theta \partial_{\tau}\mathcal{D}_{i+1}\Theta d\zeta\right]\\
            &\quad\quad +3\kappa(1+\kappa)\delta \lambda^{-3\kappa}\bar{\lambda}_{\tau} \int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 g \mathcal{D}_{i+1}\Theta \partial_{\tau}\mathcal{D}_{i+1}\Theta d\zeta\\
            &\quad\quad -(1+\kappa)\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 (\partial_{\tau} g) \mathcal{D}_{i+1}\Theta \partial_{\tau}\mathcal{D}_{i+1}\Theta d\zeta\\
            &\quad\quad -(1+\kappa)\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 g |\partial_{\tau}\mathcal{D}_{i+1}\Theta|^2 d\zeta\\
            &\quad\quad +(1+\kappa)\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \partial_{\zeta} g \mathcal{D}_{i+1}\Theta \partial_{\tau}^2 \mathcal{D}_i\Theta d\zeta.
            \end{split}
        \end{equation}
        By bootstrap assumptions, it is clear that
        $$
        \|g\|_{L^\infty} + \|\partial_{\tau} g\|_{L^\infty} + \|\partial_{\zeta} g\|_{L^\infty} \lesssim 1.
        $$
        Since $i \le N-1$, we have the following bounds:
        \begin{equation}
            \label{est:line4}
            \begin{split}
                \left|3\kappa(1+\kappa)\delta \lambda^{-3\kappa}\bar{\lambda}_{\tau} \int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 g \mathcal{D}_{i+1}\Theta \partial_{\tau}\mathcal{D}_{i+1}\Theta d\zeta\right| &\lesssim (\delta\lambda^{-3\kappa})^{\frac32} \mathcal{E}^N(\tau),\\
                \left|(1+\kappa)\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 (\partial_{\tau} g) \mathcal{D}_{i+1}\Theta \partial_{\tau}\mathcal{D}_{i+1}\Theta d\zeta\right| &\lesssim (\delta\lambda^{-3\kappa})^{\frac32} \mathcal{E}^N(\tau),\\
                \left|(1+\kappa)\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 g |\partial_{\tau}\mathcal{D}_{i+1}\Theta|^2 d\zeta\right| &\lesssim (\delta\lambda^{-3\kappa})^2 \mathcal{E}^N(\tau),\\
                \left|(1+\kappa)\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \partial_{\zeta} g \mathcal{D}_{i+1}\Theta \partial_{\tau}^2 \mathcal{D}_i\Theta d\zeta\right| &\lesssim \mathring{\epsilon} \|\partial_{\tau}^2 \mathcal{D}_i\Theta\|_i^2 + C(\mathring{\epsilon})(\delta \lambda^{-3\kappa})^2\mathcal{E}^N(\tau),
            \end{split}
        \end{equation}
        where $\mathring{\epsilon} > 0$ is a small constant to be determined later.

        \item \textbf{Fifth term on the LHS of \eqref{eq:Sienergy}.} Invoking Theorem \ref{thm: pressure estimate} as well as the estimate \eqref{est: est C3}, a direct application of Cauchy-Schwarz inequality gives:
        \begin{equation}
            \label{est:line5}
            \begin{split}
            &\left|\delta \lambda^{-3\kappa}\bigg[\sum_{j=1}^3 (\mathfrak{C}_i,\partial_{\tau}^2\mathcal{D}_i \Theta)_i+\mathcal{D}_i\sum_{j=1}^2(\mathfrak{R}_j(\Theta),\partial_{\tau}^2\mathcal{D}_i \Theta)_i+ (\bar{\mathcal{D}}_{i-1}\mathfrak{M}(\Theta),\partial_{\tau}^2\mathcal{D}_i \Theta)_i\bigg]\right|\\
            &\quad \le \delta \lambda^{-3\kappa}\left(\sum_{j=1}^3 \|\mathfrak{C}_j\|_i + \sum_{j=1}^2 \|\mathcal{D}_i \mathfrak{R}_j(\Theta)\|_i + \|\bar{\mathcal{D}}_{i-1}\mathfrak{M}(\Theta)\|_i\right)\|\partial_{\tau}^2 \mathcal{D}_i\Theta\|_i\\
            &\quad \lesssim \delta \lambda^{-3\kappa} (\mathcal{E}^N(\tau)^\frac12 + \mathcal{S}^N(\tau)^\frac12)\|\partial_{\tau}^2 \mathcal{D}_i\Theta\|_i\\
            &\quad \lesssim \delta\lambda^{-3\kappa} S^N(\tau)^\frac12\|\partial_{\tau}^2 \mathcal{D}_i\Theta\|_i + \mathring{\epsilon}\|\partial_{\tau}^2 \mathcal{D}_i\Theta\|_i^2 + C(\mathring{\epsilon})(\delta\lambda^{-3\kappa})^2 \mathcal{E}^N(\tau).
            \end{split}
        \end{equation}

        \item \textbf{Sixth term on the LHS of \eqref{eq:Sienergy}.} When $j = 2,5,6$, we invoke Proposition \ref{prop:DiE2}, Proposition \ref{prop:DiE5+6} and directly apply Cauchy-Schwarz inequality to obtain:
        \begin{equation}\label{line6aux1}
        \begin{split}
        |\delta\lambda^{-3\kappa}(\mathcal{D}_i E_j , \partial_{\tau}^2\mathcal{D}_i\Theta)_i| &\le \delta\lambda^{-3\kappa}(1+(\mathcal{E}^N(\tau))^{\frac12})\|\partial_{\tau}^2 \mathcal{D}_i\Theta\|_i\\
        &\le \mathring{\epsilon}\|\partial_{\tau}^2 \mathcal{D}_i\Theta\|_i^2 + C(\mathring{\epsilon})(\delta\lambda^{-3\kappa})^2,
        \end{split}
        \end{equation}
        where $\mathring{\epsilon} > 0$ is a small constant to be determined later. We also used that $\mathcal{E}^N(\tau) < 1$ in the bootstrap regime.

        When $j = 1$, we invoke Proposition \ref{prop:DiE1} to have
        \begin{align*}
        \delta\lambda^{-3\kappa}(\mathcal{D}_i E_1,\partial_{\tau}^2\mathcal{D}_i\Theta)_i &= \delta\lambda^{-3\kappa}\left(\left((1+\kappa)\mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\mathcal{L}_i\mathcal{D}_i\Theta\right)(\mathcal{G}^{\kappa}-1), \partial_{\tau}^2\mathcal{D}_i\Theta\right)_i\\
        &\quad +\delta\lambda^{-3\kappa}(R_1^i, \partial_{\tau}^2\mathcal{D}_i\Theta)_i
        \end{align*}
        The second term above can be estimated straightforwardly using \eqref{est:R1i}:
        \begin{equation}
            \label{line6aux2}
            |\delta\lambda^{-3\kappa}(R_1^i, \partial_{\tau}^2\mathcal{D}_i\Theta)_i| \lesssim \mathring{\epsilon}\|\partial_{\tau}^2 \mathcal{D}_i\Theta\|_i^2 + C(\mathring{\epsilon})(\delta\lambda^{-3\kappa})^2 (1+\mathcal{E}^N(0))\mathcal{E}^N(\tau).
        \end{equation}
        The first term above can be treated in an identical way to how we deal with the fourth line of \eqref{eq:Sienergy}, now with
        $$
        g(\tau,\zeta) = \mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4(\mathcal{G}^{\kappa}-1).
        $$
        By bootstrap assumptions and Lemma \ref{lem: induced bootstrap}, we also have
        $$
        \|g\|_{L^\infty} + \|\partial_{\tau} g\|_{L^\infty} + \|\partial_{\zeta} g\|_{L^\infty} \lesssim 1.
        $$
        Then by an argument which is similar to how we treat the fourth line of \eqref{eq:Sienergy}, we may write
        \begin{equation}
            \label{line6aux3}
            \begin{split}
            &\delta\lambda^{-3\kappa}\left(\left((1+\kappa)\mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\mathcal{L}_i\mathcal{D}_i\Theta\right)(\mathcal{G}^{\kappa}-1), \partial_{\tau}^2\mathcal{D}_i\Theta\right)_i\\
            &\quad = (1+\kappa)\frac{d}{d\tau}\left[\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2\left(\mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4(\mathcal{G}^{\kappa}-1)\right)\mathcal{D}_{i+1}\Theta \partial_{\tau}\mathcal{D}_{i+1}\Theta d\zeta\right]\\
            &\quad\quad + I_{E_1},
            \end{split}
        \end{equation}
        where $|I_{E_1}| \lesssim \mathring{\epsilon} \|\partial_{\tau}^2 \mathcal{D}_i\Theta\|_i^2 + C(\mathring{\epsilon})(\delta \lambda^{-3\kappa})^2\mathcal{E}^N(\tau) + (\delta \lambda^{-3\kappa})^\frac32\mathcal{E}^N(\tau)$ for $\mathring{\epsilon} > 0$ a small constant.

        When $j = 3$, we invoke Proposition \ref{prop:DiE3} to write
        \begin{align*}
            \delta\lambda^{-3\kappa}(\mathcal{D}_i E_3, \partial_{\tau}^2 \mathcal{D}_i\Theta)_i &= \delta\lambda^{-3\kappa}(\mathcal{C}^{E_3}_1w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta, \partial_{\tau}^2 \mathcal{D}_i\Theta)_i + \delta\lambda^{-3\kappa}(\mathcal{C}_2^{E_3}\mathcal{L}_i\mathcal{D}_i\Theta, \partial_{\tau}^2 \mathcal{D}_i\Theta)_i\\
            &\quad + \delta\lambda^{-3\kappa}(\mathcal{C}^{E_3}_3w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta(0), \partial_{\tau}^2 \mathcal{D}_i\Theta)_i + \delta\lambda^{-3\kappa}(\mathcal{C}_4^{E_3}\mathcal{L}_i\mathcal{D}_i\Theta(0), \partial_{\tau}^2 \mathcal{D}_i\Theta)_i\\
            &\quad + \delta\lambda^{-3\kappa}(R_{3}^i, \partial_{\tau}^2 \mathcal{D}_i\Theta)_i,
        \end{align*}
        where we recall that the coefficients $\mathcal{C}_k^{E_3}$, $k = 1,2,3,4$ are given in \eqref{E3coeff}. 
        \begin{enumerate}
            \item \textit{Bound for $\delta\lambda^{-3\kappa}(\mathcal{C}^{E_3}_1w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta, \partial_{\tau}^2 \mathcal{D}_i\Theta)_i$.} By bootstrap assumptions and Lemma \ref{lem: induced bootstrap}, one observes that $\|\mathcal{C}_1^{E_3}\|_{L^\infty} \lesssim 1$. Since $i \le N-1$, we have
            \begin{equation}
                \label{line6aux4}
                \begin{split}
                |\delta\lambda^{-3\kappa}(\mathcal{C}^{E_3}_1w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta, \partial_{\tau}^2 \mathcal{D}_i\Theta)_i| &\le \delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^3 |\mathcal{C}_1^{E_3}\mathcal{D}_{i+1}\partial_{\tau}\Theta\partial_{\tau}^2 \mathcal{D}_i\Theta| d\zeta\\
                &\lesssim (\delta\lambda^{-3\kappa})^\frac32\mathcal{E}^N(\tau)^\frac12\|\partial_{\tau}^2 \mathcal{D}_i\Theta\|_i\\
                &\lesssim \mathring{\epsilon}\|\partial_{\tau}^2 \mathcal{D}_i\Theta\|_i^2 + C(\mathring{\epsilon})(\delta\lambda^{-3\kappa})^3\mathcal{E}^N(\tau).
                \end{split}
            \end{equation}
            \item \textit{Bound for $\delta\lambda^{-3\kappa}(\mathcal{C}_2^{E_3}\mathcal{L}_i\mathcal{D}_i\Theta, \partial_{\tau}^2 \mathcal{D}_i\Theta)_i$.} This term can be treated in an almost identical way to that treating the fourth line of \eqref{eq:Sienergy}. Note that by bootstrap assumptions and Lemma \ref{lem: induced bootstrap}, we have $\|\mathcal{C}_2^{E_2}\|_{L^\infty} + \|\partial_{\zeta} \mathcal{C}_2^{E_2}\|_{L^\infty} +\|\partial_{\tau} \mathcal{C}_2^{E_2}\|_{L^\infty}  \lesssim \delta\lambda^{-3\kappa}.$ Then we can write
            \begin{equation}
                \label{line6aux5}
                \begin{split}
                \delta\lambda^{-3\kappa}(\mathcal{C}_2^{E_3}\mathcal{L}_i\mathcal{D}_i\Theta, \partial_{\tau}^2 \mathcal{D}_i\Theta)_i = \frac{d}{d\tau}\left[\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \mathcal{C}_2^{E_3} \mathcal{D}_{i+1}\Theta \partial_{\tau}\mathcal{D}_{i+1}\Theta d\zeta\right]+ I_{E_3}^1,
                \end{split}
            \end{equation}
            where $I_{E_3}^1$ obeys the bound
            $$
            |I_{E_3}^1| \lesssim \mathring{\epsilon} \|\partial_{\tau}^2 \mathcal{D}_i\Theta\|_i^2 + C(\mathring{\epsilon})(\delta \lambda^{-3\kappa})^4\mathcal{E}^N(\tau) + (\delta \lambda^{-3\kappa})^\frac52\mathcal{E}^N(\tau)
            $$
            for $\mathring{\epsilon} > 0$ a small constant.

            \item \textit{Bound for $\delta\lambda^{-3\kappa}(\mathcal{C}^{E_3}_3w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta(0), \partial_{\tau}^2 \mathcal{D}_i\Theta)_i$.} This term can be estimated in an identical way to item (a) above. Due to $\|\mathcal{C}_3^{E_3}\|_{L^\infty} \lesssim 1$ by bootstrap assumptions and Lemma \ref{lem: induced bootstrap}, we can bound:
            \begin{equation}
                \label{line6aux6}
                |\delta\lambda^{-3\kappa}(\mathcal{C}^{E_3}_3w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta(0), \partial_{\tau}^2 \mathcal{D}_i\Theta)_i| \lesssim \mathring{\epsilon}\|\partial_{\tau}^2 \mathcal{D}_i\Theta\|_i^2 + C(\mathring{\epsilon})\delta^3\lambda^{-6\kappa}\mathcal{E}^N(0),
            \end{equation}
            for $\mathring{\epsilon} > 0$ a small constant.

            \item \textit{Bound for $\delta\lambda^{-3\kappa}(\mathcal{C}_4^{E_3}\mathcal{L}_i\mathcal{D}_i\Theta(0), \partial_{\tau}^2 \mathcal{D}_i\Theta)_i$.} Emulating the computation \eqref{eq:line4}, we realize that
            \begin{align*}
                &\delta\lambda^{-3\kappa}(\mathcal{C}_4^{E_3}\mathcal{L}_i\mathcal{D}_i\Theta(0), \partial_{\tau}^2 \mathcal{D}_i\Theta)_i = \frac{d}{d\tau}\left[\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \mathcal{C}_4^{E_3} \mathcal{D}_{i+1}\Theta(0)\partial_{\tau} \mathcal{D}_{i+1}\Theta d\zeta\right]\\
                &\quad + 3\kappa \delta \lambda^{-3\kappa}\bar{\lambda}_{\tau} \int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \mathcal{C}_4^{E_3} \mathcal{D}_{i+1}\Theta(0)\partial_{\tau}\mathcal{D}_{i+1}\Theta d\zeta\\
                &\quad - \delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 (\partial_{\tau} \mathcal{C}_4^{E_3})\mathcal{D}_{i+1}\Theta(0)\partial_{\tau}\mathcal{D}_{i+1}\Theta d\zeta\\
                &\quad + \delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 (\partial_{\zeta} \mathcal{C}_4^{E_3}) \mathcal{D}_{i+1}\Theta(0)\partial_{\tau}^2\mathcal{D}_{i}\Theta d\zeta\\
                &=: \frac{d}{d\tau}\left[\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \mathcal{C}_4^{E_3} \mathcal{D}_{i+1}\Theta(0)\partial_{\tau} \mathcal{D}_{i+1}\Theta d\zeta\right] + I_{E_3}^2.
            \end{align*}
            By bootstrap assumptions and Lemma \ref{lem: induced bootstrap}, it is straightforward to see that
            $$
            \|\mathcal{C}_4^{E_3}\|_{L^\infty} + \|\partial_{\tau}\mathcal{C}_4^{E_3}\|_{L^\infty} + \|\partial_{\zeta}\mathcal{C}_4^{E_3}\|_{L^\infty} \lesssim \delta.
            $$
            We may then bound $I_{E_3}^2$ by
            \begin{equation}\label{line6aux7}
            \begin{split}
            |I_{E_3}^2| &\lesssim \delta^2\lambda^{-3\kappa}\left(\delta^\frac12 \lambda^{-\frac32\kappa} \mathcal{E}^N(0)^\frac12 \mathcal{E}^N(\tau)^\frac12  + \mathcal{E}^N(0)^\frac12 \|\partial_{\tau}^2\mathcal{D}_i\Theta\|_i\right)\\
            &\le \delta^2\lambda^{-3\kappa} \mathcal{E}^N(\tau) + \mathring{\epsilon}\|\partial_{\tau}^2\mathcal{D}_i\Theta\|_i^2 + C(\mathring{\epsilon})(\delta^2\lambda^{-3\kappa})^2\mathcal{E}^N(0).
            \end{split}
            \end{equation}

            \item \textit{Bound for $\delta\lambda^{-3\kappa}(R_{3}^i, \partial_{\tau}^2 \mathcal{D}_i\Theta)_i$.} Invoking \eqref{est:R3i} and directly using Cauchy-Schwarz inequality, we have
            \begin{equation}
                \label{line6aux8}
                |\delta\lambda^{-3\kappa}(R_{3}^i, \partial_{\tau}^2 \mathcal{D}_i\Theta)_i| \lesssim  \mathring{\epsilon}\|\partial_{\tau}^2 \mathcal{D}_i\Theta\|_i^2 + C(\mathring{\epsilon})(\delta\lambda^{-3\kappa})^2(1+\mathcal{E}^N(\tau) + \mathcal{E}^N(0)),
            \end{equation}
            for $\mathring{\epsilon} > 0$ a small constant.
        \end{enumerate}
        Finally, when $j = 4$, we invoke Proposition \ref{prop:DiE4} to write
        \begin{align*}
            \delta\lambda^{-3\kappa}(\mathcal{D}_i E_4, \partial_{\tau}^2 \mathcal{D}_i\Theta)_i &= \delta\lambda^{-3\kappa}\left((\mathcal{C}^{E_4}_1+\mathcal{C}^{E_4}_2)w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta,\partial_{\tau}^2\mathcal{D}_i\Theta\right)_i\\
            &\quad +\delta\lambda^{-3\kappa}\left(\mathcal{C}^{E_4}_3w\mathcal{D}_i\partial_{\tau}^2\Theta,\partial_{\tau}^2\mathcal{D}_i\Theta\right)_i\\
            &\quad + \delta\lambda^{-3\kappa}\left(R_{4}^i,\partial_{\tau}^2\mathcal{D}_i\Theta\right)_i,
        \end{align*}
        where we recall that the coefficients $\mathcal{C}_k^{E_4}$ are given in \eqref{E4coeff}. By bootstrap assumptions and Lemma \ref{lem: induced bootstrap}, we see that $\|\mathcal{C}_k^{E_4}\|_{L^\infty} \lesssim 1$ in the bootstrap regime. Then we immediately have
        $$
        \left|\delta\lambda^{-3\kappa}\left((\mathcal{C}^{E_4}_1+\mathcal{C}^{E_4}_2)w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta,\partial_{\tau}^2\mathcal{D}_i\Theta\right)_i\right| \lesssim \mathring{\epsilon}\|\partial_{\tau}^2 \mathcal{D}_i\Theta\|_i^2 + C(\mathring{\epsilon})(\delta\lambda^{-3\kappa})^3\mathcal{E}^N(\tau),
        $$
        for $\mathring{\epsilon} > 0$ sufficiently small, and
        $$
        \left| \delta\lambda^{-3\kappa}\left(\mathcal{C}^{E_4}_3w\mathcal{D}_i\partial_{\tau}^2\Theta,\partial_{\tau}^2\mathcal{D}_i\Theta\right)_i\right| \lesssim \delta\lambda^{-3\kappa} \|\partial_{\tau}^2\mathcal{D}_i\Theta\|_i^2.
        $$
        Finally using \eqref{est:R4i}, we have
        \begin{align*}
        \left|\delta\lambda^{-3\kappa}\left(R_{4}^i,\partial_{\tau}^2\mathcal{D}_i\Theta\right)_i\right| &\lesssim \delta\lambda^{-3\kappa}\left(\delta\lambda^{-3\kappa} + (\delta\lambda^{-3\kappa})^\frac12 \mathcal{E}^N(\tau)^\frac12 + \mathcal{S}^N(\tau)^\frac12\right)\|\partial_{\tau}^2\mathcal{D}_i\Theta\|_i\\
        &\lesssim \mathring{\epsilon}\|\partial_{\tau}^2\mathcal{D}_i\Theta\|_i^2 + C(\mathring{\epsilon})\left[(\delta\lambda^{-3\kappa})^4 + (\delta\lambda^{-3\kappa})^3\mathcal{E}^N(\tau)\right] + \delta\lambda^{-3\kappa}\mathcal{S}^N(\tau)^\frac12\|\partial_{\tau}^2\mathcal{D}_i\Theta\|_i.
        \end{align*}
    \end{enumerate}
    Now, we take \eqref{eq:Sienergy}, sum over $i = 0,\hdots, N-1$, and integrate over the time interval $[\tau_1,\tau_2]$. By combining all estimates above, we arrive at, for $\mathring{\epsilon} > 0$ and a constant $C$ depending on $N$:
    \begin{equation}
        \label{est:SN0}
        \begin{split}
        \frac{1}{2}S^N(\tau_2;\tau_1) &\le C(\mathring{\epsilon}+ \delta\lambda^{-3\kappa}) S^N(\tau_2;\tau_1) + C(\mathring{\epsilon})\left[\delta \int_{\tau_1}^{\tau_2}\lambda^{-3\kappa}\mathcal{E}^N(\tau)d\tau + \int_{\tau_1}^{\tau_2}(\delta\lambda^{-3\kappa})^2 + \delta^3\lambda^{-6\kappa}\mathcal{E}^N(0) d\tau\right]\\
        & + \left|(1+\kappa)\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2\left(\mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\mathcal{G}^{\kappa}\right)\mathcal{D}_{i+1}\Theta \partial_{\tau}\mathcal{D}_{i+1}\Theta d\zeta\bigg|_{\tau = \tau_1}\right|\\
        & + \left|(1+\kappa)\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2\left(\mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\mathcal{G}^{\kappa}\right)\mathcal{D}_{i+1}\Theta \partial_{\tau}\mathcal{D}_{i+1}\Theta d\zeta\bigg|_{\tau = \tau_2}\right|\\
        & + \left|\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \mathcal{C}_2^{E_3} \mathcal{D}_{i+1}\Theta \partial_{\tau}\mathcal{D}_{i+1}\Theta d\zeta\bigg|_{\tau = \tau_1}\right|\\
        & + \left|\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \mathcal{C}_2^{E_3} \mathcal{D}_{i+1}\Theta \partial_{\tau}\mathcal{D}_{i+1}\Theta d\zeta\bigg|_{\tau = \tau_2}\right|\\
        & + \left|\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \mathcal{C}_4^{E_3} \mathcal{D}_{i+1}\Theta(0)\partial_{\tau} \mathcal{D}_{i+1}\Theta d\zeta\bigg|_{\tau = \tau_1}\right|\\
        & + \left|\delta \lambda^{-3\kappa}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \mathcal{C}_4^{E_3} \mathcal{D}_{i+1}\Theta(0)\partial_{\tau} \mathcal{D}_{i+1}\Theta d\zeta\bigg|_{\tau = \tau_2}\right|.
        \end{split}
    \end{equation}
    First by \eqref{est:lambdaasym}, $\lambda^{-6\kappa}$ is integrable on $[0,\infty)$. Then we have
    $$
    \int_{\tau_1}^{\tau_2}(\delta\lambda^{-3\kappa})^2 + \delta^3\lambda^{-6\kappa}\mathcal{E}^N(0) d\tau \le C(\delta^2 + \delta^3\mathcal{E}^N(0)),
    $$
    where $C > 0$ is independent of $\tau_1,\tau_2$.
    Next, since 
    $$
    \left\|\mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\mathcal{G}^{\kappa}\right\|_{L^\infty} + \|\mathcal{C}_2^{E_3}\|_{L^\infty} + \|\mathcal{C}_4^{E_3}\|_{L^\infty} \lesssim 1,
    $$
    uniformly for all $\tau \in [0,\tau_*]$ by the bootstrap assumptions and and Lemma \ref{lem: induced bootstrap}, we may apply Cauchy-Schwarz inequality to bound terms on the temporal boundary $\tau = \tau_{1,2}$ by
    $$
    (\delta\lambda^{-3\kappa})^\frac32 \mathcal{E}^N(\tau_1) + (\delta\lambda^{-3\kappa})^\frac32 \mathcal{E}^N(\tau_2) + (\delta\lambda^{-3\kappa})^\frac32 \mathcal{E}^N(0).
    $$
    Finally, by choosing $\mathring{\epsilon}, \delta$ sufficiently small such that $C(\mathring{\epsilon} +\delta\lambda^{-3\kappa}) \le \frac14$, we conclude, after plugging in all estimates above to \eqref{est:SN0} and rearranging, that
    \begin{align*}
        S^N(\tau_2;\tau_1) &\lesssim (\delta\lambda^{-3\kappa})^\frac32 \mathcal{E}^N(\tau_1) + (\delta\lambda^{-3\kappa})^\frac32 \mathcal{E}^N(\tau_2) + (\delta\lambda^{-3\kappa})^\frac32 \mathcal{E}^N(0) + \delta^2+\delta^3\mathcal{E}^N(0) + \delta\int_{\tau_1}^{\tau_2} \lambda^{-3\kappa} \mathcal{E}^N(\tau) d\tau\\
        &\lesssim \delta^{\frac32}(\mathcal{E}^N(\tau_1) + \mathcal{E}^N(\tau_2) + \mathcal{E}^N(0)) + \delta^2 + \delta\int_{\tau_1}^{\tau_2} \lambda^{-3\kappa} \mathcal{E}^N(\tau) d\tau,
    \end{align*}
    which is the desired inequality.

\label{prop:mainEN0}
    Let $(\Theta,\partial_{\tau}\Theta)$ be the solution to \eqref{eq:momlagmainfull} on $[0,\tau_*]$ verifying the bootstrap assumptions. There exists $\epsilon'' \in (0,1)$ sufficiently small so that for any $\epsilon \le \epsilon''$, $\delta \le \epsilon^\frac12$, the following statement holds: for any time instances $\tau_0, \tau$ such that $0 \le \tau_0 \le \tau \le \tau_*$, then
    \begin{equation}
        \label{est:mainEN0}
        \begin{split}
        \mathcal{E}^N(\tau) + \int_{\tau_0}^\tau \mathfrak{D}^N(\tilde\tau)d\tilde\tau &\le C_0(\mathcal{E}^N(\tau_0) + \mathcal{E}^N(0) + \delta^2)\\
        &\quad + C_1 \left[\delta^\frac12\int_{\tau_0}^\tau e^{-\frac32\kappa\bar\lambda \tilde\tau} (\mathcal{E}^N(\tilde\tau))^\frac12 d\tilde\tau + \int_{\tau_0}^\tau e^{-\frac32\kappa\bar\lambda \tilde\tau}\mathcal{E}^N(\tilde\tau) d\tilde\tau\right],
        \end{split}
    \end{equation}
    where $C_0, C_1$ are positive constants that are independent of parameters $\epsilon, \delta$, and $M_*$.

We start by recalling the energy balance \eqref{eq: high-order energy identity}: for $0 \le i \le N$,
    \begin{equation}
        \label{eq:ienergybalance}
        \begin{split}
        \frac{d}{d\tau}\mathfrak{E}_i(\tau) + \mathfrak{D}_i(\tau) &=  -(\bar{\mathcal{D}}_{i-1}\mathfrak{M}, \partial_{\tau}\mathcal{D}_i\Theta)_i - \sum_{j=1}^2 (\mathcal{D}_i\mathfrak{R}_j(\Theta), \partial_\tau\mathcal{D}_i\Theta)_i-\sum_{j=1}^6(\mathcal{D}_iE_j, \partial_{\tau}\mathcal{D}_i\Theta)_i\\
        &\quad-\sum_{j=1}^3(\mathfrak{C}_j, \partial_{\tau}\mathcal{D}_i\Theta)_i -\sum_{j=1}^5\mathfrak{I}_j.
        \end{split}
    \end{equation}
    Using Proposition \ref{prop:est M}, Proposition \ref{prop:est R}, Proposition \ref{prop:est C12}, and Proposition \ref{prop:est C}, we have the following bound after a use of Cauchy-Schwarz inequality:
    \begin{equation}
        \label{energyineqaux1}
        \begin{split}
        &\left|(\bar{\mathcal{D}}_{i-1}\mathfrak{M}, \partial_{\tau}\mathcal{D}_i\Theta)_i + \sum_{j=1}^2 (\mathcal{D}_i\mathfrak{R}_j(\Theta), \partial_\tau\mathcal{D}_i\Theta)_i +\sum_{j=1}^3(\mathfrak{C}_j, \partial_{\tau}\mathcal{D}_i\Theta)_i +\sum_{j=1}^5\mathfrak{I}_j\right|\\
        &\quad \lesssim (\delta\lambda^{-3\kappa})^\frac12\left((\mathcal{E}^N(\tau))^\frac12 + (\mathcal{S}^N(\tau))^\frac12\right)(\mathcal{E}^N(\tau))^\frac12 + \lambda^{-\frac32\kappa}\mathcal{E}^N(\tau)\\
        &\quad \lesssim \lambda^{-\frac32\kappa}\mathcal{E}^N(\tau) + \mathcal{S}^N(\tau),
        \end{split}
    \end{equation}
    where we used that $\delta \lambda^{-3\kappa} + \delta \lesssim 1$. Using Proposition \ref{prop:DiE1}, Proposition \ref{prop:DiE2}, Proposition \ref{prop:DiE3}, Proposition \ref{prop:DiE4}, and Proposition \ref{prop:DiE5+6}, we write
    \begin{equation}
        \label{energyineqaux2}
        \begin{split}
            -\sum_{j=1}^6(\mathcal{D}_iE_j, \partial_{\tau}\mathcal{D}_i\Theta)_i &= -\left((\mathcal{C}_1^{E_4} + \mathcal{C}_2^{E_4} +\mathcal{C}_1^{E_3})w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta, \mathcal{D}_i\partial_{\tau}\Theta\right)_i\\
            &\quad -\left(\mathcal{C}_3^{E_4}\mathcal{D}_{i}\partial_{\tau}^2\Theta, \mathcal{D}_i\partial_{\tau}\Theta\right)_i - \left(g\mathcal{L}_{i}\mathcal{D}_i\Theta, \mathcal{D}_i\partial_{\tau}\Theta\right)_i\\
            &\quad - \left(\mathcal{C}_3^{E_3}w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta(0), \mathcal{D}_i\partial_{\tau}\Theta\right)_i - \left(\mathcal{C}_4^{E_3}\mathcal{L}_{i}\mathcal{D}_i\Theta(0), \mathcal{D}_i\partial_{\tau}\Theta\right)_i\\
            &\quad + (\mathfrak{R}_E,\mathcal{D}_i\partial_{\tau}\Theta)_i,
        \end{split}
    \end{equation}
    where the coefficients $\mathcal{C}_k^{E_j}$ are defined in \eqref{E4coeff} and \eqref{E3coeff}, and the function $g$ is given by
    \begin{equation}\label{gdefn}
    g(\tau,\zeta) := (1+\kappa)\mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4(\mathcal{G}^\kappa - 1) +\mathcal{C}_{2}^{E_3}.
    \end{equation}
    Moreover, $\mathfrak{R}_E$ obeys the following bound for all $\tau \in [0,\tau_*]$:
    \begin{equation}
        \label{energyineqaux3}
        \|\mathfrak{R}_E\|_i^2 \lesssim 1 + \mathcal{E}^N(0) + \mathcal{S}^N(\tau) + \mathcal{E}^N(\tau).
    \end{equation}
    Then we are left to study the leading order terms appearing in \eqref{energyineqaux2}. 
    \begin{enumerate}
        \item $\left((\mathcal{C}_1^{E_4} + \mathcal{C}_2^{E_4} +\mathcal{C}_1^{E_3})w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta, \mathcal{D}_i\partial_{\tau}\Theta\right)_i$. It suffices to consider the case where $i$ is even, as the $i$ odd case is strictly easier. Writing $\mathcal{D}_{i+1} = D_{\zeta} \mathcal{D}_i = \partial_{\zeta}\mathcal{D}_i + \frac{2}{\zeta}\mathcal{D}_i$, we have
        \begin{align*}
            &-\left((\mathcal{C}_1^{E_4} + \mathcal{C}_2^{E_4} +\mathcal{C}_1^{E_3})w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta, \mathcal{D}_i\partial_{\tau}\Theta\right)_i = -\frac12\int_0^1 (\mathcal{C}_1^{E_4} + \mathcal{C}_2^{E_4} +\mathcal{C}_1^{E_3}) w^{\frac1\kappa + i+1}\zeta^3 \partial_{\zeta}\left(\mathcal{D}_i\partial_{\tau}\Theta\right)^2d\zeta\\
            &\quad - 2\int_0^1 (\mathcal{C}_1^{E_4} + \mathcal{C}_2^{E_4} +\mathcal{C}_1^{E_3}) w^{\frac1\kappa + i+1} \zeta^2 \left(\mathcal{D}_i\partial_{\tau}\Theta\right)^2d\zeta\\
            &=\frac12 \int_0^1 \partial_{\zeta}\left(\mathcal{C}_1^{E_4} + \mathcal{C}_2^{E_4} +\mathcal{C}_1^{E_3}\right)w^{\frac1\kappa + i+1}\zeta^3 \left(\mathcal{D}_i\partial_{\tau}\Theta\right)^2d\zeta\\
            &\quad +\frac{\frac1\kappa + i + 1}{2} \int_0^1 \left(\mathcal{C}_1^{E_4} + \mathcal{C}_2^{E_4} +\mathcal{C}_1^{E_3}\right)w'w^{\frac1\kappa + i}\zeta^3 \left(\mathcal{D}_i\partial_{\tau}\Theta\right)^2d\zeta\\
            &\quad -\frac{1}{2}\int_0^1 \left(\mathcal{C}_1^{E_4} + \mathcal{C}_2^{E_4} +\mathcal{C}_1^{E_3}\right)w^{\frac1\kappa + i+1}\zeta^2 \left(\mathcal{D}_i\partial_{\tau}\Theta\right)^2d\zeta.
        \end{align*}
        Since $\|\mathcal{C}_1^{E_4}\|_{W^{1,\infty}} + \|\mathcal{C}_2^{E_4}\|_{W^{1,\infty}} + \|\mathcal{C}_1^{E_3}\|_{W^{1,\infty}} \lesssim 1$ by bootstrap assumptions and Lemma \ref{lem: induced bootstrap}, we immediately have
        \begin{equation}
            \label{leadingorder1}
            \left|\left((\mathcal{C}_1^{E_4} + \mathcal{C}_2^{E_4} +\mathcal{C}_1^{E_3})w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta, \mathcal{D}_i\partial_{\tau}\Theta\right)_i\right| \lesssim \|\mathcal{D}_i\partial_{\tau}\Theta\|_i^2 \le \delta\lambda^{-3\kappa}\mathcal{E}^N(\tau).
        \end{equation}

        \item $-\left(\mathcal{C}_3^{E_4}\mathcal{D}_{i}\partial_{\tau}^2\Theta, \mathcal{D}_i\partial_{\tau}\Theta\right)_i$. We observe that
        \begin{equation}\label{leadingorder2}
        \begin{split}
            -\left(\mathcal{C}_3^{E_4}\mathcal{D}_{i}\partial_{\tau}^2\Theta, \mathcal{D}_i\partial_{\tau}\Theta\right)_i &= -\frac12\partial_{\tau}\left(\mathcal{C}_3^{E_4}\mathcal{D}_i\partial_{\tau}\Theta,\mathcal{D}_i\partial_{\tau}\Theta\right)_i + \frac12  \left(\partial_{\tau}\mathcal{C}_3^{E_4} \mathcal{D}_i\partial_{\tau}\Theta,\mathcal{D}_i\partial_{\tau}\Theta\right)\\
            &=: -\frac12\partial_{\tau}\left(\mathcal{C}_3^{E_4}\mathcal{D}_i\partial_{\tau}\Theta,\mathcal{D}_i\partial_{\tau}\Theta\right)_i + \mathfrak{I}_{leading}^1.
            \end{split}
        \end{equation}
        By definition of $\mathcal{C}_3^{E_4}$, bootstrap assumptions, and Lemma \ref{lem: induced bootstrap}, we have $\|\partial_{\tau} \mathcal{C}_3^{E_4}\|_{L^\infty} \lesssim 1$. Then the following bound holds:
        $$|\mathfrak{I}_{leading}^1| \lesssim \delta\lambda^{-3\kappa}\mathcal{E}^N(\tau).$$

        \item $- \left(g\mathcal{L}_{i}\mathcal{D}_i\Theta, \mathcal{D}_i\partial_{\tau}\Theta\right)_i$. Following \eqref{ellipticibp}, we have
        \begin{equation}\label{leadingorder3}
        \begin{split}
            -\left(g\mathcal{L}_{i}\mathcal{D}_i\Theta, \mathcal{D}_i\partial_{\tau}\Theta\right)_i &=-\frac{1}{2}\frac{d}{d\tau}\int_0^1w^{1+\frac1\kappa+i}\zeta^2g|\mathcal{D}_{i+1}\Theta|^2 + \frac{1}{2}\int_0^1w^{1+\frac1\kappa+i}\zeta^2(\partial_{\tau}g)|\mathcal{D}_{i+1}\Theta|^2\\
    &-\int_0^1w^{1+\frac1\kappa+i}\zeta^2(\partial_{\zeta} g)(\partial_{\tau}\mathcal{D}_i\Theta)(\mathcal{D}_{i+1}\Theta)\\
    &=: -\frac{1}{2}\partial_{\tau} (g\mathcal{D}_{i+1}\Theta, \mathcal{D}_{i+1}\Theta)_{i+1} + \mathfrak{I}_{leading}^2.            
        \end{split}
        \end{equation}
        By bootstrap assumptions, Lemma \ref{lem: induced bootstrap}, and the definition of $g$, it is not difficult to see the following estimate:
        $$
        \|\partial_{\zeta} g\|_{L^\infty} \lesssim 1,\quad \|\partial_{\tau} g\|_{L^\infty} \lesssim \lambda^{-\frac32}.
        $$
        Then an application of Cauchy-Schwarz inequality yields:
        \begin{equation}\label{Ileading2}
            |\mathfrak{I}_{leading}^2| \lesssim (\delta\lambda^{-3\kappa})^\frac12 \mathcal{E}^N(\tau).
        \end{equation}

        \item $- \left(\mathcal{C}_3^{E_3}w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta(0), \mathcal{D}_i\partial_{\tau}\Theta\right)_i$. It suffices to consider $i$ to be even. We observe that
        \begin{align*}
            &- \left(\mathcal{C}_3^{E_3}w\zeta\mathcal{D}_{i+1}\partial_{\tau}\Theta(0), \mathcal{D}_i\partial_{\tau}\Theta\right)_i = \int_0^1 \mathcal{C}_3^{E_3} w^{\frac1\kappa + i + 1}\zeta^3\mathcal{D}_i \partial_{\tau}\Theta(0)\mathcal{D}_{i+1}\partial_{\tau}\Theta d\zeta\\
            &\quad + \int_0^1 \partial_{\zeta}\left(\mathcal{C}_3^{E_3} w^{\frac1\kappa + i + 1}\zeta^3\right) \mathcal{D}_i \partial_{\tau}\Theta(0) \mathcal{D}_i\partial_{\tau}\Theta d\zeta-2\int_0^1 \mathcal{C}_3^{E_3} w^{\frac1\kappa + i + 1}\zeta^2\mathcal{D}_i \partial_{\tau}\Theta(0)\mathcal{D}_i\partial_{\tau}\Theta d\zeta\\
            &= \frac{d}{d\tau} \int_0^1 \mathcal{C}_3^{E_3} w^{\frac1\kappa + i + 1}\zeta^3\mathcal{D}_i \partial_{\tau}\Theta(0)\mathcal{D}_{i+1}\Theta d\zeta- \int_0^1 (\partial_{\tau}\mathcal{C}_3^{E_3}) w^{\frac1\kappa + i + 1}\zeta^3\mathcal{D}_i \partial_{\tau}\Theta(0)\mathcal{D}_{i+1}\Theta d\zeta\\
            &\quad + \int_0^1 \partial_{\zeta}\left(\mathcal{C}_3^{E_3} w^{\frac1\kappa + i + 1}\zeta^3\right) \mathcal{D}_i \partial_{\tau}\Theta(0) \mathcal{D}_i\partial_{\tau}\Theta d\zeta-2\int_0^1 \mathcal{C}_3^{E_3} w^{\frac1\kappa + i + 1}\zeta^2\mathcal{D}_i \partial_{\tau}\Theta(0)\mathcal{D}_i\partial_{\tau}\Theta d\zeta\\
            &=: \frac{d}{d\tau} \int_0^1 \mathcal{C}_3^{E_3} w^{\frac1\kappa + i + 1}\zeta^3\mathcal{D}_i \partial_{\tau}\Theta(0)\mathcal{D}_{i+1}\Theta d\zeta + \mathfrak{I}_{leading}^3.
        \end{align*}
        By definition of $\mathcal{C}_3^{E_3}$, the bootstrap assumptions, and Lemma \ref{lem: induced bootstrap}, we have the following bounds:
        $$
        \|\mathcal{C}_3^{E_3}\|_{W^{1,\infty}} \lesssim 1,\quad \|\partial_{\tau} \mathcal{C}_3^{E_3}\|_{L^\infty} \lesssim \lambda^{-\frac32\kappa},
        $$
        from which we deduce that
        \begin{equation}
            \label{Ileading3}
            |\mathfrak{I}_{leading}^3| \lesssim (\delta \lambda^{-3\kappa})^\frac12 (\mathcal{E}^N(0))^\frac12(\mathcal{E}^N(\tau))^\frac12 \lesssim (\delta \lambda^{-3\kappa})^\frac12(\mathcal{E}^N(0) + \mathcal{E}^N(\tau)).
        \end{equation}

        \item $- \left(\mathcal{C}_4^{E_3}\mathcal{L}_{i}\mathcal{D}_i\Theta(0), \mathcal{D}_i\partial_{\tau}\Theta\right)_i$. Following \eqref{ellipticibp}, we note that
        \begin{align*}
            &- \left(\mathcal{C}_4^{E_3}\mathcal{L}_{i}\mathcal{D}_i\Theta(0), \mathcal{D}_i\partial_{\tau}\Theta\right)_i = -\frac{d}{d\tau}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \mathcal{C}_4^{E_3} \mathcal{D}_{i+1}\Theta(0)\mathcal{D}_{i+1}\Theta d\zeta\\
            &\quad + \int_0^1 w^{\frac1\kappa + i + 1}\zeta^2(\partial_{\tau} \mathcal{C}_4^{E_3})\mathcal{D}_{i+1}\Theta(0)\mathcal{D}_{i+1}\Theta d\zeta- \int_0^1 w^{\frac1\kappa + i + 1}\zeta^2(\partial_{\zeta} \mathcal{C}_4^{E_3})\mathcal{D}_{i+1}\Theta(0)\mathcal{D}_{i}\partial_{\tau}\Theta d\zeta\\
            &=: -\frac{d}{d\tau}\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \mathcal{C}_4^{E_3} \mathcal{D}_{i+1}\Theta(0)\mathcal{D}_{i+1}\Theta d\zeta + \mathfrak{I}_{leading}^4.
        \end{align*}
        Again by the definition of $\mathcal{C}_4^{E_3}$, the bootstrap assumptions and Lemma \ref{lem: induced bootstrap}, we have the bounds
        $$
        \|\mathcal{C}_4^{E_3}\|_{W^{1,\infty}} \lesssim \delta,\quad \|\partial_{\tau} \mathcal{C}_4^{E_3}\|_{L^\infty} \lesssim \delta \lambda^{-\frac32\kappa}.
        $$
        Then we have
        \begin{equation}
            \label{Ileading4}
            |\mathfrak{I}_{leading}^4| \lesssim \delta \lambda^{-\frac32\kappa}(\mathcal{E}^N(0) + \mathcal{E}^N(\tau)).
        \end{equation}

    \end{enumerate}

    Now, we integrate \eqref{eq:ienergybalance} in time on $[\tau_0,\tau]$, rearranging, and applying \eqref{energyineqaux1}--\eqref{Ileading4}, we obtain
    \begin{equation}\label{est:mfEiaux1}
    \begin{split}
        \mathfrak{E}_i(\tau) &+ \int_{\tau_0}^\tau \mathfrak{D}_i(\tilde\tau) d\tilde\tau + \frac12 \left(\mathcal{C}_3^{E_4}\mathcal{D}_i\partial_{\tau}\Theta, \mathcal{D}_i\partial_{\tau}\Theta\right)_i(\tau) + \frac12 \left(g\mathcal{D}_{i+1}\Theta,\mathcal{D}_{i+1}\Theta\right)_i(\tau)\\
        &\quad-\int_0^1 \mathcal{C}_3^{E_3}(\tau) w^{\frac1\kappa + i + 1}\zeta^3\mathcal{D}_i \partial_{\tau}\Theta(0)\mathcal{D}_{i+1}\Theta(\tau) d\zeta+\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \mathcal{C}_4^{E_3}(\tau) \mathcal{D}_{i+1}\Theta(0)\mathcal{D}_{i+1}\Theta(\tau) d\zeta\\
        &\le \frac12 \left|\left(\mathcal{C}_3^{E_4}\mathcal{D}_i\partial_{\tau}\Theta, \mathcal{D}_i\partial_{\tau}\Theta\right)_i(\tau_0)\right| + \frac12\left|\left(g\mathcal{D}_{i+1}\Theta,\mathcal{D}_{i+1}\Theta\right)_i(\tau_0)\right|\\
        &\quad +\left|\int_0^1 \mathcal{C}_3^{E_3}(\tau_0) w^{\frac1\kappa + i + 1}\zeta^3\mathcal{D}_i \partial_{\tau}\Theta(0)\mathcal{D}_{i+1}\Theta(\tau_0) d\zeta\right|+ \left|\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \mathcal{C}_4^{E_3}(\tau_0) \mathcal{D}_{i+1}\Theta(0)\mathcal{D}_{i+1}\Theta(\tau_0) d\zeta\right|\\
        &\quad + C\bigg[\delta^\frac12\int_{\tau_0}^\tau \lambda^{-\frac32\kappa}(\mathcal{E}^N(\tilde\tau))^\frac12\left(1+\mathcal{S}^N(\tilde\tau) + \mathcal{E}^N(\tilde\tau)+\mathcal{E}^N(0)\right)^\frac12 d\tilde\tau + \delta^\frac12\int_{\tau_0}^\tau \lambda^{-\frac32\kappa} \mathcal{E}^N(0) d\tilde\tau\\
        &\quad + \int_{\tau_0}^\tau \lambda^{-\frac32\kappa}\mathcal{E}^N(\tilde\tau) d\tilde\tau + \int_{\tau_0}^\tau \mathcal{S}^N(\tilde\tau) d\tilde\tau\bigg]\\
        &\le \bar{C}\left(\mathcal{E}^N(\tau_0) + \mathcal{E}^N(0)\right) + C\left[\delta^\frac12\int_{\tau_0}^\tau e^{-\frac32\kappa\bar\lambda \tilde\tau} (\mathcal{E}^N(\tilde\tau))^\frac12 d\tilde\tau + \int_{\tau_0}^\tau \mathcal{S}^N(\tilde\tau) d\tilde\tau\right]\\
        &\le \bar{C}\left(\delta^\frac32\mathcal{E}^N(\tau) + \mathcal{E}^N(\tau_0) + \mathcal{E}^N(0) + \delta^2\right) + C\left[\delta^\frac12\int_{\tau_0}^\tau e^{-\frac32\kappa\bar\lambda \tilde\tau} (\mathcal{E}^N(\tilde\tau))^\frac12 d\tilde\tau+\int_{\tau_0}^\tau e^{-\frac32\kappa\bar\lambda \tilde\tau}\mathcal{E}^N(\tilde\tau) d\tilde\tau\right],
        \end{split}
    \end{equation}
    where $C,\bar C > 0$ are positive constants which are independent of $M_*,\epsilon,\delta$. We remark that we have used bootstrap assumptions, Lemma \ref{lem: induced bootstrap}, the equivalence \eqref{est:lambdaasym}, and the integrability of $\lambda^{-\frac32\kappa}$ on $[0,\infty]$ in the second inequality above; we also used Proposition \ref{prop:SN} in the final inequality.

    In view of the LHS of \eqref{est:mfEiaux1}, we immediately infer from Lemma \ref{lem: induced bootstrap} that
    \begin{align*}
        \left|\frac12 \left(\mathcal{C}_3^{E_4}\mathcal{D}_i\partial_{\tau}\Theta, \mathcal{D}_i\partial_{\tau}\Theta\right)_i(\tau)\right| &\lesssim \delta\lambda^{-3\kappa}\mathcal{E}^N(\tau) \lesssim \delta \mathcal{E}^N(\tau),\\
        \left|\int_0^1 \mathcal{C}_3^{E_3}(\tau) w^{\frac1\kappa + i + 1}\zeta^3\mathcal{D}_i \partial_{\tau}\Theta(0)\mathcal{D}_{i+1}\Theta(\tau) d\zeta\right| &\lesssim \delta^\frac12(\mathcal{E}^N(0))^\frac12(\mathcal{E}^N(\tau))^\frac12 \lesssim \mathcal{E}^N(0) + \delta\mathcal{E}^N(\tau),\\
        \left|\int_0^1 w^{\frac1\kappa + i + 1}\zeta^2 \mathcal{C}_4^{E_3}(\tau) \mathcal{D}_{i+1}\Theta(0)\mathcal{D}_{i+1}\Theta(\tau) d\zeta\right| &\lesssim (\mathcal{E}^N(0))^\frac12(\mathcal{E}^N(\tau))^\frac12 \le \mathring{\epsilon}\mathcal{E}^N(\tau) + C(\mathring{\epsilon})\mathcal{E}^N(0),
    \end{align*}
    where $\mathring{\epsilon} > 0$ is a small parameter to be determined. Using the above bounds, we then bound the LHS of \eqref{est:mfEiaux1} from below as follows:
    \begin{equation}\label{est:LHSEi}
    \begin{split}
    \text{LHS of }\eqref{est:mfEiaux1} &\ge \int_{\tau_0}^\tau \mathfrak{D}_i(\tilde\tau)d\tilde\tau + \frac{1}{2}\delta^{-1}\lambda^{3\kappa}\int_0^1 w^{\frac1\kappa+i}\zeta^2(1+\delta\lambda^{-3\kappa}w\mathcal{F}^{-\kappa}\mathcal{G}^{\kappa})|\mathcal{D}_i\partial_{\tau}\Theta|^2d\zeta \\
    &\quad+ \frac{1}{2}\int_0^1 w^{\frac1\kappa+i}\zeta^2(1+\delta\lambda^{-3\kappa}w\mathcal{F}^{-\kappa}\mathcal{G}^{\kappa})|\mathcal{D}_i\Theta|^2d\zeta\\
    &\quad+\frac{1+\kappa}{2}\int_0^1w^{1+\frac1\kappa+i}\zeta^2\left(\mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\right)|\mathcal{D}_{i+1}\Theta|^2d\zeta\\
    &\quad+\frac12 \left(g\mathcal{D}_{i+1}\Theta,\mathcal{D}_{i+1}\Theta\right)_i(\tau) - (\mathring{\epsilon} + \delta)\mathcal{E}^N(\tau) - C(\mathring{\epsilon})\mathcal{E}^N(0)\\
    &=\int_{\tau_0}^\tau \mathfrak{D}_i(\tilde\tau)d\tilde\tau + \frac{1}{2}\delta^{-1}\lambda^{3\kappa}\int_0^1 w^{\frac1\kappa+i}\zeta^2(1+\delta\lambda^{-3\kappa}w\mathcal{F}^{-\kappa}\mathcal{G}^{\kappa})|\mathcal{D}_i\partial_{\tau}\Theta|^2d\zeta \\
    &\quad+ \frac{1}{2}\int_0^1 w^{\frac1\kappa+i}\zeta^2(1+\delta\lambda^{-3\kappa}w\mathcal{F}^{-\kappa}\mathcal{G}^{\kappa})|\mathcal{D}_i\Theta|^2d\zeta\\
    &\quad+\frac{1+\kappa}{2}\int_0^1w^{1+\frac1\kappa+i}\zeta^2\left[\left(\mathcal{F}^{-\kappa-2}(U^0)^{-4}\left(1+\frac{\Theta}{\zeta}\right)^4\mathcal{G}^\kappa\right) + \mathcal{C}_2^{E_3}\right]|\mathcal{D}_{i+1}\Theta|^2d\zeta\\
    &\quad - (\mathring{\epsilon} + \delta)\mathcal{E}^N(\tau) - C(\mathring{\epsilon})\mathcal{E}^N(0)\\
    &\ge c_0\mathcal{E}_i(\tau) +\int_{\tau_0}^\tau \mathfrak{D}_i(\tilde\tau)d\tilde\tau - (\mathring{\epsilon} + \delta)\mathcal{E}^N(\tau) - C(\mathring{\epsilon})\mathcal{E}^N(0),
    \end{split}
    \end{equation}
    where $c_0 > 0$ is a constant independent of $M_*, \epsilon,\delta$. Note that we have used the definition of $g$ \eqref{gdefn} in the equality above. In the final inequality above, we used the bootstrap assumption that $\mathcal{F}, U^0,\mathcal{G} \approx 1$, the bound $\|\mathcal{C}_2^{E_3}\|_{L^\infty} \lesssim \delta \ll1$, and the energy-norm equivalence (i.e., Corollary \ref{cor: energy norm equiva}). Now, let us choose $\mathring{\epsilon} + \delta < \frac{c_0}{2}$. Combining \eqref{est:mfEiaux1} and \eqref{est:LHSEi}, rearranging, and summing over $i = 0,\hdots, N$, we arrive at
    \begin{align*}
    \frac{c_0}{2}\mathcal{E}^N(\tau) +\int_{\tau_0}^\tau \mathfrak{D}^N(\tilde\tau)d\tilde\tau &\le \bar{C}N\left(\delta^\frac32\mathcal{E}^N(\tau) + \mathcal{E}^N(\tau_0) + \mathcal{E}^N(0) + \delta^2\right)\\
    &\quad +CN\left[\delta^\frac12\int_{\tau_0}^\tau e^{-\frac32\kappa\bar\lambda \tilde\tau} (\mathcal{E}^N(\tilde\tau))^\frac12 d\tilde\tau + \int_{\tau_0}^\tau e^{-\frac32\kappa\bar\lambda \tilde\tau}\mathcal{E}^N(\tilde\tau) d\tilde\tau\right]
    \end{align*}
    Choosing $\delta$ even smaller such that $\bar{C}N\delta^\frac32 \le \min\{\frac{c_0}{4},\frac12\}$, we deduce from the above inequality that
    \begin{align*}
    \mathcal{E}^N(\tau)+\int_{\tau_0}^\tau \mathfrak{D}^N(\tilde\tau)d\tilde\tau &\le \frac{4\bar C N}{c_0}\left(\mathcal{E}^N(\tau_0) + \mathcal{E}^N(0) + \delta^2\right)\\
    &\quad+ \frac{4CN}{c_0}\left[\delta^\frac12\int_{\tau_0}^\tau e^{-\frac32\kappa\bar\lambda \tilde\tau} (\mathcal{E}^N(\tilde\tau))^\frac12 d\tilde\tau + \int_{\tau_0}^\tau e^{-\frac32\kappa\bar\lambda \tilde\tau}\mathcal{E}^N(\tilde\tau) d\tilde\tau\right]
    \end{align*}
    Then the main result \eqref{est:mainEN0} follows after we fix $C_0 = \frac{4\bar C N}{c_0}$ and $C_1 = \frac{4CN}{c_0}.$

\label{R:Norm_equivalence_calX_calE}
    We see that the $\mathcal{X}^m$ norm is the  $\mathcal{E}^N$ norm given by \eqref{defn:calEN}
up to the factor $\delta^{-1}\lambda(\tau)^{3\kappa}$. Recall that $\lambda(\tau)$ is given by Lemma \ref{lem:lambdaODE}, which also ensures that   $\lambda$ does not depend on solutions to \eqref{eq:momlagmain} and is uniformly bounded away from zero on any finite time interval. Therefore, the $\mathcal{X}^{m}$ norm is equivalent to the norm $\mathcal{E}^N$ given by \eqref{defn:calEN} for each $\tau$.

\label{T:LWP}
    Let $(\mathring{\rho},\mathring{u}^i)$ be spherically symmetric initial data for the relativistic Euler equations \eqref{eq:RE} on a bounded domain $\mathring{\Omega} = B_{\lambda_0}(0) \subset \mathbb{R}^3$, with equation of state \eqref{equation of states}. Assume that $\mathring{\Omega} = \{ \mathring{\rho} > 0 \}$ and that the physical vacuum boundary condition \eqref{fallout rate} holds on $\mathring{\Omega}$.  Let $N$ be an integer such that 
    \begin{align}
    \label{E:Fixed_N_bound}
    N \geq \lfloor \frac{1}{\kappa} \rfloor + 10.
    \end{align}
    Suppose that
    \begin{align*}
        (\mathring{\mathsf{r}},\mathring{\mathsf{v}}^i) \in 
        \mathcal{H}^{2k}_{\mathring{\mathsf{r}}}(\mathring{\Omega}),
    \end{align*}
    where $(\mathring{\mathsf{r}},\mathring{\mathsf{v}}^i)$ are the variables \eqref{E:New_sound_and_velocity} constructed out of $(\mathring{\rho},\mathring{u}^i)$, and $k$ satisfies
    \begin{align}
        \label{E:N_k_relation}
        k & \geq N + 5 + \lceil \frac{1}{2\kappa} \rceil.
    \end{align}        
    Fix parameters $\lambda_1 \in (0,1)$, $\delta >0$, an admissible weight $w$ as in Definition \ref{def: w}, introduce the reference initial data 
    \begin{subequations}{\label{E:Reference_data}}
    \begin{align}
        \label{E:rho_ref}
        \mathring{\rho}_{\text{ref}}(x) &:= \lambda_0^{-3} \big(\delta w(\frac{|x|}{\lambda_0})\big)^\frac{1}{\kappa}, \quad
        \\
        \label{E:u_ref}
        \mathring{u}^i_{\text{ref}}(x) &:= \frac{1}{\sqrt{1-\frac{\lambda_1^2 }{\lambda_0^2}|x|^2}} \frac{\lambda_1}{\lambda_0} x^i,
    \end{align}        
    \end{subequations}
    and let $(\mathsf{r}_\text{ref},\mathsf{v}^i_\text{ref})$ be the variables \eqref{E:New_sound_and_velocity} corresponding to $(\rho_\text{ref},u^i_\text{ref})$.
    Introduce the $\delta$-dependent reference mass
    \begin{subequations}{\label{E:Masses_data}}
    \begin{align}
        \label{E:Reference_mass}
        M_\text{ref}(\delta,w) \equiv M_\text{ref}:=4\pi \int_0^1 (\delta w(\zeta))^\frac{1}{\kappa} \zeta^2  d\zeta,
    \end{align}
    and the total mass of the initial data
    \begin{align}
        \label{E:Initial_mass}
        M(\mathring{\rho}) \equiv 
        M :=4\pi \int_0^{\lambda_0} \mathring{\rho}(r) r^2 dr.
    \end{align}
    \end{subequations}    
    Finally, assume that
    \begin{align}
        \label{E:Mass_constraint}
        M = M_\text{ref}.
    \end{align}

    Then, the following statements hold:

    \medskip
    1) The variables $(\Theta_0,U_0)$ in \eqref{mainID} given by the change of variables described in Section \ref{sect: setup}, with $\rho=\mathring{\rho}$ and $u=\mathring{u}$ in \eqref{ansatz radial symmetry}, are well defined. Moreover, $(\Theta_0,U_0)=(0,0)$ if $\mathring{\rho}=\mathring{\rho}_{\text{ref}}$ and $\mathring{u}^i=\mathring{u}^i_{\text{ref}}$.

    \medskip
    2) There exists a $\tau^*>0$ and a unique classical solution $\Theta$ to \eqref{eq:momlagmain} defined on the time interval $[0,\tau^*)$ and taking the data \eqref{mainID}, where again \eqref{eq:momlagmain} is constructed out of $(\mathring{\rho},\mathring{u}^i)$ as in Section \ref{sect: setup}. Furthermore, for any $0 \leq \tau^{**} < \tau^*$, 
    \begin{align}
        \label{E:Regularity_Theta_partial_tau_Theta_closed_time_interval}
        (\Theta,\partial_\tau\Theta) \in C^0([0,\tau^{**}],\mathcal{X}^N),
    \end{align}
    and 
    \begin{align}
    \label{E:Finiteness_E_N_closed_time_interval}
    E^N(\tau^{**}) < \infty.
    \end{align}

    \medskip
    3) Define the set of initial states with compatible mass as 
    \begin{align*}
    \mathcal{H}_{\text{ref}}^{2k} := \{ (\mathring{\mathsf{r}},\mathring{\mathsf{v}}^i) \in \mathcal{H}^{2k}_0 \, | \,     (\mathring{\mathsf{r}},\mathring{\mathsf{v}}^i) \text{ is spherically symmetric and }
    M(\mathring{r}) = M_\text{ref} \},
    \end{align*}    
    with topology induced from $\mathcal{H}_0^{2k}$, where $M(\mathring{r})$ being the corresponding $M(\mathring{\rho})$ given by \eqref{E:Initial_mass}.

    Given $\epsilon > 0$, there exists a neighborhood $(\mathsf{r}_\text{ref},\mathsf{v}_\text{ref}) \in \mathcal{U}_\text{ref} \subset \mathcal{H}_{\text{ref}}^{2k}$ such that if
    \begin{align*}    (\mathring{\mathsf{r}},\mathring{\mathsf{v}}^i)  \in \mathcal{U}_\text{ref} 
    \end{align*}
    then
    \begin{align*}
        E^N(0) < \epsilon.
    \end{align*}

    \medskip
    4) Assume that the bootstrap assumptions \eqref{bootstrap U0} and \eqref{bootstrap FG} hold on $[0,\tau^*)\times[0,1]$. If 
    \begin{align}
        \label{E:Continuation_criterion_Lagrangian}
        \sup_{\tau \in [0,\tau^*)} \Big( 
        \| \Theta(\tau,\cdot) \|_{C^3([0,1])} + \| \partial_\tau \Theta(\tau,\cdot) \|_{C^2([0,1])}
        \Big) < \infty
    \end{align}
    and $\tau^* < \infty$, then the solution $(\Theta(\tau,\cdot),\partial_\tau \Theta(\tau,\cdot))$ given by 2) can be continued past $\tau^*$.

\label{thm:improved}
    Let $(\Theta,\partial_{\tau}\Theta)$ be a solution to \eqref{eq:momlagmainfull} on $[0,\tau_*]$ verifying the bootstrap assumptions. There exists $\epsilon_0 > 0$ sufficiently small such that for any $\epsilon \le \epsilon_0$ and $\delta \le \epsilon$, the following improved estimates hold:
    \begin{subequations}
    \label{est:improved}
    \begin{equation}\label{est:improvedEN}
        E^N(\tau_*) \le \frac{M_*\epsilon}{2},
        \end{equation}
        \begin{equation}\label{est:improvedU0}
        \frac23(1-\bar\lambda^2\zeta^2) \le (U^0(\tau,\zeta))^{-2} \le \frac{4}{3}(1-\bar\lambda^2\zeta^2),\quad (\tau,\zeta) \in [0,\tau_*]\times [0,1],
        \end{equation}
        \begin{equation}\label{est:improvedFG}
        \|\mathcal{F}(\tau) - 1\|_{L^\infty} + \|\kappa\bar{\mathcal{G}}(\tau) - 1\|_{L^\infty} \le \frac{1}{200},\quad \tau \in [0,\tau_*].
        \end{equation}
    \end{subequations}

\label{prop:barGimproved}
    Given the assumptions of Theorem \ref{thm:improved}, the following estimate holds:
    \begin{equation}
        \label{est:barGimproved}
        \sup_{0\le \tau \le \tau_*}\|\kappa\bar{\mathcal{G}}(\tau) - 1\|_{L^\infty} \leq C(M_*^{\frac12}+1)\epsilon,
    \end{equation}
    where $C>0$ is a generic constant.

We begin by converting \eqref{eq:dtbarcalG} into
\begin{equation}
\label{eq:dtbarcalG_rewrite}
\begin{split}
\kappa \partial_\tau \bar{\mathcal{G}} &= \mathcal{C}_0 \partial_{\tau} (U^0)^{\kappa}- \delta w\partial_{\tau}(\lambda^{-3\kappa}\mathcal{F}^{-\kappa}),
\end{split}
\end{equation}
where
\begin{equation}
    \nonumber
    \mathcal{C}_0:= (U^0)^{-\kappa}(0)(1+ \delta\lambda^{-3\kappa}(0)w\mathcal{F}^{-\kappa}(0)).
\end{equation}
Integrating \eqref{eq:dtbarcalG_rewrite} and using $\left. \bar{\mathcal{G}} \right|_{\tau=0}=\frac{1}{\kappa}$, we thus find
\begin{equation}
\nonumber
    \begin{split}
        \kappa \bar{\mathcal{G}} - 1= \mathcal{C}_0 \int_0^\tau \partial_{\tau} (U^0)^{\kappa} d\tilde{\tau}
        - \delta w \int_0^\tau\partial_{\tau} (\lambda^{-3\kappa}\mathcal{F}^{-\kappa})d\tilde{\tau}
        =: T_1 - T_2.
    \end{split}
\end{equation}

    First, we estimate $T_1$. Recall $(U^0)^{-2} = 1-(\partial_\tau\Theta+\bar{\lambda}_{\tau} (\Theta+\zeta))^2$. Then, 
    \begin{equation}\label{dtU0a}
    \begin{split}
        \partial_{\tau} (U^0)^{\kappa} &= \kappa(U^0)^{\kappa+2} \left(\partial_{\tau}\Theta + \bar{\lambda}_{\tau}(\Theta+\zeta)\right)\left(\partial_{\tau}^2\Theta + \partial_{\tau}\bar{\lambda}_{\tau}(\Theta+\zeta) + \bar{\lambda}_{\tau}\partial_{\tau}\Theta\right)\\
        &= \kappa(U^0)^{\kappa+2}\bigg[\bar{\lambda}_{\tau}\partial_{\tau}\bar{\lambda}_{\tau}(\Theta + \zeta)^2 + \partial_{\tau}^2\Theta\left(\partial_{\tau}\Theta + \bar{\lambda}_{\tau}(\Theta+\zeta)\right) + \mathcal{O}(\partial_{\tau}\Theta)\bigg].
    \end{split}
    \end{equation}
    This implies, together with \eqref{est:improvedU0}, that
    \begin{align*}
        |T_1| \lesssim& \int_0^\tau |\bar{\lambda}_{\tau}\partial_{\tau}\bar{\lambda}_{\tau}|(\Theta + \zeta)^2 d\tilde\tau + \left|\int_0^\tau \partial_{\tau}^2\Theta(\partial_{\tau}\Theta + \bar{\lambda}_{\tau}(\Theta+\zeta)) d\tilde\tau\right| + \int_0^\tau |\mathcal{O}(\partial_{\tau}\Theta)|d\tilde\tau\\
        &=: T_{11}+T_{12}+T_{13}.
    \end{align*}
    Since $|\bar{\lambda}_{\tau}| \approx \bar\lambda$, we obtain from the Hardy's the embedding \eqref{est:LinftyHardy1} and \eqref{est:ptlamt} to obtain that $T_{11} \lesssim \delta$. Also, by applying \eqref{est:LinftyHardy1} to $\partial_{\tau}\Theta$ and because $\lambda^{-\frac32\kappa}$ is integrable, we have 
    $$
    T_{13} \lesssim \int_0^\tau \delta^{\frac12}\lambda^{-\frac32\kappa}(\mathcal{E}^{N})^{1/2}  \lesssim (M_*)^{\frac12} \epsilon^{\frac12} \delta^{\frac12},
    $$ 
    where we used \eqref{est:improvedEN} in the last inequality. To bound $T_{12}$, we integrate $\partial_{\tau}$ by parts to obtain that
    \begin{align*}
        T_{12} &\le \frac12 \left|(\partial_{\tau}\Theta(\tau)^2 - \partial_{\tau}\Theta(0)^2)\right| + \left|\bar{\lambda}_{\tau}\partial_{\tau}\Theta(\Theta + \zeta) - \bar{\lambda}_{\tau}(0)\partial_{\tau}\Theta(0)(\Theta(0) + \zeta)\right|\\
        &\quad + \int_0^\tau |\partial_{\tau}\Theta|\left|\partial_{\tau}\bar{\lambda}_{\tau}(\Theta + \zeta) + \bar{\lambda}_{\tau}\partial_{\tau}\Theta\right|d\tilde\tau\\
        &\lesssim \delta^{\frac12}\left((\mathcal{E}^N(0))^{1/2} + (\mathcal{E}^N(\tau))^{1/2}\right) + \int_0^\tau \delta\lambda^{- 3\kappa}\|\partial_{\tau}\Theta\|_{L^\infty} + \bar{\lambda}_{\tau}\|\partial_{\tau}\Theta\|_{L^\infty}^2 d\tilde\tau\\
        &\lesssim \delta^{\frac12}\left((\mathcal{E}^N(0))^{1/2} + (\mathcal{E}^N(\tau))^{1/2}\right) + \delta^{\frac32}\left(E^N(\tau_*)\right)^{1/2} + \delta^{\frac32}E^N(\tau_*)\\
        &\lesssim M_*^{\frac12}\epsilon^{\frac12}\delta^{\frac12},
    \end{align*}
    where we used \eqref{est:LinftyHardy1} and \eqref{est:lambdaasym} in the third inequality, as well as \eqref{est:improvedEN} in the final inequality. Summarizing all the estimates above, we have
    \begin{equation}
        \label{est:U0T1}
        |T_1| \lesssim 
        \delta+
        M_*^{\frac12}\epsilon^{\frac12}\delta^{\frac12}.
    \end{equation}
     Lastly, we control $T_2$. By decomposing
    \begin{align*}
        T_2 = \delta w\int_0^\tau \left((-3\kappa\lambda^{-3\kappa}\bar{\lambda}_{\tau}) \mathcal{F}^{-\kappa} + \lambda^{-3\kappa}(-\kappa\mathcal{F}^{-\kappa-1}\partial_{\tau}\mathcal{F})\right)d\tilde\tau
        =: T_{21} + T_{22}, 
    \end{align*}
    we see that $|T_{21}| \lesssim \delta$ from \eqref{est:lambdaasym}, \eqref{est:improvedU0}, and the bound $|\mathcal{F}-1|\leq \frac{1}{200}$. Additionally, we recall that
    $$
    \partial_{\tau}\mathcal{F} = \partial_{\tau}\left(D_{\zeta}\Theta + D_{\zeta}\left(\frac{\Theta^2}{\zeta} + \frac{\Theta^3}{3\zeta^2}\right)\right).
    $$
    Then an application of Hardy's inequality \eqref{est:LinftyHardy1}, \eqref{est:improvedU0}, the bound $|\mathcal{F}-1|\leq \frac{1}{200}$, and \eqref{est:lambdaasym} yields the bound $|T_{22}| \lesssim M_*^{\frac12}\epsilon^{\frac12}\delta$. In summation, we have 
    \begin{align}|T_2| \lesssim \delta+M_*^{\frac12}\epsilon^{\frac12}\delta.
    \end{align}
    By combining this with \eqref{est:U0T1}, we conclude that
    \begin{align}
    \begin{aligned}
        |\kappa\bar{\mathcal{G}}-1| \leq& C\left(\delta+M_*^{\frac12}\epsilon^{\frac12}\delta^{\frac12}\right)
        \leq C(M_*^{\frac12}+1)\epsilon,
        \end{aligned}
    \end{align}
    where we used $\delta\le \epsilon$ in the final inequality.

\label{lem:Dicoercivity}
    Suppose $\mathcal{D}_i f \in L^2\left([0,\frac34], r^2dr\right)$. Then the following estimate holds:
    \begin{equation}
        \label{est:Dicoercivity}
        \sum_{P_i \in \mathcal{P}_i}\int_0^1 |P_i f|^2 \chi(r) r^2dr \lesssim \int_0^1 |\mathcal{D}_i f|^2 \chi(r) r^2 dr,
    \end{equation}
    where $\chi$ is a bump function supported on $[0,\frac34]$.

\label{lem:Lcommute}
    For any $i > 0$ a positive integer and $f$ a smooth function, there exist smooth functions $\xi_{i,j}(\zeta)$ with $j \ge 0$ such that 
    \begin{equation}
        \label{maincommutation}
        \mathcal{D}_i L_0 f = \mathcal{L}_{i}\mathcal{D}_i f + \sum_{j=0}^{i-1} \xi_{i,j}\mathcal{D}_{i-j}f,
    \end{equation}
    where
    $$
    \xi_{i,j} \in \begin{cases}
        \mathcal{P},& j \text{ is odd},\\
        \mathcal{Q},& j \text{ is even}.
    \end{cases}
    $$

We first recall the following product rule:
\begin{equation}\label{eq:basicproduct}
D_{\zeta}(fg) = D_{\zeta} fg + f\partial_{\zeta} g.
\end{equation}
Following \cite[p. 538]{guo2021continued}, we also have
\begin{equation}\label{DzLk}
    D_{\zeta} L_k f = L^*_{1+k}D_{\zeta} f- (1+k)(w'' + \frac{2}{\zeta}w')D_{\zeta} f,
\end{equation}

\begin{equation}\label{dzLk*}
    \partial_{\zeta} L_k^* f = L_{1+k}\partial_{\zeta} f- (1+k)(w'' - \frac{2}{\zeta}w')\partial_{\zeta} f.
\end{equation}
    Now, we prove \eqref{maincommutation} by induction. For notational convenience, we will denote $p(\zeta)$ as a generic member of $\mathcal{P}$, and $q(\zeta)$ a generic member of $\mathcal{Q}$. The exact expression of $p,q$ might change from line to line.
    \begin{enumerate}
        \item $i = 1$. This case is clear upon using \eqref{DzLk} and realizing that $D_{\zeta} = \mathcal{D}_1$, $w'' \pm 2w'/\zeta \in \mathcal{Q}$:
        $$
        \mathcal{D}_1L_0 f = L^*_{1}\mathcal{D}_1 f - (1+k)(w'' + 2w'/\zeta)\mathcal{D}_1 f = L^*_{1}\mathcal{D}_1 f + q\mathcal{D}_1f.
        $$
        \item $i > 1$. We first discuss the case where $i$ is even. The following elementary fact is useful for the rest of the proof:
        $$
        \partial_{\zeta} p,D_{\zeta} p \in \mathcal{Q},\quad \partial_{\zeta} q \in \mathcal{P}.
        $$
        We remark that $D_{\zeta} q$ is extremely dangerous as $D_{\zeta} 1 = 2/\zeta$. However, we will see that such adverse derivative will never appear thanks to the vanishing properties of weight $w$. By induction hypothesis, we have
        \begin{align*}
            \mathcal{D}_i L_0 f &= \partial_{\zeta} (\mathcal{D}_{i-1}L_0 f ) = \partial_{\zeta}\left(\mathcal{L}_{i-1}\mathcal{D}_{i-1}f + \sum_{j=0}^{i-2}\xi_{i-1,j}\mathcal{D}_{i-1-j}f\right)\\
            &= \partial_{\zeta}\left(L_{i-1}^*\mathcal{D}_{i-1}f\right) + \sum_{j=0}^{i-2}\partial_{\zeta}\left(\xi_{i-1,j}\mathcal{D}_{i-1-j}f\right)\\
            &= L_{i}\mathcal{D}_i f - i(w''-2w'/\zeta)\mathcal{D}_if + \sum_{j=0}^{i-2}\partial_{\zeta}\left(\xi_{i-1,j}\mathcal{D}_{i-1-j}f\right).
        \end{align*}
        It is clear that the second term above has the required structure since $w'' - 2w'/\zeta \in \mathcal{Q}$. Then it suffices for us to consider the final term above. For $0\le j \le i - 2$ being even, we write
        \begin{equation}\label{lemcommuteaux1}
        \begin{split}
        \partial_{\zeta}\left(\xi_{i-1,j}\mathcal{D}_{i-1-j}f\right) &= \partial_{\zeta}(\xi_{i-1,j})\mathcal{D}_{i-1-j}f + \xi_{i-1,j}\partial_{\zeta}\mathcal{D}_{i-1-j}f\\
        &= \partial_{\zeta}(\xi_{i-1,j})\mathcal{D}_{i-1-j}f + \xi_{i-1,j}\mathcal{D}_{i-j}f,
        \end{split}
        \end{equation}
        where we used that $\partial_{\zeta} \mathcal{D}_{i-j-1} = \mathcal{D}_{i-j}$ when $j$ is even (i.e. $i-j-1$ is odd). Moreover, because
        \begin{equation}\label{dzxi}
        \partial_\zeta \xi_{i-1,j} \in \begin{cases}
        \mathcal{P},& j \text{ is even},\\
        \mathcal{Q},& j \text{ is odd},
    \end{cases}
        \end{equation}
        the RHS to \eqref{lemcommuteaux1} has the desired structure. When $j$ is odd, we recall that $\xi_{i-1,j} \in \mathcal{P}$ by the induction hypothesis. Hence, we may write
        $$
        \xi_{i-1,j} = \zeta q_{i-1,j},\quad q_{i-1,j} \in \mathcal{Q}.
        $$
        Then
        \begin{align*}
            \partial_{\zeta}\left(\xi_{i-1,j}\mathcal{D}_{i-1-j}f\right) &= \partial_{\zeta}(\zeta q_{i-1,j}\mathcal{D}_{i-1-j}f) = q_{i-1,j}\mathcal{D}_{i-1-j}f + \zeta\partial_\zeta (q_{i-1,j}\mathcal{D}_{i-1-j}f).
        \end{align*}
        But then we recall that for a function $h$,
        $$
        \zeta D_{\zeta} h = \zeta\partial_{\zeta} h + 2h.
        $$
        Then combining the two pieces of computations above, we have
        \begin{align*}
        \partial_{\zeta}\left(\xi_{i-1,j}\mathcal{D}_{i-1-j}f\right) &= -q_{i-1,j}\mathcal{D}_{i-1-j}f + \zeta D_{\zeta}(q_{i-1,j}\mathcal{D}_{i-1-j}f)\\
        &= -q_{i-1,j}\mathcal{D}_{i-1-j}f + \zeta(q_{i-1,j}\mathcal{D}_{i-j}f + \partial_{\zeta} q_{i-1,j}\mathcal{D}_{i-j-1}f).
        \end{align*}
        This case is thus proved after noticing that $\zeta q_{i-1,j} \in \mathcal{P}$ and $\zeta\partial_{\zeta} q_{i-1,j} \in \mathcal{Q}$. The proof for $i$ odd is similar, where one needs to quote \eqref{DzLk} in place of \eqref{dzLk*}.
    \end{enumerate}

\label{lem:generalproductrule}
Let $ i \in \mathbb{N}$ be given.
    \begin{enumerate}
        \item For any $P \in \mathcal{P}_{i}$, the following identity holds:
        \begin{equation}
            \label{Pproduct}
            P(fg) = \sum_{k=0}^i \sum_{\substack{A \in \mathcal{P}_{k}\\ B \in \bar{\mathcal{P}}_{i-k}}}c^{AB}_k(Af)(Bg),
        \end{equation}
        where $c^{AB}_k$ are real constants.

        \item For any $\bar P \in \bar{\mathcal{P}}_{i}$, the following identities hold:
        \begin{equation}
            \label{Pbarproduct}
            \bar P(fg) = \sum_{k=0}^i \sum_{\substack{A \in \bar{\mathcal{P}}_{k}\\ B \in \bar{\mathcal{P}}_{i-k}}}c^{AB}_k(Af)(Bg),
        \end{equation}
        and
        \begin{equation}
            \label{Pbarproduct2}
            \bar P(fg) = \sum_{k=0}^i \sum_{\substack{A \in \mathcal{P}_{k}\\ B \in \mathcal{P}_{i-k}}}\bar{c}^{AB}_k(Af)(Bg),
        \end{equation}
        where $c^{AB}_k, \bar{c}^{AB}_k$ are real constants.
    \end{enumerate}

\label{lem:leadingorder}
    The following identity holds:
    \begin{align}\label{eq: leading order symmetry}
        \mathcal{D}_i (fg) = (\mathcal{D}_i f) g + \sum_{k=0}^{i-1}\sum_{\substack{A\in \mathcal{P}_k\\B\in\bar{\mathcal{P}}_{i-k}}}c_k^{AB} (Af)(Bg),
    \end{align}
    where $c_k^{AB}$ are real constants. 
    As an immediate corollary, we have
    \begin{equation}\label{commutator [calDi g]f}
        [\mathcal{D}_i, g] f = \sum_{k=0}^{i-1}\sum_{\substack{A\in \mathcal{P}_k\\B\in\bar{\mathcal{P}}_{i-k}}}c_k^{AB} (Af)(Bg).
    \end{equation}

\label{lem: DiZ}
    Let $Z=\frac{1}{\zeta}\left(\zeta\partial_{\zeta}\left(\frac{\Theta}{\zeta}\right)\right)^2$. Then $P_i Z$ verifies the following identity: 
\begin{align}\label{eq:DiZ}
P_i Z = \sum_{1\leq k\leq i}\sum_{\substack{A\in\mathcal{P}_{k+1}\\B\in\mathcal{P}_{i-k+2}}}c_i^{AB}A\Theta B\Theta, \quad P_i\in \mathcal{P}_i.  
\end{align}

Using $\zeta\partial_{\zeta}\left(\frac{\Theta}{\zeta}\right) = D_{\zeta}\Theta-3\frac{\Theta}{\zeta}$, we see that
$$
Z = \frac{1}{\zeta} \left(D_{\zeta}\Theta- 3\frac{\Theta}{\zeta}\right)^2.
$$
We are now ready to show \eqref{eq:DiZ} by induction. When $P_1=D_{\zeta}$, and since $D_{\zeta}\frac{1}{\zeta} = \frac{1}{\zeta^2}$, we have
\begin{equation*}
    \begin{aligned}
D_{\zeta} Z =&\frac{2}{\zeta}\left(D_{\zeta}\Theta- 3\frac{\Theta} {\zeta}\right)\partial_{\zeta} \left(D_{\zeta}\Theta- 3\frac{\Theta} {\zeta}\right) + \frac{1}{\zeta^2}\left(D_{\zeta}\Theta- 3\frac{\Theta} {\zeta}\right)^2\\
=&2\partial_{\zeta} \left(\frac{\Theta}{\zeta}\right)\partial_{\zeta} \left(D_{\zeta}\Theta- 3\frac{\Theta} {\zeta}\right)+\left(\partial_{\zeta}\left(\frac{\Theta}{\zeta}\right)\right)^2\\
=&2\partial_{\zeta} \left(\frac{\Theta}{\zeta}\right)\partial_{\zeta}D_{\zeta}\Theta - 5\left(\partial_{\zeta}\left(\frac{\Theta}{\zeta}\right)\right)^2. 
\end{aligned}
\end{equation*}
Additionally, when $P_1=\frac{1}{\zeta}$, 
\begin{equation*}
  \frac{1}{\zeta} Z =   \left(\partial_{\zeta}\left(\frac{\Theta}{\zeta}\right)\right)^2. 
\end{equation*}
These verify \eqref{eq:DiZ} when $i=1$. Suppose now that \eqref{eq:DiZ} holds for $\ell=1,\cdots,i-1$. If $i$ is odd, $P_iZ = D_{\zeta} P_{i-1}Z$ or $\frac{1}{\zeta}P_{i-1}Z$. In the former case, 
\begin{align*}
    P_i Z &= D_{\zeta} \sum_{1\leq k\leq i-1}\sum_{\substack{A\in\mathcal{P}_{k+1}\\B\in\mathcal{P}_{i-k+1}}}c_i^{AB}A\Theta B\Theta\\
   &=
   \begin{cases}
\sum_{1\leq k\leq i-1}\sum_{\substack{A\in\mathcal{P}_{k+1}\\B\in\mathcal{P}_{i-k+1}}}c_i^{AB}(\partial_{\zeta} A\Theta B\Theta+A\Theta D_{\zeta} B\Theta),\quad k\text{ is even};\\
\sum_{1\leq k\leq i-1}\sum_{\substack{A\in\mathcal{P}_{k+1}\\B\in\mathcal{P}_{i-k+1}}}c_i^{AB}(D_{\zeta} A\Theta B\Theta+A\Theta \partial_{\zeta} B\Theta),\quad k\text{ is odd}.
   \end{cases}
\end{align*}
In the latter case, 
\begin{align*}
    P_i Z &= \frac{1}{\zeta}\sum_{1\leq k\leq i-1}\sum_{\substack{A\in\mathcal{P}_{k+1}\\B\in\mathcal{P}_{i-k+1}}}c_i^{AB}A\Theta B\Theta\\
   &=
   \begin{cases}
\sum_{1\leq k\leq i-1}\sum_{\substack{A\in\mathcal{P}_{k+1}\\B\in\mathcal{P}_{i-k+1}}}c_i^{AB}A\Theta\left(\frac{1}{\zeta}B\Theta\right),\quad k\text{ is even};\\
\sum_{1\leq k\leq i-1}\sum_{\substack{A\in\mathcal{P}_{k+1}\\B\in\mathcal{P}_{i-k+1}}}c_i^{AB}\left(\frac{1}{\zeta}A\Theta\right)B\Theta,\quad k\text{ is odd}.
   \end{cases}
\end{align*}
On the other hand, if $i$ is even, then 
\begin{align*}
    \mathcal{D}_i Z &= \partial_{\zeta} \sum_{1\leq k\leq i-1}\sum_{\substack{A\in\mathcal{P}_{k+1}\\B\in\mathcal{P}_{i-k+1}}}c_i^{AB}A\Theta B\Theta\\
   &=
   \begin{cases}
\sum_{1\leq k\leq i-1}\sum_{\substack{A\in\mathcal{P}_{k+1}\\B\in\mathcal{P}_{i-k+1}}}c_i^{AB}(\partial_{\zeta} A\Theta B\Theta+A\Theta \partial_{\zeta} B\Theta),\quad k\text{ is even};\\
\sum_{1\leq k\leq i-1}\sum_{\substack{A\in\mathcal{P}_{k+1}\\B\in\mathcal{P}_{i-k+1}}}c_i^{AB}\left(\left(D_{\zeta}-\frac{2}{\zeta}\right) A\Theta B\Theta+A\Theta \left(D_{\zeta}-\frac{2}{\zeta}\right)B\Theta\right),\quad k\text{ is odd}.
   \end{cases}
\end{align*}
This completes the induction.

\label{lem:Fnonlinear}
    Let $f$ be a smooth function and $P_i \in \mathcal{P}_i$ for $i \ge 1$. Then the following identities hold:
    \begin{equation}
        \label{eq:thetasquare}
        P_i\left(\frac{f^2}{\zeta}\right) = \sum_{\substack{A_{1,2} \in \mathcal{P}_{l_1,l_2},\\l_1 + l_2 = i+1,\\l_1,l_2 \le i}}c^{l_1, l_2}_{i}(A_1 f)(A_2f),
    \end{equation}
    \begin{equation}
        \label{eq:thetacube}
        P_i\left(\frac{f^3}{\zeta^2}\right) = \sum_{\substack{A_{1,2,3} \in \mathcal{P}_{l_1,l_2,l_3},\\l_1 + l_2 + l_3 = i+1,\\l_1,l_2,l_3 \le i}}c^{l_1, l_2, l_3}_{i}(A_1 f)(A_2f)(A_3f).
    \end{equation}

We prove \eqref{eq:thetasquare} by induction, and the proof of \eqref{eq:thetacube} will be similar. If $i = 1$, we either have $P_1 = D_{\zeta}$ or $P_1 = \zeta^{-1}$. If the former case hold, then we have
    \begin{align*}
    D_{\zeta}\left(\frac{f^2}{\zeta}\right) &= D_{\zeta} f \frac{f}{\zeta} + f\partial_{\zeta}\left(\frac{f}{\zeta}\right)= 2D_{\zeta} f\frac{f}{\zeta} -3\left(\frac{f}{\zeta}\right)^2,
    \end{align*}
    which verifies \eqref{eq:thetasquare} when $i = 1$. If the case $P_1 = \zeta^{-1}$ holds, then easily $P_1(f^2/\zeta) = (f/\zeta)^2$, which also verfies the base case.

    To complete the inductive step, we assume that $i \ge 1$ is even. Then $P_{i+1} = VP_{i}$, where $V = D_{\zeta}$ or $\zeta^{-1}$. Then
    \begin{align*}
    P_{i+1}\left(\frac{f^2}{\zeta}\right) &= V\sum_{\substack{A_{1,2} \in \mathcal{P}_{l_1,l_2},\\l_1 + l_2 = i+1,\\l_1,l_2 \le i}}(A_1 f)(A_2f).
    \end{align*}
    Since $i$ is even and $l_1 + l_2 = i+1$, we may without loss assume that $l_1$ is even and $l_2$ is odd, which implies that $l_1 \le i$ and $l_2 \le i-1$. If $V = D_{\zeta}$, then
    \begin{align*}
    P_{i+1}\left(\frac{f^2}{\zeta}\right) &= \sum_{\substack{A_{1,2} \in \mathcal{P}_{l_1,l_2},\\l_1 + l_2 = i+1,\\l_1,l_2 \le i}}(D_{\zeta} A_1 f)(A_2f) + (A_1 f)(\partial_{\zeta} A_2 f),
    \end{align*}
    which completes the inductive step since $D_{\zeta} A_1 \in \mathcal{P}_{l_1 + 1}$, $\partial_{\zeta} A_2 \in \mathcal{P}_{l_2 + 1}$. If $V = \zeta^{-1}$, then
    \begin{align*}
    P_{i+1}\left(\frac{f^2}{\zeta}\right) &= \sum_{\substack{A_{1,2} \in \mathcal{P}_{l_1,l_2},\\l_1 + l_2 = i+1,\\l_1,l_2 \le i}}(\zeta^{-1}A_1 f)(A_2f),
    \end{align*}
    which also verfies the inductive step since $\zeta^{-1} A_1 \in \mathcal{P}_{l_1 + 1}$. The case where $i$ is odd is similar.

\label{lem:chainrule}
    Let $a \in \mathbb{R}$, $i \in \mathbb{N}$ be given and fix a vectorfield $W \in \bar{\mathcal{P}}_i$. Then the following holds for any smooth function $f$:
    \begin{equation}
        \label{eq:chainrule}
        W(f^a) = \sum_{k=1}^i f^{a-k}\sum_{\substack{i_1 +\hdots i_k = i\\W_{j} \in \bar{\mathcal{P}}_{i_j}}}c_{k,i_i,\hdots,i_k}\prod_{j=1}^k W_{j} f.
    \end{equation}

\label{lem:hardy0}
    Let $m$ be a positive integer, and $u: B_1(0) \to \mathbb{R}$ be a smooth function. Then the following inequalities hold:
    \begin{equation}
        \label{est:Linftyu}
        \|u\|_{L^\infty}^2 \lesssim \sum_{i=1}^2 \int_0^\frac34 |B_i u|^2 r^2dr + \sum_{i = 0}^{m+1} \int_\frac14^1 w^{\alpha - \lfloor\alpha\rfloor + 2m}|B_i u|^2 dr,
    \end{equation}
    and
    \begin{equation}
        \label{est:Linftyur}
        \|ru\|_{L^\infty}^2 \lesssim \sum_{i=0}^1 \int_0^\frac34 |B_i u|^2 r^2dr + \sum_{i = 0}^{m+1} \int_\frac14^1 w^{\alpha - \lfloor\alpha\rfloor + 2m}|B_i u|^2 dr,
    \end{equation}
    where $B_i = \mathcal{D}_i$ or $\bar{\mathcal{D}}_i$, $i = 1,\hdots, m+1$. Moreover,
    \begin{equation}
        \label{est:Linftyu/r}
        \|\frac{u}{r}\|_{L^\infty}^2 \lesssim \sum_{i=2}^3 \int_0^\frac34 |\mathcal{D}_i u|^2 r^2dr + \sum_{i = 0}^{m+1} \int_\frac14^1 w^{\alpha - \lfloor\alpha\rfloor + 2m}|\mathcal{D}_i u|^2 dr,
    \end{equation}

Let $\Theta, \partial_{\tau}\Theta \in B^N$, $\partial_{\tau}^2\Theta \in B^{N-1}$. Then the following holds:
    \begin{enumerate}
        \item For $\frac{N-\alpha}{2} \le k \le N$, $P_k \in \mathcal{P}_k$,
        \begin{equation}
        \label{est:L2Hardy}
        \delta^{-1}\lambda^{3\kappa}\int_0^1 w^{\alpha + 2k - N}|P_k\partial_{\tau}\Theta|^2 r^2dr + \int_0^1 w^{\alpha + 2k - N}|P_k \Theta|^2 r^2 dr \lesssim \mathcal{E}^N.
    \end{equation}

    \item If we further have $\sum_{j = 0}^N \int_0^1 w^{\alpha + j + 1}|\mathcal{D}_j \Theta|^2 r^2 dr < \infty$, then for $\frac{N-\alpha - 1}{2} \le k \le N$, $P_k \in \mathcal{P}_k$:
    \begin{equation}
        \label{est:L2Hardy2}
        \int_0^1 w^{\alpha + 2k + 1 - N} |P_{k+1}\Theta|^2 r^2 dr \lesssim \mathcal{E}^N.
    \end{equation}
    \item For $\frac{N-\alpha - 1}{2} \le k \le N-1$, $P_k \in \mathcal{P}_k$,
    \begin{equation}
        \label{est:L2Hardypt2}
        \int_0^1 w^{\alpha + 2k + 1 - N}|P_k\partial_{\tau}^2\Theta|^2 r^2dr \lesssim \mathcal{S}^N.
    \end{equation}
    \end{enumerate}

\label{lem:LinftyHardy}
    Let $\Theta, \partial_{\tau}\Theta \in B^N$ and $\partial_{\tau}^2\Theta \in B^{N-1}$. Then the following holds:
    \begin{enumerate}
        \item For any nonnegative integer $k$ such that $k \le \frac{N - \lfloor\alpha\rfloor-2}{2}$ and given $P_k \in \mathcal{P}_k$, we have
        \begin{equation}
            \label{est:LinftyHardy1}
            \delta^{-1}\lambda^{3\kappa}\|P_k\partial_{\tau}\Theta\|_{L^\infty}^2 + \|P_k \Theta\|_{L^\infty}^2 \lesssim \mathcal{E}^N.
        \end{equation}

        \item For any nonnegative integer $k$ such that $k \le \frac{N - \lfloor\alpha\rfloor-2}{2}$ and given $\bar P_k \in \bar{\mathcal{P}}_k$, we have
        \begin{equation}
            \label{est:LinftyHardy2}
            \delta^{-1}\lambda^{3\kappa}\|\bar P_k\partial_{\tau}\left(\frac{\Theta}{\zeta}\right)\|_{L^\infty}^2 + \|\bar P_k \left(\frac{\Theta}{\zeta}\right)\|_{L^\infty}^2 \lesssim \mathcal{E}^N.
        \end{equation}

        \item For any nonnegative integer $k$ such that $k \le \frac{N - \lfloor\alpha\rfloor-3}{2}$ and given $P_k \in \mathcal{P}_k$, we have
        \begin{equation}
            \label{est:LinftyHardypt2}
            \|P_k\partial_{\tau}^2\Theta\|_{L^\infty}^2  \lesssim \mathcal{S}^N.
        \end{equation}
    \end{enumerate}

The proof follows similarly to that of Lemma C.4 in \cite{guo2021continued}, so we are content with sketching the modified proof here. Invoking \eqref{est:Linftyu} with $u = P_k \Theta$ and $m = \lfloor \alpha \rfloor + k + 1$, we arrive at
    \begin{align*}
        \|P_k \Theta\|_{L^\infty} &\lesssim \sum_{i=1}^2 \int_0^\frac34 |B_i P_k \Theta|^2 r^2dr + \sum_{i = 0}^{\lfloor \alpha \rfloor + k + 2} \int_\frac14^1 w^{\alpha - \lfloor\alpha\rfloor + 2(\lfloor \alpha \rfloor + k + 1)}|B_i P_k \Theta|^2 dr
    \end{align*}
    Selecting $B_i = \mathcal{D}_i$ if $k$ is even and $B_i = \bar{\mathcal{D}}_i$ if $k$ is odd, we have $B_iP_k \in \mathcal{P}_{k+i}$. Since $i + k \le 2 + \frac{N-\lfloor\alpha\rfloor - 2}{2} \le N$ and $w \gtrsim 1$ in $[0,\frac34]$, the first sum is bounded by $\mathcal{E}^N$ after invoking the coercivity estimate \eqref{est:Dicoercivity}. On the other hand, since $w \lesssim 1$, then $w^{\alpha - \lfloor\alpha\rfloor + 2(\lfloor \alpha \rfloor + k + 1)} \lesssim w^{\alpha + i + k}$ for $i \le \lfloor \alpha \rfloor + k + 2$. Then the second sum is also bounded by $\mathcal{E}^N$ after invoking coercivity \eqref{est:Dicoercivity} again. Other estimates follow similarly.

\label{lem:LinftyHardyweighted}
Let $\Theta,\partial_{\tau}\Theta \in B^N$ and $\partial_{\tau}^2\Theta \in B^{N-1}$. Then the following holds:
\begin{enumerate}
    \item Given any $0 \le k \le N - 4$ and $P_{k+2} \in \mathcal{P}_{k+2}$, we have
    \begin{equation}
        \label{est:LinftyHardyweighted1N-4}
        \delta^{-1}\lambda^{3\kappa}\|w^kP_{k+2}\partial_{\tau}\Theta \|_{L^\infty}^2 + \|w^kP_{k+2}\Theta\|_{L^\infty}^2 \lesssim \mathcal{E}^N.
    \end{equation}
    For $k = N-3$ and $P_{N-1} \in \mathcal{P}_{N-1}$, we have
    \begin{equation}
        \label{est:LinftyHardyweighted1N-3}
        \delta^{-1}\lambda^{3\kappa}\|\zeta w^{N-3}P_{N-1}\partial_{\tau}\Theta \|_{L^\infty}^2 + \|\zeta w^{N-3}P_{N-1}\Theta\|_{L^\infty}^2 \lesssim \mathcal{E}^N.
    \end{equation}

    \item Given any $0 \le k \le N - 5$ and $P_{k+2} \in \mathcal{P}_{k+2}$, we have
    \begin{equation}
        \label{est:LinftyHardyweightedpt2}
        \|w^kP_{k+2}\partial_{\tau}^2\Theta \|_{L^\infty}^2 \lesssim \mathcal{S}^N.
    \end{equation}

    \item For any $0 \le k \le N-5$ and $\bar P_{k+2} \in \bar{\mathcal{P}}_{k+2}$,
    \begin{equation}
        \label{est:LinftyHardyweighted2N-5}
        \delta^{-1}\lambda^{3\kappa}\|w^k\bar P_{k+2}\partial_{\tau}\left(\frac{\Theta}{\zeta}\right) \|_{L^\infty}^2 + \|w^k\bar P_{k+2}\left(\frac{\Theta}{\zeta}\right)\|_{L^\infty}^2 \lesssim \mathcal{E}^N.
    \end{equation}
    For $k = N-4$ and $\bar P_{N-2} \in \bar{\mathcal{P}}_{N-2}$, we have
    \begin{equation}
        \label{est:LinftyHardyweighted2N-4}
        \delta^{-1}\lambda^{3\kappa}\|\zeta w^{N-4}\bar P_{N-2}\partial_{\tau}\left(\frac{\Theta}{\zeta}\right) \|_{L^\infty}^2 + \|\zeta w^{N-4}\bar P_{N-2}\left(\frac{\Theta}{\zeta}\right)\|_{L^\infty}^2 \lesssim \mathcal{E}^N.
    \end{equation}
\end{enumerate}

\label{L:Inverse_odd_function}
    Let $\psi \colon [0,a]\rightarrow \mathbb{R}$ be invertible, $C^1$, and have the form
    \begin{align*}
        \psi(\zeta) = \zeta \mathbf{F}(\zeta^2),
    \end{align*}
    where $\mathbf{F}(0) \neq 0$. Then, near the origin, we can write 
    \begin{align*}
        \psi^{-1}(\zeta) = \zeta \mathbf{G}(\zeta^2),
    \end{align*}
    where $\mathbf{G}(0)\neq 0$.

Set $s=\zeta^2$ and $\Psi(s) = s (\mathbf{F}(s))^2$. Then $\Psi^\prime(0) >0$ and $\Psi$ is a $C^1$ diffeomorphism in a neighborhood of the origin. Let $\alpha=\psi(\zeta)=\zeta \mathbf{F}(\zeta^2)$, so $\alpha^2=\zeta^2 (\mathbf{F}(\zeta^2))^2=\Psi(\zeta^2)$, thus $\Psi^{-1}(\alpha^2) = \zeta^2$ for small $\zeta$. Therefore
    \begin{align*}
        \psi^{-1}(\alpha) = \zeta = \frac{\alpha}{\mathbf{F}(\zeta^2)} = \frac{\alpha}{\mathbf{F}(\Psi^{-1}(\alpha^2))} = \alpha \mathbf{G}(\alpha^2)
    \end{align*}
    where $\mathbf{G}(s) = \frac{1}{\mathbf{F}(\Psi^{-1}(s))}$ satisfies $\mathbf{G}(0) \neq 0$.

\label{L:calD_odd_functions}
    Let $\mathsf{f} \in C^{k}([0,1])$ satisfy $\partial_\zeta^{2\ell}\mathsf{f}(0)=0$, $2\ell \leq k$. Then
\begin{align*}
    \mathcal{D}_{2\ell} \mathsf{f}(0) & = 0, \, 2\ell \leq k,
    \\
    \mathcal{D}_{2\ell+1} \mathsf{f}(0) & = \text{finite value }, \, 2\ell+1 \leq k,
\end{align*}
where we recall that $\mathcal{D}_\ell$ is given by 
\eqref{calDj}. Moreover,
\begin{align*}
    \| \mathcal{D}_\ell \mathsf{f} \|_{L^\infty([0,1])} \lesssim \| \mathsf{f} \|_{C^\ell([0,1]), }\, \ell \leq k.
\end{align*}

For notational convenience, let us write $\mathsf{L} := \partial_\zeta D_{\zeta}$, where we recall from \eqref{E:Primitive_weighted_derivative} that $D_{\zeta} = \frac{1}{\zeta^2}\partial_{\zeta} (\zeta^2\cdot) = \partial_{\zeta} + \frac{2}{\zeta}$. Then $\mathcal{D}_{2\ell} = \mathsf{L}^\ell$ and $\mathcal{D}_{2\ell+1}= D_{\zeta} \mathsf{L}^\ell$.

Near the origin, we can write
\begin{align*}
    \mathsf{f}(\zeta) = \zeta \mathbf{F}(\zeta^2),
\end{align*}
for some $C^k$ function $\mathbf{F}$. With $s=\zeta^2$, we have $\zeta^2 \mathsf{f}(\zeta) = \zeta^3 \mathbf{F}(s)$ and then
\begin{align*}
    \partial_\zeta (\zeta^2 \mathsf{f}(\zeta)) = \partial_\zeta(
    \zeta^3 \mathbf{F}(s) )
    = 3\zeta^2 \mathbf{F}(s) + 2\zeta^4 \mathbf{F}^\prime(s),
\end{align*}
so that dividing by $\zeta^2$ the operator on LHS becomes $D_{\zeta}$ and we get 
\begin{align}
    \label{E:Generic_Dz}
    D_{\zeta} \mathsf{f}(\zeta) = 3\mathbf{F}(s) + 2s\mathbf{F}^\prime(s),
\end{align}
which is a function only of $s=\zeta^2$, i.e., even in $\zeta$, thus it extends continuously to $\zeta=0$. Hence
$D_{\zeta} \mathsf{f}(0)= 3\mathbf{F}(0)$. Applying $\partial_\zeta$ to \eqref{E:Generic_Dz} we then obtain 
\begin{align}
    \label{E:Generic_L}
    \mathsf{L} \mathsf{f}(\zeta) = \zeta (10 \mathbf{F}^\prime(s) + 4s\mathbf{F}^{\prime\prime}(s) ).
\end{align}
The RHS of \eqref{E:Generic_L} is of the form $\zeta$ times a function of $s=\zeta^2$, thus it extends continuously to $\zeta=0$ so that $\mathsf{L}\mathsf{f}(0) = 0$.

Define recursively
\begin{align*}
    \mathbf{F}_{\ell+1} & := \mathsf{L} \mathbf{F}_\ell
    \\
    &= 10 \mathbf{F}^\prime_\ell + 4\zeta^2\mathbf{F}^{\prime\prime}_\ell,
\end{align*}
with $\mathbf{F}_0 := \mathbf{F}$. Then \eqref{E:Generic_L} says that
\begin{align*}
    \mathsf{L} \mathsf{f}(\zeta) = \zeta \mathbf{F}_1(\zeta^2).
\end{align*}
Applying to $\mathsf{L} \mathsf{f}$ the same reasoning that led to \eqref{E:Generic_L} and proceeding inductively gives
\begin{align*}
    \mathsf{L}^\ell\mathsf{f}(\zeta) = \zeta \mathbf{F}_\ell(\zeta^2)
\end{align*}
and $\mathsf{L}^\ell\mathsf{f}(0)=0$. Also, applying $D_{\zeta}$ to $\mathsf{L}^\ell\mathsf{f}$ gives, as in \eqref{E:Generic_Dz},
\begin{align*}
    D_{\zeta} (\mathsf{L}^\ell\mathsf{f})(\zeta) = 3 \mathbf{F}_\ell(\zeta^2) + 2\zeta^2\mathbf{F}^\prime_\ell(\zeta^2),
\end{align*}
and thus $D_{\zeta} (\mathsf{L}^\ell\mathsf{f})(0)$ is a well-defined finite value. The norm statement follows from the RHS of the above expressions for $\mathsf{L}^\ell$ and $D_{\zeta} (\mathsf{L}^\ell)$.

The proof is given in several steps.

\medskip
\noindent\textbf{Step 1} (Radially symmetric data  launches radially symmetric solutions). Since the variables in \eqref{eq:momlagmain} assume a spherically symmetric solution to \eqref{eq:RE}, we first need to verify that such solutions are spherically symmetric if the initial data is. The argument is standard (see \cite{MR1724661}), but since it has not been explicitly written in a physical vacuum boundary context, we provide it here.

By \cite{disconzi2022relativistic}, there exists a classical solution $(\rho,u^i)$ to equations \eqref{eq:RE} defined on
\begin{align}
    \label{E:Moving_domain_spherically_symmetric_LWP}
    \bigcup_{0 \leq t < T^*} \{ t \} \times \Omega_t,
\end{align}
for some $T^*>0$, where $\Omega_t$ is given by \eqref{def: moving domain Omega_t} and taking the given data $(\mathring{\rho},\mathring{u}^i)$ at $t=0$, provided that
\begin{align}
        \label{E:k_DIT_LWP}
        2k &> 5 +\frac{1}{\kappa}.
\end{align}
Condition \eqref{E:k_DIT_LWP} is satisfied in view of \eqref{E:Fixed_N_bound} and \eqref{E:N_k_relation}. Moreover, such solution satisfies the physical vacuum boundary condition.

Let $\mathsf{R} \in SO(3)$ and define
\begin{align*}
    \rho_\mathsf{R}(t,x) &:= \rho(t, \mathsf{R}^{-1} x),
    \\
    u^i_\mathsf{R}(t,x) & := \mathsf{R}\indices{^i_j}  u^j(t,\mathsf{R}^{-1} x), 
\end{align*}
which are defined in the rotated domain
\begin{align*}
    & \bigcup_{0 \leq t < T^*} \{ t \} \times \Omega_t^\mathsf{R},
    \\
    & \Omega_t^\mathsf{R} := \mathsf{R}(\Omega_t) := \{ \mathsf{R}x \, | \, x \in \Omega_t \}.
\end{align*}
The time component of the four velocity transforms as 
\begin{align*}
    u^0_\mathsf{R}(t,x) := u^0(t,\mathsf{R}^{-1}x), 
\end{align*}
so that \eqref{eq: RE_normalization} is preserved in view of the invariance of the Minkowski metric under rotations. Since $SO(3) \subset \text{Lorentz group}$ and the Lorentz group maps solutions to relativistic Euler equations into solutions, we have that $(\rho_\mathsf{R},u^i_\mathsf{R})$ also solves \eqref{eq:RE}. 

Next, we verify that $(\rho_\mathsf{R},u^i_\mathsf{R})$ satisfies the physical vacuum boundary condition in the rotated domain. First, observe that if $x \in \partial \Omega_t^\mathsf{R}$, then $\mathsf{R}^{-1}x \in \partial \Omega_t$ and therefore $\rho_\mathsf{R}(t,x) = \rho(t,\mathsf{R}^{-1}x) =0$, so that $\rho_\mathsf{R}$ vanishes on the boundary of the rotated domain; we also see that $\rho_\mathsf{R}$ remains positive away from the boundary. The sound speed squared in the rotated domain is given by $c_{s,\mathsf{R}}^2 = (1+\kappa) \rho_\mathsf{R}^\kappa$. Because $\mathsf{R}$ is an isometry of $\mathbb{R}^3$, we have that $\text{dist(}x,\partial\Omega_t^\mathsf{R})=\text{dist}(\mathsf{R}^{-1}x,\partial\Omega_t)$. Therefore
\begin{align*}
    c_{s,\mathsf{R}}^2(t,x) = (1+\kappa) \rho^\kappa_\mathsf{R}(t,x) = (1+\kappa)\rho^\kappa(t,\mathsf{R}^{-1}x) = c_s^2(t,\mathsf{R}^{-1}x) \approx 
    \text{dist}(\mathsf{R}^{-1}x,\partial\Omega_t)
    =\text{dist(}x,\partial\Omega_t^\mathsf{R}),
\end{align*}
i.e., $c_{s,\mathsf{R}}^2$ is comparable to the distance to the boundary in the rotated domain. Finally, to verify the kinematic boundary condition that the four-velocity is tangent to the free-boundary in spacetime for the rotated quantities (or equivalently, that the rotated domain is advected by the rotated velocity), we  observe that if $(t,\gamma(t)) \subset \cup_{0\leq t < T^*} \{t\} \times \partial\Omega_t$ is a fluid-particle trajectory, so that
\begin{align*}
    \frac{d}{dt}\gamma(t) = \frac{u^i}{u^0}(t,\gamma(t)),
\end{align*}
then the rotated trajectory $(t,\gamma_\mathsf{R}(t)) = (t, \mathsf{R} \gamma(t))$ is such that $(t,\gamma_\mathsf{R}(t)) \subset  \cup_{0\leq t < T^*} \{t\} \times \partial\Omega^\mathsf{R}_t$ and
\begin{align*}
     \frac{d}{dt}\gamma_\mathsf{R}(t) = \mathsf{R} \frac{d}{dt} \gamma(t) = \left( \mathsf{R} \frac{u^i}{u^0} \right)(t,\gamma(t)) = \frac{\mathsf{R}\indices{^i_j} u^j(t,\gamma(t))}{u^0(t,\gamma(t))}  
     =
     \frac{\mathsf{R}\indices{^i_j} u^j(t,\mathsf{R}^{-1}\gamma_\mathsf{R}(t))}{u^0(t,\mathsf{R}^{-1}\gamma_\mathsf{R}(t))}
     =\frac{u^i_\mathsf{R}(t,\gamma_\mathsf{R}(t))}{u^0_\mathsf{R}(t,\gamma_\mathsf{R}(t))},
\end{align*}
as needed.

At $t=0$ we have
\begin{align*}
    \rho_\mathsf{R}(0,x) &= \rho(0,\mathsf{R}^{-1}x) = \mathring{\rho}(\mathsf{R}^{-1}x)  = \mathring{\rho}(x),
    \\
    u^i_\mathsf{R}(0,x) & := \mathsf{R}\indices{^i_j}  u^j(0,\mathsf{R}^{-1} x)
    = \mathsf{R}\indices{^i_j}  \mathring{u}^j(\mathsf{R}^{-1} x)
    =
    \mathring{u}^j(x),
\end{align*}
where the last equality on each line follows from the assumption that the data is spherically symmetric. Thus, $(\rho_\mathsf{R},u^i_\mathsf{R})$ and $(\rho,u^i)$ are two solutions to \eqref{eq:RE} satisfying the physical vacuum boundary condition and taking the same data at time zero. By uniqueness (also established in \cite{disconzi2022relativistic}), they must agree, so that for all $0 \leq t < T^*$, $\Omega_t = \Omega_t^\mathsf{R}$, $\rho_\mathsf{R}(t,x) =\rho(t,x)$, $u_\mathsf{R}^i(t,x)=u^i(t,x)$, thus in particular
\begin{align*}
    \rho(t, \mathsf{R}^{-1} x) = \rho(t,x),
    \\
    \mathsf{R}\indices{^i_j}  u^j(t,\mathsf{R}^{-1} x) = u^i(t,x), 
\end{align*}
i.e., $(\rho,u^i)$ is spherically symmetric. (In particular, each $\Omega_t$ must be a ball.)

\medskip
\noindent\textbf{Step 2} (Definiteness of the change of variables at the level of data). Here, we follow the arguments of Section \ref{sect: setup} and check that the procedure is well defined at the level of the data. Throughout, we will refer to expressions from Section \ref{sect: setup} that involve $\rho$, $u^i$, and $u^0$, but it should be understood that they are to be taken with $\mathring{\rho}$, $\mathring{u}^i$, and $\mathring{u}^0$ instead. We will refer to expressions as being well defined to mean that they are determined uniquely in terms of the data $(\mathring{\rho},\mathring{u}^i)$ and the fixed parameters in the statement of the Theorem.
We will not track the regularity of the change of variables in this step because this will be done further below for spacetime quantities, from which in particular we can verify the regularity of the data $(\Theta_0,U_0)$ constructed out of $(\mathring{\rho},\mathring{u}^i)$.

In view of our assumption on the data, \eqref{ansatz radial symmetry} and \eqref{u00} are well defined.
The ODE defining $\lambda$ in \eqref{lambdaODEt}
depends only on $\delta$, $\kappa$, and the initial conditions \eqref{lambdaODEt_data} involve only the parameters $\lambda_0$ and $\lambda_1$. Thus, the change of variables \eqref{defn:scaling} is well-defined, as are the modified velocity $V$ in \eqref{modvel} and the expression for the time component of $\mathring{u}^0$ in \eqref{u0}.
It follows that $\partial_s\eta$ in \eqref{E:d_eta_d_s} is well defined at $s=0$ in terms of the data and $\eta_0$. It follows that $f$, $U$, and $U^0$ in \eqref{E:f_and_U_of_s} are also well defined at $s=0$, as is  $\mathcal{F}$ in \eqref{E:Jac_det_def}. By \eqref{E:d_tau_d_s} and $\partial_\tau = \lambda^{-\frac{3}{2}\kappa}\partial_s$, all these quantities are also well defined at $\tau=0$, thus in terms of the data and $\eta_0$. 

To fix $\eta_0$, we invoke \eqref{gauge fixing}, but also note that \eqref{gauge fixing} imposes a constraint. Integrating \eqref{gauge fixing} and recalling that $w_\delta = \delta w$,
\begin{align*}
   \int_0^1 \mathcal{F}_0 f_0 \zeta^2 d\zeta = \int_0^1 (\delta w)^{\frac1\kappa} \zeta^2 d\zeta.
\end{align*}
The LHS is $\frac{1}{4\pi}M_\text{ref}$ by \eqref{E:rho_ref} and \eqref{E:Reference_mass}, whereas the RHS is $\frac{1}{4\pi}M$ in view of \eqref{E:f_and_U_of_s}, \eqref{E:Jac_det_def},  \eqref{E:d_tau_d_s}, a change of variables, and \eqref{E:Initial_mass}. The constraint $M=M_\text{ref}$ is satisfied by \eqref{E:Mass_constraint}.

It now follows from the above that $\Theta(0,\cdot)$ given by \eqref{E:Theta_def} and $\partial_\tau \Theta(0,\cdot)$ obtained from \eqref{E:d_eta_d_s}, and \eqref{E:Theta_def}, \eqref{E:d_tau_d_s}, are uniquely determined in terms of the data (and the gauge choice \eqref{gauge fixing}).

To show that $(\Theta_0,U_0)=(0,0)$ if $\mathring{\rho}=\mathring{\rho}_{\text{ref}}$ and $\mathring{u}^i=\mathring{u}^i_{\text{ref}}$, it suffices to verify that for such data we have $V(0,\cdot)=0$ and that \eqref{gauge fixing} is satisfied by taking $\eta_0(\zeta)=\zeta$. Both statements are a direct consequence of following the above steps in the construction of $(\Theta_0,U_0)$ using $(\mathring{\rho},\mathring{u}^i)=(\mathring{\rho}_{\text{ref}},\mathring{u}^i_{\text{ref}})$.

This establishes item 1) of the Theorem.

\medskip
\noindent\textbf{Step 3} (Spherically symmetric solutions to \eqref{eq:RE} give rise to solutions to \eqref{eq:momlagmain}). By Step 1 and \cite{disconzi2022relativistic}, there exists a unique spherically symmetric classical solution ($\rho,u^i)$ to \eqref{eq:RE} defined on \eqref{E:Moving_domain_spherically_symmetric_LWP} for some $T>0$, and taking the given data at $t=0$. In view of \eqref{E:d_tau_d_s}, if we set
\begin{align}
    \label{E:Time_existence_Lagrangian}
    \tau^* := \int_0^{T^*} \frac{1}{\lambda(t)} dt,
\end{align}
then the procedure in Section \ref{sect: setup} immediately produces a solution $(\Theta,\partial_\tau\Theta)$ defined for $0\leq \tau < \tau^*$ and taking the data $(\Theta_0,U_0)$ produced in Step 2, provided all steps in Section \ref{sect: setup} are justified. This, in turn, is a matter of verifying that there is enough regularity to carry out all steps. The regularity of $(\Theta,\partial_\tau\Theta)$ is investigated in the next step, which shows in particular that $(\Theta,\partial_\tau\Theta)$ is at least (in fact, much better) $C^2([0,\tau^*)\times[0,1])\times C^1([0,\tau^*)\times[0,1])$, hence a classical solution.

Uniqueness of \eqref{eq:momlagmain} for the class of data $(\Theta_0,U_0)$ constructed out of $(\mathring{\rho},\mathring{u}^i)$ in Step 2 follows from uniqueness of \eqref{eq:RE} (established in \cite{disconzi2022relativistic}).

This establishes the existence and uniqueness part in item 2) of the Theorem.

\medskip
\noindent\textbf{Step 4} (Spacetime and radial regularity). The solution $(\mathsf{r},\mathsf{v}^i)$ given by \cite{disconzi2022relativistic} has regularity
\begin{align*}
    (\mathsf{r}(t,\cdot),\mathsf{v}^i(t,\cdot)) & \in \mathcal{H}_\mathsf{r}^{2k}(\Omega_t), 
    \\
    (\partial_t\mathsf{r}(t,\cdot),\partial_t\mathsf{v}^i(t,\cdot)) & \in \mathcal{H}_\mathsf{r}^{2k-1}(\Omega_t),
\end{align*}
from which follows, in light of \eqref{E:N_k_relation} and \eqref{E:Weighted_embedding_DIT}, that
\begin{align*}
    (\mathsf{r}(t,\cdot),\mathsf{v}^i(t,\cdot)) &\in C^{N+2}(\overline{\Omega_t}),
    \\
    (\partial_t\mathsf{r}(t,\cdot),\partial_t \mathsf{v}^i(t,\cdot)) &\in C^{N+1}(\overline{\Omega_t}). 
\end{align*}
From the equations of motion we then obtain standard regularity for time derivatives, where each $\partial_t$ corresponds to one lower spatial regularity. From \eqref{E:New_sound_and_velocity} and the physical vacuum boundary condition it follows that
\begin{align*}
    u^i(t,\cdot) & \in C^{N+2}(\overline{\Omega_t}), \quad
    \partial_t u^i(t,\cdot) \in C^{N+1}(\overline{\Omega_t}),  
    \\
    \rho(t,\cdot) & \in C^{N+2}_{loc}(\Omega_t), \quad
    \partial_t \rho(t,\cdot) \in C^{N+1}_{loc}(\Omega_t),     
\end{align*}
again with higher time derivatives having regularity determined by the equations of motion as above. Crucially, these all refer to the regularity relative to rectangular coordinates in $\mathbb{R}^3$, which therefore implies the usual compatibility conditions at the origin for spherically symmetric solutions, so that 
the variables \eqref{ansatz radial symmetry} satisfy
\begin{align*}
    \partial_r^{2\ell+1} \rho(t,0) & = 0,\, 
    2\ell+1 \leq N+2,
    \\
    \partial_r^{2\ell}v(t,0) & = 0, \, 
    2\ell \leq N+2,
\end{align*}
The variables $\tilde{\rho}$ and $\tilde{v}$ in \eqref{defn:scaling} inherit the regularity of $\rho$ and $u^i$ and thus also satisfy the same compatibility conditions in $r$ at the origin. Thus we can summarize the regularity of the relevant variables as
\begin{subequations}{\label{E:Regularity_rescaled_symmetric_variables}}
\begin{align}
    \label{E:Regularity_rescaled_v}
   & \tilde{v}(t,\cdot) \in C^{N+2}([0,1]), \quad
    \partial_t \tilde{v}(t,\cdot) \in C^{N+1}([0,1]),  
    \\
    \label{E:Regularity_rescaled_rho}
    &\tilde{\rho}(t,\cdot)  \in C^{N+2}_{loc}([0,1)), \quad
    \partial_t \rho(t,\cdot) \in C^{N+1}_{loc}([0,1)), 
    \\
    \label{E:Regularity_rescaled_sound_speed}
    &\tilde{\rho^\kappa}(t,\cdot)  \in C^{N+2}([0,1]), \quad
    \partial_t \rho^\kappa(t,\cdot) \in C^{N+1}([0,1]), 
    \\
    \label{E:Regularity_rescaled_v_at_zero}
    & \partial_r^{2\ell}\tilde{v}(t,0)  = 0, \, 
    2\ell \leq N+2,
    \\
    \label{E:Regularity_rescaled_rho_at_zero}    
    &\partial_r^{2\ell+1} \tilde{\rho}(t,0)  = 0,\, 
    2\ell+1 \leq N+2,
\end{align}
\end{subequations}
and, again, each further time derivative costs another spatial derivative.

\medskip
\noindent\textbf{Step 5} (Regularity of $\eta_0$).
Define
\begin{subequations}{\label{E:Mass_functions}}
\begin{align}
    \label{E:Mass_function}
    m(\zeta) & := \int_0^\zeta \tilde{\rho}_0(z) z^2 dz,
    \\
    \label{E:Reference_mass_function}
    m_\text{ref}(\zeta) &:= \int_0^\zeta (\delta w(z))^\frac{1}{\kappa} z^2 dz.
\end{align}
\end{subequations}
We have that $m \colon [0,1] \rightarrow [0,m(1)]$ and $m_\text{ref} \colon [0,1] \rightarrow [0,m_\text{ref}(1)]$ are continuous and strictly increasing maps, thus invertible. By  \eqref{E:Reference_mass}, \eqref{E:Initial_mass}, and \eqref{E:Mass_constraint},
$m(1)=M=M_\text{ref}=m_\text{ref}(1)$, and therefore we have a well-defined orientation preserving homeomorphism
\begin{align*}
    &\eta_0 \colon [0,1] \rightarrow [0,1],
    \\
    & \eta_0(\zeta) := m^{-1}(m_\text{ref}(\zeta)).
\end{align*}

The expressions defining $m$ and $m_\text{ref}$ show that these quantities are differentiable. We further show below that $\eta_0$ is in fact a $C^{N+2}$ diffeomorphism, which then justifies the following step: differentiating the identity
\begin{align}
\label{E:Pre_gauge_identity_in_terms_of_masses}
    m(\eta_0(\zeta)) = m_\text{ref}(\zeta)
\end{align}
gives
\begin{align*}
    \tilde{\rho}_0(\eta_0(\zeta)) (\eta_0(\zeta))^2 \partial_\zeta \eta_0(\zeta) = (\delta w(\zeta))^\frac{1}{\kappa} \zeta^2,
\end{align*}
which is \eqref{gauge fixing} (recall \eqref{E:Jac_det_def}). 

An orientation preserving diffeomorphism $\hat{\eta}$ on $[0,1]$ must be increasing. If it satisfies \eqref{gauge fixing} (with $\hat{\eta}$ in place of $\eta_0$), then upon integration it must satisfy $m(\hat{\eta}(\zeta))=m_\text{ref}(\zeta)$, hence $\hat{\eta} = \eta_0$. This shows that in our setting the diffeomorphism given by Dacorogna--Moser \cite{dacorogna1990partial} in \eqref{gauge fixing} agrees with the one we just constructed.

By \eqref{E:Regularity_rescaled_rho} and Definition \ref{def: w}, we obtain that $m,m_\text{ref} \in C^{N+3}([\epsilon, 1-\epsilon])$ for any $\epsilon > 0$, and since $\partial_\zeta m(\zeta) > 0$, we have $m^{-1} \in C^{N+3}([\epsilon,1-\epsilon])$ by the inverse function theorem. Thus, $\eta_0 \in C^{N+3}([\epsilon,1-\epsilon])$ for any $\epsilon>0$, i.e., $\eta_0 \in C^{N+3}_{loc}((0,1))$.

Let us next investigate regularity at $\zeta=0$. By 
\eqref{E:Regularity_rescaled_rho} and \eqref{E:Regularity_rescaled_rho_at_zero} we have
\begin{align*}
    \tilde{\rho}_0(\zeta)=\sum_{\ell=0}^{\lfloor \frac{N+1}{2} \rfloor}  \frac{1}{(2\ell)!} \partial_\zeta^{2\ell} \tilde{\rho}(0) \zeta^{2\ell}
    +O(\zeta^{2 \lfloor \frac{N+1}{2} \rfloor+2}),
\end{align*}
so that
\begin{align}
    \label{E:Mass_function_near_zero}
    m(\zeta) = \frac{1}{3}\tilde{\rho}(0) \zeta^3 + \frac{1}{10}\partial_\zeta^2 \tilde{\rho}(0)\zeta^5 + \dots = \zeta^3 \mathsf{f}_m(\zeta^2),
\end{align}
for some function $\mathsf{f}_m$ that is $C^{N+2}$ in a neighborhood of $\zeta=0$ and satisfies $\mathsf{f}_m(0)=\frac{1}{3}\tilde{\rho}(0)>0$. Similarly, in view of the properties of $w$ stated in Definition \ref{def: w}, we have
\begin{align}
    \label{E:Reference_mass_function_near_zero}    
    m_\text{ref}(\zeta) = \zeta^3 \mathsf{f}_{m_\text{ref}}(\zeta^2)
\end{align}
for some function $\mathsf{f}_{m_\text{ref}}$ that is $C^{N+2}$ in a neighborhood of $\zeta=0$ and satisfies $\mathsf{f}_{m_\text{ref}}(0)>0$.

The maps $(m(\zeta))^\frac{1}{3}=\zeta (\mathsf{f}_m(\zeta^2))^\frac{1}{3}$ and $(m_\text{ref})^\frac{1}{3} = \zeta (\mathsf{f}_{m_\text{ref}}(\zeta^2))^\frac{1}{3}$ are $C^{N+2}$ in a neighborhood of $\zeta=0$ because $\mathsf{f}_m(0)>0$ and $\mathsf{f}_{m_\text{ref}}(0)>0$. Since 
\begin{align*}
    \left. \partial_\zeta [(m(\zeta))^\frac{1}{3}]\right|_{\zeta=0} = (\mathsf{f}_m(0))^\frac{1}{3}>0,
\end{align*}
by the inverse function theorem, $m^\frac{1}{3}$ is a $C^{N+2}$ diffeomorphism in a neighborhood of $\zeta=0$. But near zero we have that 
$(m(\eta_0(\zeta)))^\frac{1}{3} := (m_\text{ref}(\zeta))^\frac{1}{3}$ if and only if $m(\eta_0(\zeta)) := m_\text{ref}(\zeta)$, and we conclude that 
\begin{align}
    \label{E:eta_0_near_zero}
    \eta_0(\zeta) = (m^\frac{1}{3})^{-1}(m_\text{ref}(\zeta))^\frac{1}{3}),
\end{align}
thus $\eta_0$ is $C^{N+2}$ at $\zeta=0$.

We finally move to establish regularity at $\zeta=1$. Since $w(1)=0$, we can write, for $0<\zeta< 1$,
\begin{align*}
    w(1-\zeta) &= w(1-\zeta) - w(1) =\int_1^{1-\zeta} \partial_z w(z) dz
    \\
    & = \int_{1-\zeta}^1 (-\partial_z w(z) )dz
    \\
    & =
    \zeta \int_0^1 (-\partial_z w(1-\zeta z))dz,
\end{align*}
where we changed variables $z \mapsto 1-\zeta z$ in the last step. Thus we can write
\begin{align*}
    w_\delta(1-\zeta) = \zeta W_\delta(\zeta),
\end{align*}
where 
\begin{align*}
    W_\delta(\zeta) = \delta  \int_0^1 (-\partial_z w(1-\zeta z))dz
\end{align*}
is smooth in a neighborhood of $\zeta=0$. Since  $\partial_\zeta w(1) < 0$, we also have that $W_\delta$ is positive in a neighborhood of $\zeta=0$. Similarly, by the physical vacuum boundary condition and \eqref{E:Regularity_rescaled_sound_speed}, we can write 
\begin{align}
    \label{E:Identity_boundary_regularity_eta_0_1}
    \tilde{\rho}^\kappa_0(1-\zeta) = \zeta  R(\zeta),
\end{align}
where $R$ is $C^{N+2}$ and positive in a neighborhood of zero. Thus, there exists an $\epsilon>0$ such that $W_\delta,R \in C^{N+2}([0,\epsilon])$ and $W_\delta, R > 0$ on $[0,\epsilon]$. In what follows, we may need to shrink $\epsilon$ as we will be making several statements valid in a neighborhood of $\zeta=0$.

Introduce
\begin{subequations}{\label{E:Endpoint_mass_functions}}
\begin{align}
    \label{E:Endpoint_mass_function}    
    m^-(\zeta) & := \int_\zeta^1 \tilde{\rho}_0(z) z^2 dz,
    \\
    \label{E:Endpoint_reference_mass_function}     
    m^-_\text{ref}(\zeta) &:= \int_\zeta^1 (\delta w(z))^\frac{1}{\kappa} z^2 dz.
\end{align}
\end{subequations}
Then
\begin{align*}
     m^-(1-\zeta) & = \int_{1-\zeta}^1 (\tilde{\rho}^\kappa_0(z))^\frac{1}{\kappa} z^2 dz   
     \\
     &= \int_0^\zeta
     (\tilde{\rho}^\kappa_0(1-z))^\frac{1}{\kappa} (1-z)^2 dz
     \\
     &=
     \int_0^\zeta z^\frac{1}{\kappa} \tilde{R}(z) dz,
\end{align*}
where we used \eqref{E:Identity_boundary_regularity_eta_0_1}, changed variables $z\mapsto 1-z$ in the second step, and defined
\begin{align*}
    \tilde{R}(\zeta) := R^\frac{1}{\kappa}(\zeta)(1-\zeta)^2.
\end{align*}
By the above construction of $R$ in \eqref{E:Identity_boundary_regularity_eta_0_1}, we have that $\tilde{R}\in C^{N+2}([0,\epsilon])$ and $\tilde{R}>0$ on $[0,\epsilon ]$. 
Changing variables once more, $z \mapsto \zeta z$,
\begin{align*}
     m^-(1-\zeta) & = \zeta^{1+\frac{1}{\kappa}}
     \int_0^1 z^\frac{1}{\kappa} \tilde{R}(\zeta z) dz
     \\
     &=
     \zeta^{1+\frac{1}{\kappa}} \hat{R}(\zeta),
\end{align*}
where 
\begin{align*}
    \hat{R}(\zeta) :=     \int_0^1 z^\frac{1}{\kappa} \tilde{R}(\zeta z) dz
\end{align*}
belongs to $C^{N+2}([0,\epsilon])$ and is positive on $[0,\epsilon]$. Similarly, we can write
\begin{align*}
    m^-_\text{ref}(1-\zeta) = \zeta^{1+\frac{1}{\kappa}} \hat{W}_\delta(\zeta),
\end{align*}
where $\hat{W}_\delta \in C^{N+2}([0,\epsilon])$ and is positive on $[0,\epsilon]$.

Define
\begin{subequations}{\label{E:Endpoint_masses_to_a_power}}
\begin{align}
    \mathsf{m}^-(\zeta) & := (m^-(\zeta))^{\frac{\kappa}{1+\kappa}},
    \\
    \mathsf{m}^-_\text{ref}(\zeta) & := (m^-_\text{ref}(\zeta))^\frac{\kappa}{1+\kappa},
\end{align}
\end{subequations}
so that 
\begin{align*}
    \mathsf{m}^-(1-\zeta) = \zeta (\hat{R}(\zeta))^\frac{\kappa}{1+\kappa}.
\end{align*}
Because $\hat{R} \in C^{N+2}([0,\epsilon])$ and $\hat{R}(0) > 0$, we have that $\left. \partial_\zeta \mathsf{m}^-(1-\zeta)\right|_{\zeta=0} >0$. By the inverse function theorem, $\mathsf{m}^-(1-\zeta)$ is a $C^{N+2}$ diffeomorphism in a neighborhood of $\zeta=0$, or equivalently  $\mathsf{m}^-$ is a $C^{N+2}$ diffeomorphism in a neighborhood of $\zeta=1$. Similarly, $\mathsf{m}^-_\text{ref}$ is a $C^{N+2}$ diffeomorphism in a neighborhood of $\zeta=1$.

In view of the definitions \eqref{E:Masses_data}, \eqref{E:Mass_functions}, and \eqref{E:Endpoint_mass_functions}, we can write
\begin{subequations}{\label{E:Masses_and_endpoint_masses_relations}}
\begin{align}
    m^-(\zeta) &= M - m(\zeta),\\
    m^-_\text{ref}(\zeta) & = M_\text{ref} - m_\text{ref}(\zeta).
\end{align}
\end{subequations}
Identities \eqref{E:Pre_gauge_identity_in_terms_of_masses} and \eqref{E:Masses_and_endpoint_masses_relations} imply that $M-m^-(\eta_0(\zeta)) = M_\text{ref} - m^-_\text{ref}(\zeta)$, and thus
\begin{align}
    \label{E:Pre_gauge_identity_in_terms_of_endpoint_masses} 
    m^-(\eta_0(\zeta)) = m^-_\text{ref}(\zeta)    
\end{align}
in view of assumption \eqref{E:Mass_constraint}. Reciprocally, if \eqref{E:Pre_gauge_identity_in_terms_of_endpoint_masses} holds so does \eqref{E:Pre_gauge_identity_in_terms_of_masses} using again \eqref{E:Masses_and_endpoint_masses_relations}
and \eqref{E:Mass_constraint}.
In other words, \eqref{E:Pre_gauge_identity_in_terms_of_endpoint_masses} and \eqref{E:Masses_and_endpoint_masses_relations}
are equivalent, and since the latter holds by our construction of $\eta_0$ so does the former. Raising \eqref{E:Pre_gauge_identity_in_terms_of_endpoint_masses} to the power $\frac{\kappa}{1+\kappa}$ and invoking \eqref{E:Endpoint_masses_to_a_power}
gives
\begin{align}
    \mathsf{m}^-(\eta_0(\zeta)) = \mathsf{m}^-_\text{ref}(\zeta)    
\end{align}
By the foregoing, $\mathsf{m}^-$ and $\mathsf{m}_\text{ref}^-$ are $C^{N+2}$ diffeomorphisms in a neighborhood of $\zeta=1$, and thus is $\eta_0 = (\mathsf{m}^{-})^{-1} \circ \mathsf{m}^-_\text{ref}$. In particular $\eta_0 \in C^{N+2}([1-\epsilon,1])$. 

Considering the three regions investigated above, namely, a neighborhood of $\zeta=0$, a neighborhood of $\zeta=1$, and $(0,1)$, we conclude that $\eta_0 \in C^{N+2}([0,1])$ and $\eta_0^{-1} \in C^{N+2}([0,1])$.

\medskip
\noindent\textbf{Step 6} (Regularity of $(\Theta,\partial_\tau\Theta)$).
By \eqref{E:Regularity_rescaled_v} and \eqref{modvel}, we have $V(\tau,\cdot) \in C^{N+2}([0,1])$ and $\partial_\tau V(\tau,\cdot) \in C^{N+1}([0,1])$. We showed above that $\eta_0 \in C^{N+2}([0,1])$. Therefore,  by \eqref{E:d_eta_d_s},
we conclude that $\eta(\tau,\cdot)$ and $\partial_\tau\eta(\tau,\cdot)$ are in $C^{N+2}([0,1])$, and thus the same holds for $\Theta(\tau,\cdot)$ and $\partial_\tau\Theta(\tau,\cdot)$ in view of \eqref{E:Theta_def}, where we recall that the change of variables from $s$ to $\tau$ does not lose derivatives.

\medskip
\noindent\textbf{Step 7} (Center regularity of $(\Theta,\partial_\tau\Theta)$ and boundedness of $E^N$). We now show that $\Theta$ and $\partial_\tau \Theta$ are genuinely spherically symmetric functions. For this, we need to verify that they satisfy
\begin{align*}
    \partial_\zeta^{2\ell} \Theta(\tau,0) &=0, \, 2\ell \leq N+2, 
    \\
    \partial_\zeta^{2\ell} \partial_\tau \Theta(\tau,0) &=0, \, 2\ell \leq N+2.   
\end{align*}

We will refer to functions whose even derivatives vanish at $\zeta=0$ as odd, and those whose odd derivatives vanish at $\zeta=0$ as even. This is a slight abuse of notation in that our maps are not defined for $\zeta < 0$, but the important point is that the standard parity algebra $(\text{odd}) \cdot (\text{odd})= (\text{even})$, $(\text{odd}) \cdot (\text{even})= (\text{odd})$, etc., continues to hold. Here we are interested in parity in $\zeta$ for functions of $\tau$ and $\zeta$, while we will appeal to expressions of $s$ and $\zeta$ where $s$ is as in \eqref{defn:scaling}. The change from $s$ to $\tau$, however, does not affect the parity in $\zeta$.

Let us show that $V(\tau,\zeta)$ is an odd function of $\zeta$. Consider \eqref{modvel}. The term $\frac{\lambda^\prime}{\lambda}\zeta$ is odd, as is $\tilde{v}$ by \eqref{E:Regularity_rescaled_v_at_zero}. $u^0$ is even by \eqref{u00}. Thus, $V$ is odd.

From \eqref{E:Mass_function_near_zero},
\eqref{E:Reference_mass_function_near_zero}, and \eqref{E:eta_0_near_zero}, we have that near $\zeta=0$ we can write
\begin{align*}
    \eta_0(\zeta) = \zeta \mathbf{F}(\zeta^2),
\end{align*}
with $\mathbf{F}(0) \neq 0$,
where we used an invertible map of the form, $\mathbf{F}(\zeta^2)$, $\mathbf{F}(0) \neq 0$,  also has the form 
$\zeta \mathbf{F}(\zeta^2)$, $\mathbf{F}(0) \neq 0$ by Lemma \ref{L:Inverse_odd_function}. 
Thus, $\eta_0$ is odd.

$V$ being odd in $\zeta$, i.e., having all even derivatives vanishing at $\zeta=0$, implies that $V$ can be extended from $[0,1]$ to an odd function on $[-1,1]$ which is of the same regularity, $C^{N+2}$. Similarly for $\eta_0$. By \eqref{E:d_eta_d_s}, $\eta$ is the flow of an odd vector field with odd initial condition. A standard parity-preserving argument based on uniqueness shows that $\eta(\tau,\zeta)$ is then odd in $\zeta$. Upon restricting to $\zeta \in [0,1]$, we have $\partial_\zeta^{2\ell}\eta(\tau,0)=0$, $2\ell \leq N+2$. Thus the same holds for $\Theta(\tau,\zeta)$ by \eqref{E:Theta_def}.

For $\partial_\tau \Theta$, we use  \eqref{E:Theta_def} and \eqref{E:d_eta_d_s} to get
\begin{align*}
    \partial_\tau \Theta(\tau,\zeta) = \frac{ds}{d\tau} \partial_s \Theta(s,\zeta) = 
    \frac{ds}{d\tau} \partial_s \eta(s,\zeta)
    = \frac{ds}{d\tau} V(s,\eta(s,\zeta)),
\end{align*}
which is odd in $\zeta$.

For any odd function $\mathsf{f} \in C^{N+2}([0,1])$, Lemma \ref{L:calD_odd_functions} gives that
\begin{subequations}{\label{E:calDj_on_odd_functions}}
\begin{align}
    \mathcal{D}_{2\ell} \mathsf{f}(0) & = 0, \, 2\ell \leq N+2,
    \\
    \mathcal{D}_{2\ell+1} \mathsf{f}(0) & = \text{finite value }, \, 2\ell+1 \leq N+2,
\end{align}
\end{subequations}
and also a bound on the respective norms,
where we recall that $\mathcal{D}_\ell$ is given by 
\eqref{calDj}.

With \eqref{E:calDj_on_odd_functions} at hand and the regularity of $\Theta$ and $\partial_\tau \Theta$ established in Step 6, 
we then immediately obtain \eqref{E:Regularity_Theta_partial_tau_Theta_closed_time_interval}; \eqref{E:Finiteness_E_N_closed_time_interval} then follows from \eqref{E:Regularity_Theta_partial_tau_Theta_closed_time_interval} and Remark \ref{R:Norm_equivalence_calX_calE}.

This completes the proof of item 2) of the Theorem.

\medskip
\noindent\textbf{Step 8} (Perturbations of reference data give rise to small $E^N$ data). 
This is essentially the statement that our association $(\mathring{\mathsf{r}},\mathring{\mathsf{v}}^i)\mapsto (\Theta_0,U_0)$ is continuous at $(\mathsf{r}_\text{ref},\mathsf{v}_\text{ref}^i)$. We have already seen that this association is well defined, but now we need to be more quantitative about it.

Define the set 
\begin{align*}
    \mathcal{U} := \{ (\mathring{\mathsf{r}},\mathring{\mathsf{v}}^i) \in \mathcal{H}^{2k}_\text{ref} \, \, | \, \text{the construction of } (\Theta_0,U_0) \, \text{ out of } \, (\mathring{\mathsf{r}},\mathring{\mathsf{v}}^i) \,\text{ in Step 2 is well defined} \},
\end{align*}
and endow $\mathcal{U}$ with the topology inherited from $\mathcal{H}^{2k}_\text{ref}$. In practice, recall that the ingredients needed for $(\Theta_0,U_0)$ to be well defined are the physical vacuum boundary condition, the gauge fixing of $\eta_0$, subluminality, enough regularity for the variables, and the center-regularity conditions. 
These conditions are stable under convergence in $\mathcal{H}^{2k}_\text{ref}$ and thus $\mathcal{U}$ is open.
By construction, on $\mathcal{U}$ we have a well-defined Euler-to-Lagrangian data map $\mathbb{D} \colon (\mathring{\mathsf{r}},\mathring{\mathsf{v}}) \mapsto (\Theta_0,U_0)$ and we need to ascertain the continuity of this map, where the topology on the image is given by the $\mathcal{X}^N$ topology.

Let $\{ (\mathring{\mathsf{r}}_n,\mathring{\mathsf{v}}^i_n)\}_{n=0}^\infty \subset \mathcal{U}$ converge to $(\mathring{\mathsf{r}},\mathring{\mathsf{v}}^i)$.
By definition of convergence in $\mathcal{H}^{2k}_0$, we have that $\Omega_{\mathring{\mathsf{r}}_n}$ converges to $\Omega_{\mathring{\mathsf{r}}}$. Since 
$\Omega_{\mathring{\mathsf{r}}_n}=B_{\lambda_{0,n}}(0)$ and $\Omega_{\mathring{\mathsf{r}}}=B_{\lambda_0}(0)$ by spherical symmetry, we have $\lambda_{0,n} \rightarrow \lambda_0$. 

Set
\begin{align*}
    \mathring{\mathsf{r}}^L_n(\zeta) & := \mathring{\mathsf{r}}_n(\lambda_{0,n}\zeta),
    \\
    \mathring{\mathsf{r}}^L(\zeta) & := \mathring{\mathsf{r}}(\lambda_{0}\zeta),   \\
    (\mathring{\mathsf{v}}^L_n)^i(\zeta) & := \mathring{\mathsf{v}}_n^i(\lambda_{0,n}\zeta),\\ 
    (\mathring{\mathsf{v}}^L)^i(\zeta) & := \mathring{\mathsf{v}}^i(\lambda_{0}\zeta), 
\end{align*}
$\zeta \in [0,1]$. By definition of convergence in 
$\mathcal{H}^{2k}_0$, given $\epsilon$ we have a smooth $(\mathring{\mathsf{r}}_\text{smooth}, \mathring{\mathsf{v}}_\text{smooth}^i)$, which we can assume to be spherically symmetric (this is because the relevant domains and norms are invariant under $SO(3)$; if $(\mathring{\mathsf{r}}_\text{smooth}, \mathring{\mathsf{v}}_\text{smooth}^i)$ were not spherically symmetric, we could replace it by its $SO(3)$ average without worsening the approximation), defined in a neighborhood $B_{\lambda_\text{smooth}}(0)$ of $\Omega_{\mathring{\mathsf{r}}}$ such that
$\| (\mathring{\mathsf{r}},\mathring{\mathsf{v}}^i) - (\mathring{\mathsf{r}}_\text{smooth}, \mathring{\mathsf{v}}_\text{smooth}^i) \|_{\mathcal{H}^{2k}_{\mathring{\mathsf{r}}}(\Omega_{\mathring{\mathsf{r}}})} \leq \epsilon$ and
$\limsup_{n\rightarrow\infty}\| (\mathring{\mathsf{r}}_n,\mathring{\mathsf{v}}^i_n) - (\mathring{\mathsf{r}}_\text{smooth}, \mathring{\mathsf{v}}_\text{smooth}^i) \|_{\mathcal{H}^{2k}_{\mathring{\mathsf{r}}_n}(\Omega_{\mathring{\mathsf{r}}_n})} \leq \epsilon$. From this and the non-degeneracy of $\mathring{\mathsf{r}}_n$ it follows that 
\begin{align*}
    \| (\mathring{\mathsf{r}}^L,(\mathring{\mathsf{v}}^L)^i) - (\mathring{\mathsf{r}}^L_\text{smooth}, (\mathring{\mathsf{v}}^L)^i_\text{smooth}) \|_{\mathcal{H}^{2k}_{w}([0,1])} \lesssim \epsilon
\end{align*}
and
\begin{align*}
    \limsup_{n\rightarrow\infty}
    \| (\mathring{\mathsf{r}}^L_n,(\mathring{\mathsf{v}}^L_n)^i) - (\mathring{\mathsf{r}}^L_\text{smooth}, (\mathring{\mathsf{v}}^L)^i_\text{smooth}) \|_{\mathcal{H}^{2k}_{w}([0,1])} \lesssim \epsilon,
\end{align*}
where $\mathring{\mathsf{r}}^L_\text{smooth}(\zeta):=\mathring{\mathsf{r}}_\text{smooth}(\lambda_\text{smooth}\zeta)$ and $(\mathring{\mathsf{v}}^L)^i_\text{smooth}(\zeta) := \mathring{\mathsf{v}}_\text{smooth}^i(\lambda_\text{smooth}\zeta)$. This implies that $(\mathring{\mathsf{r}}^L_n,(\mathring{\mathsf{v}}^L_n)^i) \rightarrow (\mathring{\mathsf{r}}^L,(\mathring{\mathsf{v}}^L)^i)$ in $\mathcal{H}^{2k}_w([0,1])$.

From \eqref{E:New_sound_and_velocity} we can write $u^i = (1+\frac{\kappa}{1+\kappa}r)^{-(1+\frac{1}{\kappa})} \mathsf{v}^i$, so that $u^i$ is related to $\mathsf{v}^i$ by a smooth function of $\mathsf{r}$ that is uniformly bounded away from zero. Thus, for the Eulerian velocities $\mathring{u}^i$ and $\mathring{u}^i_n$ corresponding to $\mathring{\mathsf{v}}^i$ and $\mathring{\mathsf{v}}^i_n$, respectively, if we set $(\mathring{u}^L)^i(\zeta) := \mathring{u}^i(\lambda_{0}\zeta)$ and $(\mathring{u}^L_n)^i(\zeta) := \mathring{u}_n^i(\lambda_{0}\zeta)$, then we also have $(\mathring{\mathsf{r}}^L_n,(\mathring{u}^L_n)^i) \rightarrow (\mathring{\mathsf{r}}^L,(\mathring{u}^L)^i)$ in $\mathcal{H}^{2k}_w([0,1])$. By \eqref{E:N_k_relation} and \eqref{E:Weighted_embedding_DIT} we then obtain 
$(\mathring{\mathsf{r}}^L_n,(\mathring{u}^L_n)^i) \rightarrow (\mathring{\mathsf{r}}^L,(\mathring{u}^L)^i)$ in $C^{N+2}([0,1])$.

Next, by \eqref{E:New_sound_speed_sq} we have $\| \mathring{\rho}_n - \mathring{\rho} \|_{L^\infty(\mathbb{R})} \rightarrow 0$ (with $\mathring{\rho}_n,\mathring{\rho}$ extended to zero outside the domains). This combined with \eqref{defn:scaling} and the dominated convergence theorem gives that $m_n$ converges uniformly to $m$, where $m_n$ is \eqref{E:Mass_function} constructed out of $\mathring{\rho}_n$ and $m$ out of $\mathring{\rho}$. Each $m_n$ is strictly increasing and uniformly non-degenerate away from the end points, and therefore $m_n^{-1}$ also converges uniformly to $m^{-1}$. Thus, $\eta_{0,n} = m_n^{-1} \circ m_\text{ref}$ converges uniformly to $\eta_0 = m^{-1} \circ m_\text{ref}$. Analyzing the regularity and invertibility of $\eta_{0,n}$ near the endpoints and away from the endpoints as in Step 5, and recalling \eqref{E:N_k_relation}, we can show that in fact $\eta_{0,n} \rightarrow \eta_0$ in $C^{N+1}([0,1])$. From this, we then obtain $C^{N+1}([0,1])$ convergence of $\Theta_n := \eta_{0,n} - \zeta$ to $\Theta = \eta_0 -\zeta$. 

From the convergences already established, we can  obtain $C^{N+1}([0,1])$ convergence of $U_{0,n}(\zeta) := V_n(0,\eta_{0,n}(\zeta))$ to $U_0(\zeta) := V(0,\eta_0(\zeta))$, where $V_n$ and $V$ are given in terms of $\mathring{u}_n^i$ and $\mathring{u}^i$, respectively, and  \eqref{defn:scaling} in view of \eqref{modvel}.

Finally, as in Step 8, the center-regularity conditions ensure that the above $C^{N+1}([0,1])$ convergence implies $\mathcal{X}^N$ convergence and thus $E^N(0)$ convergence by Remark \ref{R:Norm_equivalence_calX_calE}. Recalling that $(\Theta_0,U_0)=(0,0)$ for the reference state, we obtain item 3) of the Theorem.

\medskip
\noindent\textbf{Step 9} (Continuation criterion). The solutions $(\Theta,\partial_\tau\Theta)$ to \eqref{eq:momlagmain} that we have constructed are obtained out of solutions $(\rho,u^i)$ to \eqref{eq:RE}, which in turn are obtained from the solutions $(\mathsf{r},\mathsf{v})$ obtained in \cite{disconzi2022relativistic}. The passage from $(\mathsf{r},\mathsf{v})$ to $(\rho,u^i)$ is given by \eqref{E:New_sound_and_velocity}, whereas the passage from $(\rho,u^i)$ to $(\Theta,\partial_\tau\Theta)$ is given by the procedure of Section \ref{sect: setup}, which we justified through Steps 1--3 above. From this procedure we have that if $(\mathsf{r},\mathsf{v})$ is defined on the time interval $[0,T^*)$ then $(\Theta,\partial_\tau\Theta)$ is defined on the time interval $[0,\tau^*)$, where $\tau^*$ is given by \eqref{E:Time_existence_Lagrangian}. Thus, if $(\mathsf{r},\mathsf{v})$ is defined instead on the time interval $[0,T^*+ \epsilon)$, $\epsilon > 0$, then $(\Theta,\partial_\tau\Theta)$ is defined on the time interval $[0,\tau^*+\epsilon^\prime)$, where $\epsilon^\prime$ is given by 
\begin{align*}
    \epsilon^\prime := \int_{T^*}^{T^*+\epsilon} \frac{1}{\lambda(t)} dt.
\end{align*}

By the continuation criterion established in \cite{disconzi2022relativistic}, a subluminal solution $(\mathsf{r},\mathsf{v})$ defined on $[0,T^*)$ and uniformly satisfying the physical vacuum boundary condition can be continued past $T^*$ if
\begin{align}
    \label{E:DIT_continuation_criterion}
    \sup_{0\leq t < T^*}
    \| (\mathsf{r},\mathsf{v})\|_{C^2(\Omega_t)} < \infty.
\end{align}
(The continuation criterion in \cite{disconzi2022relativistic} requires in fact control of a norm weaker than $C^2$, but $C^2$ suffices for our purposes.)
Therefore, in order to show item 4) of the Theorem, it suffices to show that under the bootstrap assumptions \eqref{bootstrap U0} and \eqref{bootstrap FG}, \eqref{E:Continuation_criterion_Lagrangian} implies \eqref{E:DIT_continuation_criterion}.

Recalling \eqref{E:U_0_Theta_and_bar_lambda}, we have the subluminality condition
\begin{align*}
  0 <  (U^0)^{-2} = 1 - (\partial_\tau \Theta + \bar{\lambda}_{\tau} (\Theta + \zeta))^2,  
\end{align*}
The bootstrap assumption \eqref{bootstrap U0} is stronger than subluminality, giving a uniform positive lower bound for $U^0$ on $[0,\tau^*)$, i.e., there exists a $C_0 >0$ such that 
\begin{align*}
    (U^0)^{-2} = 1 - (\partial_\tau \Theta + \bar{\lambda}_{\tau} (\Theta + \zeta))^2 \geq C_0
    \, \text{ on } [0,\tau^*).
\end{align*}

Recalling the computations surrounding \eqref{E:Jac_det_def}, we have
\begin{align}
    \mathcal{F} = \left(\frac{\eta}{\zeta}\right)^2\partial_\zeta\eta.
\end{align}
We showed in Step 7 that $\eta$ is odd in $\zeta$, thus $\eta(\tau,\zeta) = \zeta + O(\zeta^3)$ near $\zeta=0$ for $\tau \in [0,\tau^*)$. Therefore, 
the bootstrap assumption \eqref{bootstrap FG} on $\mathcal{F}$ gives that $\partial_\zeta \eta(\tau,\cdot)$ remains uniformly bounded away from zero and thus $\eta = \Theta + \zeta$ remains uniformly non-degenerate on $[0,\tau^*)$, i.e., there exists a $C_1>0$ such that
\begin{align}
    \label{E:eta_remains_diffeo_for_continuation_criterion}
    \partial_\zeta \eta = 1+\partial_\zeta \Theta \geq C_1 \, \text{ on } [0,\tau^*).
\end{align}
This, combined with 
\eqref{E:f_and_U_of_s}, 
\eqref{defn:scaling}, and the bootstrap assumption \eqref{bootstrap FG} on $\bar{\mathcal{G}}$, gives that there is no interior vacuum formation in the corresponding Eulerian variables solutions, i.e., if we define
\begin{align*}
    \overline{\Omega_{T^*} } &:=    \Big(\overline{  \bigcup_{0 \leq t < T^*} \{ t \} \times \Omega_t} \Big)\backslash
     \Big(\bigcup_{0 \leq t < T^*} \{ t \} \times \Omega_t \Big),
     \\
     \Omega_{T^*} &:=\text{interior}(\overline{\Omega_{T^*} }),
\end{align*}
then for each $x \in \Omega_{T^*}$, it holds that
\begin{align}
    \liminf_{t \rightarrow (T^{*})^-} \rho(t,x) > 0.
\end{align}
Furthermore, \eqref{E:eta_remains_diffeo_for_continuation_criterion} and  \eqref{bootstrap FG} also give that $f^\kappa(\tau,\zeta) \approx w_\delta(\zeta) \approx 1-\zeta$ uniformly over $[0,\tau^*)$, from which we conclude that the physical vacuum boundary condition is satisfied uniformly on the Eulerian variables over $[0,T^*)$, i.e., there exists $C_2>1$ such that for all $(t,x) \in \cup_{0 \leq t < T^*} \{ t \} \times \Omega_t$
\begin{align*}
    \frac{1}{C_2}\text{dist }(x,\partial\Omega_t) \leq c_s^2(t,x) \leq C_2 \text{dist }(x,\partial \Omega_t).
\end{align*}

With the above ingredients, we can now verify that \eqref {E:DIT_continuation_criterion} holds if \eqref{E:Continuation_criterion_Lagrangian} does so. We note that $\eta = \zeta + \Theta$ is $C^3$ if $\Theta$ is $C^3$; $\mathcal{F} = (\frac{\eta}{\zeta})^2 \partial_\zeta \eta = (1+\frac{\Theta}{\zeta})^2 (1+\partial_\zeta \Theta) $ is $C^2$ if $\Theta$ is $C^3$; $U=\lambda^{\frac{3}{2 }\kappa}\partial_\tau \Theta$ is $C^2$ if $\partial_\tau \Theta$ is $C^2$; $U^0 = 1 - (\partial_\tau \Theta + \bar{\lambda}_{\tau} (\Theta + \zeta))^2$ is $C^2$ if $\Theta$ is $C^2$ and $\partial_\tau \Theta$ is $C^2$. These observations combined with the fact that $\eta(\tau,\cdot) = \eta(\tau(t),\cdot) \colon [0,1] \rightarrow \Omega_t$, $\tau \in [0,\tau^*)$, is a diffeomorphism, imply the claim. This establishes item 4) of the Theorem.
